def to_dxf(model) -> bytes:
    _, c = to_svg(model)
    with tempfile.TemporaryDirectory() as td:
        f = pathlib.Path(td) / "s.dxf"
        render_dxf.render(c, str(f))
        return f.read_bytes()


PROFILE = deviz.DATE / "profile.json"


def citeste_profile():
    try:
        d = json.loads(PROFILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        d = {}
    return {"profile": d.get("profile") or [], "activ": d.get("activ")}


def scrie_profile(d):
    PROFILE.parent.mkdir(exist_ok=True)
    prof = [x for x in (d.get("profile") or []) if isinstance(x, dict) and x.get("nume")]
    activ = d.get("activ") if any(x["nume"] == d.get("activ") for x in prof) else None
    out = {"profile": prof, "activ": activ}
    PROFILE.write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
    return out


def _deviz(model_original, m):
    _, poz = layout.build_cu_pozitii(m)
    dv = model_original.get("deviz") or {}
    return deviz.calculeaza(poz, setari=dv.get("setari"), suprascrieri=dv.get("suprascrieri"), extra=dv.get("extra"))


def pachet_zip(model_original, m, r, name):
    """pachetul de predare: planșa (DXF, PDF, SVG), memoriul, lista, devizul și proiectul (JSON)"""
    import zipfile, io as _io
    bio = _io.BytesIO(); fis = []
    with zipfile.ZipFile(bio, "w", zipfile.ZIP_DEFLATED) as z:
        def add(fn, data, ce):
            z.writestr(fn, data); fis.append((fn, ce))
        add(name + ".dxf", to_dxf(m), "planșa, AutoCAD (DXF R2018, blocuri cu atribute)")
        svg, _ = to_svg(m); add(name + ".svg", svg, "planșa, vectorial")
        try:
            add(name + ".pdf", to_pdf(m), "planșa, PDF")
        except RuntimeError as e:
            fis.append(("(PDF lipsă)", str(e)))
        if r is not None:
            h = memoriu.genereaza_html(m, r)
            try:
                add(name + "_memoriu_de_calcul.pdf", html_to_pdf(h), "memoriul de calcul")
            except RuntimeError:
                add(name + "_memoriu_de_calcul.html", h, "memoriul de calcul (HTML)")
        _, poz = layout.build_cu_pozitii(m)
        add(name + "_lista_echipamente.xlsx", bom.bom_xlsx(m, poz), "lista de echipamente și materiale")
        dv = _deviz(model_original, m)
        add(name + "_deviz_estimativ.xlsx", deviz.deviz_xlsx(m, dv), "deviz estimativ (prețuri din catalog)")
        add(name + "_proiect.json", json.dumps(validare._fara_interne(model_original), ensure_ascii=False, indent=2),
            "proiectul — se redeschide în aplicație (Deschide)")
        k = m.get("cartus") or {}
        txt = [f"Pachet de predare — {k.get('denumire2', '')}", f"Beneficiar: {k.get('beneficiar', '')}",
               f"Planșa {k.get('plansa', '')} rev. {k.get('rev', '')} · faza {k.get('faza', '')}", ""]
        txt += [f"- {fn}: {ce}" for fn, ce in fis]
        if r is not None:
            ver = r.get("verificari") or []
            av = [v for v in ver if v.get("nivel") == "AVERTISMENT" and not v.get("confirmat")]
            ok = [v for v in ver if v.get("nivel") == "AVERTISMENT" and v.get("confirmat")]
            txt += ["", "STAREA VERIFICĂRILOR", "- erori blocante: 0 (altfel pachetul nu se generează)",
                    f"- atenționări de verificat: {len(av)}" + (": " + "; ".join(f"{v['cod']} {v['obiect']}" for v in av[:12]) if av else ""),
                    f"- atenționări analizate și acceptate de proiectant: {len(ok)}"]
            pres = r.get("presupus") or []
            if pres:
                txt += ["", "VALORI PRESUPUSE — DE CONFIRMAT CU ATR-UL / MĂSURĂTORI"] + [f"- {x}" for x in pres]
        rc = dv["recapitulatie"]
        txt += ["", "DEVIZ", f"- total cu TVA: {rc['total']:,.2f} {dv['setari'].get('moneda', 'lei')}".replace(",", " ").replace(".", ",")]
        if rc["fara_pret"]:
            txt += [f"- ATENȚIE: {rc['fara_pret']} articole nu au preț în catalog — totalul e incomplet."]
        if rc.get("fara_ore"):
            txt += [f"- {rc['fara_ore']} articole nu au ore de manoperă."]
        miss = [n for kk, n in (("proiectant", "firma de proiectare"), ("beneficiar", "beneficiar"), ("nr_pr", "nr. proiect"), ("data", "data")) if not k.get(kk)]
        if miss:
            txt += ["", "CARTUȘ INCOMPLET: " + ", ".join(miss)]
        z.writestr("CITESTE.txt", "\n".join(txt))
    return bio.getvalue()


def _fara_uid(o):
    """scoate cheile interne ale interfeței (_uid etc.) înainte de export"""
    if isinstance(o, dict): return {k: _fara_uid(v) for k, v in o.items() if not k.startswith("_")}
    if isinstance(o, list): return [_fara_uid(v) for v in o]
    return o


class H(BaseHTTPRequestHandler):
    def _send(self, code, body, ctype="application/json; charset=utf-8", fname=None, extra=None):
        if isinstance(body, str): body = body.encode("utf-8")
        self.send_response(code)
        for k, v in (extra or {}).items(): self.send_header(k, str(v))
        self.send_header("Content-Type", ctype); self.send_header("Content-Length", str(len(body)))
        if fname: self.send_header("Content-Disposition", f"attachment; filename*=UTF-8''{urllib.parse.quote(fname)}")
        self.end_headers(); self.wfile.write(body)

    def _json(self):
        n = int(self.headers.get("Content-Length", 0))
        return json.loads(self.rfile.read(n) or b"{}")

    def do_GET(self):
        p = urllib.parse.urlparse(self.path).path
        if p in ("/", "/index.html"):
            return self._send(200, (ROOT / "static" / "index.html").read_bytes(), "text/html; charset=utf-8")
        if p == "/api/presets":       # compatibilitate: modelele vechi desenate manual
            return self._send(200, json.dumps({k: {"nume": v[0], "model": v[1]} for k, v in presets.PRESETS.items()}, ensure_ascii=False))
        if p == "/api/sabloane":
            return self._send(200, json.dumps({k: {"nume": v[0], "descriere": v[1], "calc": v[2]} for k, v in SABLOANE.items()}, ensure_ascii=False))
        if p == "/api/info":
            try:
                import anthropic, os  # noqa
                claude = bool(os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("ANTHROPIC_AUTH_TOKEN") or os.path.exists(os.path.expanduser("~/.config/anthropic")))
            except ImportError:
                claude = False
            return self._send(200, json.dumps({"claude": claude, "pdf": bool(CHROME)}))
        if p == "/api/preturi":
            return self._send(200, json.dumps(deviz.citeste_catalog(), ensure_ascii=False))
        if p == "/api/profile":
            return self._send(200, json.dumps(citeste_profile(), ensure_ascii=False))
        if p == "/api/symbols":
            return self._send(200, json.dumps([{"cheie": k, "nume": v[1], "categorie": v[2]} for k, v in symbols.SYMBOLS.items()], ensure_ascii=False))
        if p.startswith("/static/"):
            f = ROOT / p.lstrip("/")
            if f.exists() and f.resolve().is_relative_to((ROOT / "static").resolve()):
                ct = {".css": "text/css", ".js": "application/javascript", ".svg": "image/svg+xml", ".png": "image/png", ".woff2": "font/woff2"}.get(f.suffix, "application/octet-stream")
                return self._send(200, f.read_bytes(), ct)
        self._send(404, "not found", "text/plain")

    def _blocat(self, v):
        return self._send(409, json.dumps({"eroare": "Exportul este blocat: schema are verificări neîndeplinite.",
                                           "verificari": [x for x in v["verificari"] if x.get("nivel") == "BLOCANT"]}, ensure_ascii=False))

    def do_POST(self):
        p = urllib.parse.urlparse(self.path).path
        if p == "/api/preturi/import":       # corp = fișierul Excel (binar)
            try:
                n = int(self.headers.get("Content-Length", 0))
                nou = deviz.importa_xlsx(self.rfile.read(n))
                d = deviz.scrie_catalog(nou)
                return self._send(200, json.dumps({"importate": len(nou["articole"]), "total": len(d["articole"]),
                                                   "sarite": nou.get("sarite", [])}, ensure_ascii=False))
            except ValueError as e:
                return self._send(400, json.dumps({"eroare": str(e)[:1].upper() + str(e)[1:] + "."}, ensure_ascii=False))
            except Exception:
                return self._send(400, json.dumps({"eroare": "Fișierul nu e un Excel .xlsx valid. Salvează lista de prețuri ca .xlsx "
                                                   "(nu .xls / .csv / .pdf) și încearcă din nou."}, ensure_ascii=False))
        try:
            try:
                model = self._json()
            except (ValueError, UnicodeDecodeError):
                return self._send(400, json.dumps({"eroare": "Corpul cererii nu e JSON valid."}, ensure_ascii=False))
            if not isinstance(model, dict):
                return self._send(400, json.dumps({"eroare": "Corpul cererii trebuie să fie un obiect JSON."}, ensure_ascii=False))
            for k in ("calc", "model", "cartus"):
                if model.get(k) is not None and not isinstance(model.get(k), dict):
                    return self._send(400, json.dumps({"eroare": f"„{k}” trebuie să fie un obiect JSON."}, ensure_ascii=False))
            for d in (model, model.get("model") if isinstance(model.get("model"), dict) else None):
                if d and isinstance(d.get("cartus"), dict):        # cartușul e text: numere / null → șiruri
                    d["cartus"] = {k: ("" if v is None else v if isinstance(v, str) else str(v)) for k, v in d["cartus"].items()}
            name = ((model.get("cartus") or {}).get("plansa", "E01") + "_" + ((model.get("cartus") or {}).get("denumire2") or "Schema monofilara"))[:80]
            if p == "/api/preview":
                m, _ = validare.pregateste(model)
                svg, _ = to_svg(m); return self._send(200, svg, "image/svg+xml; charset=utf-8")
            if p == "/api/valideaza":
                v = validare.valideaza(model)
                return self._send(200, json.dumps(v, ensure_ascii=False, default=str))
            if p == "/api/genereaza":
                # body: {calc: intrare fizică, model: modelul curent (pentru cartuș / setări)}
                m, r = constructor.genereaza(model.get("calc") or {}, pastreaza=model.get("model"))
                if (model.get("model") or {}).get("note_manuale"):
                    m["note_manuale"] = model["model"]["note_manuale"]
                v = validare.valideaza(m)
                return self._send(200, json.dumps({"model": m, "validare": v}, ensure_ascii=False, default=str))
            if p == "/api/preturi":
                try:
                    return self._send(200, json.dumps(deviz.scrie_catalog(model), ensure_ascii=False))
                except ValueError as e:
                    return self._send(400, json.dumps({"eroare": str(e)}, ensure_ascii=False))
            if p == "/api/profile":
                return self._send(200, json.dumps(scrie_profile(model), ensure_ascii=False))
            if p == "/api/deviz":            # previzualizarea devizului (și pentru schemele blocate, marcat)
                m, r = validare.pregateste(model)
                try:
                    out = _deviz(model, m)
                except ValueError as e:
                    return self._send(400, json.dumps({"eroare": str(e)}, ensure_ascii=False))
                out["blocat"] = validare.valideaza(model)["blocheaza"]
                return self._send(200, json.dumps(out, ensure_ascii=False, default=str))
            if p == "/api/export/json":
                return self._send(200, json.dumps(validare._fara_interne(model), ensure_ascii=False, indent=2), "application/json; charset=utf-8", name + ".json")
            if p.startswith("/api/export/"):
                v = validare.valideaza(model)
                if v["blocheaza"]:
                    return self._blocat(v)
                m, r = validare.pregateste(model, pentru_export=True)
                if p == "/api/export/svg":
                    svg, _ = to_svg(m); return self._send(200, svg, "image/svg+xml; charset=utf-8", name + ".svg")
                if p == "/api/export/dxf":
                    return self._send(200, to_dxf(m), "application/dxf", name + ".dxf")
                if p == "/api/export/pdf":
                    return self._send(200, to_pdf(m), "application/pdf", name + ".pdf")
                if p == "/api/export/xlsx":
                    _, poz = layout.build_cu_pozitii(m)
                    return self._send(200, bom.bom_xlsx(m, poz), "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", name + "_BOM.xlsx")
                if p in ("/api/export/deviz", "/api/export/pachet"):
                    try:
                        dvz = _deviz(model, m)
                        hdr = {"X-Deviz-Fara-Pret": dvz["recapitulatie"]["fara_pret"], "Access-Control-Expose-Headers": "X-Deviz-Fara-Pret"}
                    except ValueError as e:
                        return self._send(400, json.dumps({"eroare": "Devizul are date greșite: " + str(e)}, ensure_ascii=False))
                if p == "/api/export/deviz":
                    return self._send(200, deviz.deviz_xlsx(m, dvz),
                                      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", name + "_deviz.xlsx", extra=hdr)
                if p == "/api/export/pachet":
                    return self._send(200, pachet_zip(model, m, r, name), "application/zip", name + "_pachet.zip", extra=hdr)
                if p == "/api/export/memoriu":
                    if r is None:
                        return self._send(400, json.dumps({"eroare": "Memoriul de calcul există doar pentru schemele generate din calcul."}, ensure_ascii=False))
                    h = memoriu.genereaza_html(m, r)
                    try:
                        return self._send(200, html_to_pdf(h), "application/pdf", name + "_memoriu.pdf")
                    except RuntimeError:
                        return self._send(200, h, "text/html; charset=utf-8", name + "_memoriu.html")
            if p == "/api/memoriu":       # memoriul se poate vedea oricând, inclusiv cu verificări blocante
                m, r = validare.pregateste(model)
                if r is None:
                    return self._send(400, json.dumps({"eroare": "Memoriul de calcul există doar pentru schemele generate din calcul."}, ensure_ascii=False))
                return self._send(200, memoriu.genereaza_html(m, r), "text/html; charset=utf-8")
            if p == "/api/dimensionare":
                r = dimensioneaza_ramura_simpla(model)
                return self._send(200, json.dumps(r, ensure_ascii=False, default=str))
            if p == "/api/chat":
                it = interpretor.interpreteaza(model.get("text", ""), foloseste_llm=bool(model.get("claude")))
                out = {"interpretare": {k: it.get(k) for k in ("actiune", "tip_schema", "presupus", "intrebari", "refuz_cod", "refuz_motiv",
                                                               "intelegere", "avertismente", "motor", "intrare_fizica", "cartus")}}
                if it.get("actiune") != "refuza" and it.get("intrare_fizica"):
                    cart = {}
                    c = it.get("cartus") or {}
                    if c.get("beneficiar"): cart["beneficiar"] = c["beneficiar"]
                    adr = c.get("adresa")
                    if isinstance(adr, dict) and adr.get("localitate"):
                        cart["adresa"] = f"{adr['localitate']}" + (f", jud. {adr['judet']}" if adr.get("judet") else "")
                    elif isinstance(adr, str) and adr: cart["adresa"] = adr
                    for kk in ("plansa", "faza"):
                        if c.get(kk): cart[kk] = c[kk]
                    m, r = constructor.genereaza(it["intrare_fizica"], cartus=cart, pastreaza=model.get("model"))
                    v = validare.valideaza(m)
                    out.update({"model": m, "validare": v})
                return self._send(200, json.dumps(out, ensure_ascii=False, default=str))
        except (TypeError, AttributeError, KeyError, ValueError, IndexError) as e:
            import traceback; traceback.print_exc()          # formă neașteptată a datelor primite → 400, fără text Python
            return self._send(400, json.dumps({"eroare": "Datele trimise au un câmp de tip neașteptat (ex. text în loc de obiect / listă). "
                                                         f"Verifică proiectul (.json). [{type(e).__name__}]"}, ensure_ascii=False))
        except Exception as e:
            import traceback; traceback.print_exc()
            return self._send(500, json.dumps({"eroare": "Eroare internă a aplicației — " + type(e).__name__}, ensure_ascii=False))
        self._send(404, "not found", "text/plain")

    def log_message(self, fmt, *args):
        sys.stderr.write("%s %s\n" % (self.command, self.path))


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else PORT
    print(f"Schema monofilară — http://localhost:{port}")
    ThreadingHTTPServer(("127.0.0.1", port), H).serve_forever()

engine/calc/cabluri.py:
"""cabluri.py — curentul admisibil corectat (SPEC §B.7), căutarea secțiunii și cablurile în paralel (§B.8, §B.9),
neutrul (§B.10), conductorul PE (§B.11) și căderea de tensiune (§B.12)."""
import math

from . import norme
from .comun import ge, gt, SQRT3, UN, U0


class InAfaraTabelelor(Exception):
    """Pozare în afara tabelelor B.52.x (SPEC §B.7.2 → V10 BLOCANT)."""

    def __init__(self, parametru, tabel):
        """Reține parametrul și tabelul depășit, pentru mesajul V10 (SPEC §B.7.2, §D)."""
        super().__init__(parametru)
        self.parametru = parametru
        self.tabel = tabel


def theta_implicit(metoda):
    """SPEC §B.0: temperatura de referință — aer 30 °C, sol 20 °C."""
    return 20.0 if metoda in norme.METODE_IN_PAMANT else 30.0


def factori(izolatie, metoda, theta, rho_sol, n_circuite, distanta="atingere", aranjament=None):
    """SPEC §B.7.2: kθ (B.52.14/B.52.15), ksol (B.52.16, doar D1/D2), kgrup (B.52.17–B.52.19) pentru n_circuite
    = n_paralel + n_alte. Valorile intermediare iau rândul imediat superior; în afara tabelelor → InAfaraTabelelor."""
    try:
        kt = norme.k_temperatura(izolatie, metoda, theta)
    except ValueError:
        raise InAfaraTabelelor(f"temperatura {theta} °C", "B.52.14/B.52.15")
    try:
        ks = norme.k_rezistivitate_sol(metoda, rho_sol)
    except ValueError:
        raise InAfaraTabelelor(f"rezistivitatea termică a solului {rho_sol} K·m/W", "B.52.16")
    try:
        kg = norme.k_grupare(metoda, n_circuite, distanta, aranjament)
    except ValueError:
        raise InAfaraTabelelor(f"{n_circuite} circuite grupate", "B.52.17–B.52.19")
    return kt, ks, kg


def n_incarcate(retea):
    """SPEC §B.7.1: 3 conductoare încărcate la trifazat, 2 la monofazat."""
    return 2 if retea == "mono" else 3


def s_min(material, receptor, metoda):
    """SPEC §B.8, secțiunile minime: Cu iluminat 1,5; prize/forță/motor/invertor 2,5; coloane spre tablouri 4;
    orice cablu în pământ ≥ 6 (DECIZIE); Al ≥ 16."""
    if material == "Al":
        return norme.S_MIN_AL
    s = norme.S_MIN_CU.get(receptor if receptor != "pcs" else "invertor", 2.5)
    if metoda in norme.METODE_IN_PAMANT:
        s = max(s, norme.S_MIN_CU["ingropat"])
    return s


def metoda_implicita(cab, valoare):
    """Setează metoda de pozare implicită și marchează că NU a fost cerută de utilizator (v1.2 R3, N3-C1)."""
    if cab.get("metoda") is None:
        cab["metoda"] = valoare
        cab["metoda_implicit"] = True
    return cab["metoda"]


def monopolar(c):
    """True pentru cablurile monopolare: metoda F (aer) sau sisteme monopolare în pământ (D1/D2) — v1.2 R2/R3."""
    return bool(c.get("monopolar")) or str(c.get("metoda", "")).startswith("F")


def sectiuni(c):
    """Secțiunile disponibile pentru configurația cablului: multipolar (≤ 240) sau monopolar (25…300 mm²)."""
    return norme.SECTIUNI_MONOPOLAR if monopolar(c) else norme.SECTIUNI_MULTIPOLAR[c["material"]]


def n_max(c):
    """Numărul maxim de cabluri / sisteme în paralel: 4 multipolare (§B.8), 6 sisteme monopolare (v1.2 R2)."""
    return norme.N_PARALEL_MAX_MONOPOLAR if monopolar(c) else norme.N_PARALEL_MAX_MULTIPOLAR


def iz_corectat(c, n, S):
    """SPEC §B.7: Iz' = n·Iz·kθ·kgrup·ksol. `c` este configurația cablului (material, izolatie, metoda, retea, theta,
    rho_sol, n_alte, distanta, aranjament). Returnează (Iz_tabel, k_total, Iz')."""
    iz = norme.iz_tabel(c["material"], c["izolatie"], c["metoda"], n_incarcate(c["retea"]), S)
    kt, ks, kg = factori(c["izolatie"], c["metoda"], c["theta"], c["rho_sol"], n + c["n_alte"],
                         c["distanta"], c.get("aranjament"))
    if str(c["metoda"]).startswith("F"):
        # sisteme în treflă pe pat perforat, distanțate ≥ 2·De (B.52.21) — v1.2 R2
        nt = n + c["n_alte"]
        if nt > max(norme.K_GRUP_F_DISTANTAT):
            raise InAfaraTabelelor(f"{nt} sisteme monopolare grupate", "B.52.21")
        kg = norme.K_GRUP_F_DISTANTAT[nt]
    k = kt * ks * kg
    if iz is None:
        raise InAfaraTabelelor(f"secțiunea {S} mm² {c['material']} {c['izolatie']} metoda {c['metoda']}", "B.52.x")
    return iz, k, n * iz * k


def cauta(c, iz_min, smin):
    """SPEC §B.8, algoritmul de căutare: pentru n = 1…4, S crescător ≥ S_min: prima (n, S) cu n·Iz(S)·k ≥ Iz_min."""
    for n in range(1, n_max(c) + 1):
        for S in sectiuni(c):
            if S < smin - 1e-9:
                continue
            _, _, izp = iz_corectat(c, n, S)
            if ge(izp, iz_min):
                return n, S
    return None


def cea_mai_mica_s(c, n, iz_min, smin):
    """SPEC §B.12: „S = cea mai mică secțiune care satisface Iz_min la n” (pentru trecerea la n+1 cabluri)."""
    for S in sectiuni(c):
        if S < smin - 1e-9:
            continue
        if ge(iz_corectat(c, n, S)[2], iz_min):
            return S
    return None


def r_regim(material, izolatie, S):
    """SPEC §B.12: R' = R20(S)·[1 + α·(θ − 20)], θ = 70 °C PVC / 90 °C XLPE [Ω/km]."""
    return norme.r_la_temperatura(norme.R20_OHM_KM[material][float(S)], material, norme.THETA_MAX_C[izolatie])


def du_pct(retea, ib, L_m, material, izolatie, S, n, cosfi):
    """SPEC §B.12: ΔU% = 100·√3·Ib·L·(R'cosφ + X'sinφ)/400 (tri) sau 100·2·Ib·L·(…)/230 (mono); R', X' împărțite la n."""
    r = r_regim(material, izolatie, S) / n
    x = norme.X_CABLU_OHM_KM / n
    sinfi = math.sqrt(max(0.0, 1 - cosfi ** 2))
    Lk = L_m / 1000.0
    if retea == "mono":
        return 100.0 * 2 * ib * Lk * (r * cosfi + x * sinfi) / U0
    return 100.0 * SQRT3 * ib * Lk * (r * cosfi + x * sinfi) / UN


def sectiune_std_minima(valoare, minim=0.0):
    """Cea mai mică secțiune standard (SECTIUNI_STD) ≥ max(valoare, minim) (SPEC §B.11, §B.17)."""
    v = max(valoare, minim)
    for s in norme.SECTIUNI_STD:
        if ge(s, v):
            return s
    return None


def neutru_redus_permis(material, S, receptor, h3_pct):
    """SPEC §B.10 pct. 4: N redus permis numai dacă h3 declarat ≤ 15 %, receptorul nu e invertor / iluminat (LED) /
    VFD, S > 16 Cu / > 25 Al, N ≥ 16 Cu / ≥ 25 Al și combinația există. Returnează (N | None, motiv)."""
    if h3_pct is None:
        return None, "armonica 3 nedeclarată ≤ 15 %"
    if h3_pct > 15:
        return None, f"armonica 3 = {h3_pct} % > 15 %"
    if receptor in ("invertor", "pcs", "iluminat"):
        return None, "receptor invertor / iluminat LED / VFD"
    if not gt(S, norme.N_REDUS_S_FAZA_MIN[material]):
        return None, f"S ≤ {int(norme.N_REDUS_S_FAZA_MIN[material])} mm² {material}"
    N = norme.COMBINATII_N_REDUS.get(float(S))
    if N is None:
        return None, "combinație nefabricată"
    if N < norme.N_REDUS_S_N_MIN[material] - 1e-9:
        return None, f"N < {int(norme.N_REDUS_S_N_MIN[material])} mm² {material}"
    return N, ""


def compune_neutru(material, S, retea, receptor, h3_pct, N_fortat=None):
    """SPEC §B.10: secțiunea neutrului. Monofazat N = S; implicit N = S; redus doar cu condițiile pct. 4.
    Returnează (N, eroare_V25 | None)."""
    if retea == "mono":
        return S, None
    if N_fortat is not None:
        if N_fortat >= S - 1e-9:
            return float(N_fortat), None
        Nperm, motiv = neutru_redus_permis(material, S, receptor, h3_pct)
        if Nperm is not None and N_fortat >= Nperm - 1e-9:
            return float(N_fortat), None
        return float(N_fortat), motiv or "combinație nepermisă"
    if material == "Cu" and S <= 35:
        return S, None
    Nr, _ = neutru_redus_permis(material, S, receptor, h3_pct)
    return (Nr if Nr is not None else S), None


def s_pe_tabel(material, izolatie, n, S, pe_cupru_separat):
    """SPEC §B.11, tab. 54.2 pe S_tot = n·S; dacă faza e Al și PE e Cu: S_tab·k_faza(Al, izolație)/143."""
    s_tab = norme.s_pe_tabel(n * S)
    if material == "Al" and pe_cupru_separat:
        s_tab = s_tab * norme.K_FAZA[("Al", izolatie)] / norme.K_PE_SEPARAT[("Cu", "PVC")]
    return s_tab


def pe_in_cablu(material, S, retea):
    """SPEC §B.11, compunere: monofazat → PE în cablu (3×S); trifazat Cu S ≤ 35 → 5×S; altfel PE separat FY."""
    return retea == "mono" or (material == "Cu" and S <= 35 + 1e-9)


def compune_pe(material, izolatie, n, S, retea):
    """SPEC §B.11: (S_PE pe cablu, loc 'cablu'|'separat', S_tab) — PE separat = cea mai mică secțiune standard
    ≥ max(S_tab/n; 4 mm²)."""
    if pe_in_cablu(material, S, retea):
        return float(S), "cablu", s_pe_tabel(material, izolatie, n, S, False)
    s_tab = s_pe_tabel(material, izolatie, n, S, True)
    s_pe = sectiune_std_minima(s_tab / n, norme.S_MIN_PE_SEPARAT["neprotejat"])
    return s_pe, "separat", s_tab


def k_pe(material, izolatie, loc):
    """SPEC §B.11, tabelul k: PE în cablu → k după tab. A.54.3 (= k fază); PE separat FY Cu PVC → 143."""
    if loc in ("cablu", "PEN"):
        return norme.K_PE_IN_CABLU[(material, izolatie)]
    return norme.K_PE_SEPARAT[("Cu", "PVC")]


def r20_pe(material, loc, s_pe):
    """Rezistența la 20 °C a conductorului PE (în cablu: materialul fazei; separat: FY Cu) [Ω/km] (SPEC §B.14)."""
    mat = material if loc in ("cablu", "PEN") else "Cu"
    tab = norme.R20_OHM_KM[mat]
    if float(s_pe) in tab:
        return tab[float(s_pe)]
    return norme.RHO20[mat] * 1000.0 / s_pe

engine/calc/comun.py:
"""comun.py — utilitare comune motorului de dimensionare (comparații cu toleranță, serii, jurnalul de calcul).

Implementează regula SPEC §B.22: calculele se fac în virgulă mobilă, fără rotunjiri intermediare,
iar comparațiile se fac cu toleranța 1e-9.
"""
import math

from . import norme

EPS = 1e-9
SQRT3 = norme.SQRT3
UN = norme.U_N_V
U0 = norme.U_0_V


def _tol(a, b):
    """Toleranța de comparare (SPEC §B.22): 1e-9, relativ la mărimea operanzilor (cel puțin absolut 1e-9)."""
    return EPS * max(1.0, abs(a), abs(b))


def ge(a, b):
    """a ≥ b cu toleranță (SPEC §B.22)."""
    return a >= b - _tol(a, b)


def gt(a, b):
    """a > b cu toleranță (SPEC §B.22)."""
    return a > b + _tol(a, b)


def le(a, b):
    """a ≤ b cu toleranță (SPEC §B.22)."""
    return ge(b, a)


def lt(a, b):
    """a < b cu toleranță (SPEC §B.22)."""
    return gt(b, a)


def eq(a, b):
    """a = b cu toleranță (SPEC §B.22)."""
    return abs(a - b) <= _tol(a, b)


def prima_din_serie(serie, valoare):
    """Cea mai mică valoare din serie ≥ valoare (SPEC §B.4/§B.5 pct. 1), sau None dacă nu există."""
    for s in sorted(serie):
        if ge(s, valoare):
            return s
    return None


def vecini(serie, valoare):
    """Valorile din serie imediat sub și imediat peste o valoare inexistentă (remedierea V05, SPEC §D)."""
    s = sorted(serie)
    jos = [x for x in s if x < valoare]
    sus = [x for x in s if x > valoare]
    return (jos[-1] if jos else None, sus[0] if sus else None)


def modul(z):
    """|Z| pentru Z = (R, X) [Ω] (SPEC §B.13/§B.14)."""
    return math.hypot(z[0], z[1])


def u_calcul(retea):
    """Tensiunea de calcul a curentului: √3·400 V la trifazat, 230 V la monofazat (SPEC §A.1, §B.2)."""
    return SQRT3 * UN if retea == "tri" else U0


class Jurnal:
    """Colectorul rezultatelor de verificare (SPEC §D: {cod, nivel, obiect, mesaj, remediere}), al valorilor
    implicite folosite (SPEC §B.0 / V11), al pașilor de calcul (SPEC §H.3) și al ipotezelor (SPEC §G.2)."""

    def __init__(self):
        """Jurnal gol pentru o schemă (SPEC §D, §B.0, §G.2)."""
        self.verificari = []
        self.info = []
        self._presupus = []          # [(text, [elemente])], în ordinea declarării
        self.pasi = []
        self.ipoteze_folosite = {}

    def emite(self, cod, nivel, obiect, mesaj, remediere=""):
        """Adaugă un rezultat de verificare în ordinea producerii (SPEC §D)."""
        if nivel == "INFO":
            self.info.append({"cod": cod, "nivel": "INFO", "obiect": obiect, "mesaj": mesaj})
        else:
            self.verificari.append({"cod": cod, "nivel": nivel, "obiect": obiect, "mesaj": mesaj,
                                    "remediere": remediere})

    def presupune(self, text, element=None):
        """Declară o valoare implicită folosită (SPEC §B.0, „toate se declară”; V11). Declarațiile repetate pentru
        mai multe ramuri se grupează: „lungime plecări 50 m (P1·A, P2·B)”."""
        from .texte import curata_text
        text = curata_text(text)
        for t, el in self._presupus:
            if t == text:
                if element is not None and element not in el:
                    el.append(element)
                return
        self._presupus.append((text, [element] if element is not None else []))

    @property
    def presupus(self):
        """Lista valorilor implicite folosite, în română (SPEC §F.6 „Am presupus: …”)."""
        return [f"{t} ({', '.join(el)})" if el else t for t, el in self._presupus]

    def pas(self, text):
        """Adaugă un pas de calcul pentru memoriul de calcul (SPEC §H.3)."""
        self.pasi.append(text)

    def ipoteza(self, cheie, valoare, implicit):
        """Reține o ipoteză efectiv folosită, pentru nota G.2 (SPEC §G.2)."""
        lst = self.ipoteze_folosite.setdefault(cheie, [])
        if (valoare, implicit) not in lst:
            lst.append((valoare, implicit))

    def are_blocant(self, de_la=0):
        """True dacă există un BLOCANT emis după indexul `de_la` (SPEC §D, „BLOCANT = exportul este refuzat”)."""
        return any(v["nivel"] == "BLOCANT" for v in self.verificari[de_la:])

engine/calc/locuinta.py:
"""locuinta.py — tabloul electric al unei case / al unui apartament (SPEC §C.8, v1.7).

Branșament (BMPM / BMPT, existent sau nou) → coloana C2 → tabloul locuinței (TE): Q general (întreruptor-separator
sau MCB), SPD T2, grupe DDR 30 mA (RCCB 2P pe o fază / 4P cu circuite 3F; RCBO pentru circuitul singur) și circuitele
finale, cu bilanțul de puteri, repartizarea pe faze și verificarea Q-ului de branșament pe faza cea mai încărcată.
Valorile implicite pe receptor sunt în `norme.LOCUINTA_RECEPTORI` și se declară ca presupuse (V11).

v1.5 (runda 4 de testare, `teste/r4/proiectant.md`, `teste/r4/verificator.md`):
* V46 pe faza cea mai încărcată (Ib de calcul pe fază, cu ks), BLOCANT peste 1,13·In sau peste In la sarcini continue;
* P aprobată declarată → Ib general / coloana / Q general din puterea aprobată, Pc din ks informativ (V46 AV);
* Q branșament nedeclarat → Q presupus = calibrul standard ≥ Ib (nu mai mic decât sarcina), peste limita blocului BLOCANT;
* TT: protecția la defect = DDR (RA·IΔn ≤ 50 V), Ik1/Ia doar pentru scurtcircuitul L–N (V30 „TT”);
* toate circuitele finale cu DDR ≤ 30 mA (V49), MCB / Q general > Q branșament → V40 BLOCANT;
* grupe DDR: max. 5 circuite, iluminatul separat de prize (≥ 2 grupe de iluminat la ≥ 2 circuite), grupe pe o fază → 2P,
  cu circuite 3F → 4P, circuit singur → RCBO; sauna pe DDR propriu, cu cablu termorezistent.

v1.6 (runda 4b, `teste/r4/proiectant_b.md`, `teste/r4/verificator_b.md`, `teste/r4/ux_b.md`):
* N2 — coloana C2 se mărește întâi (buget ΔU 1,5 %), abia apoi circuitele finale; m8 — coloana pe faza cea mai încărcată;
* m-n3 — repartizarea pe faze pe curentul de CALCUL (3F, faze impuse, apoi monofazatele descrescător, inclusiv din 4P);
* N5 / m-n5 — Q / P aprobată nedeclarate la branșament existent → V46 AVERTISMENT vizibil; mesajele pe Q presupus o spun;
* P1-4 — iluminat: max. 2 circuite pe DDR, nivelurile deduse din nume nu se amestecă; P2-1 — V43 agregat;
* SPD.protectie_rezerva; alimentare.zona (Zbuclă rurală); TT — coloana „L + N”, PE din priza locală;
* rezultate parțiale: un circuit invalid e marcat `blocat` și restul se calculează; mesajele fără chei interne (`camp`).

v1.7 (runda 4c, `teste/r4/proiectant_c.md`, `teste/r4/verificator_c.md`, `teste/r4/ux_c.md`):
* M-c1 — Q branșament în afara seriei → V05 cu `camp`, Q ignorat, calculul continuă cu Q presupus (treapta superioară /
  limita blocului); m-c4 — Zb_OD_ohm / RA_ohm / Ik3_OD_kA invalide → V07 cu `camp`, ignorate (valoarea implicită);
* N11 — Zbucla rurală e „presupus (zonă rurală, [NEVERIFICAT]) — se confirmă cu OD / ATR”, nu „din ATR”;
* M-c3 — VE sub DDR-ul 300 mA tip AC / A / F al branșamentului → V43 „ve_dc” (AV; TT: BLOCANT);
* m-c5 / C3 — dicționarele centrale ETICHETE_RECEPTOR / ETICHETE (fără chei interne în mesaje și presupuneri);
* m-c6 — creșterea pentru ΔU a circuitelor finale plafonată la 16 mm² (V20 cu remedierea „mărește coloana”);
* N16 — prizele (și celelalte grupe) pe niveluri deduse din nume; N17 — VE dimensionat normal (minim 4 mm²);
* N13 — cosφ în ipoteze cu eticheta receptorului și „presupus” / „declarat” corect; nota ks fără „după 0 receptoare”.
"""
import math
import re

from . import norme
from . import ddr as ddr_mod
from . import protectii as pr
from .comun import Jurnal, ge, gt, lt, prima_din_serie, SQRT3
from .ramura import calculeaza_ramura
from .texte import fmt_ro, NB, nota_schema_pamant
from .verificari import emite, BLOCANT, AVERTISMENT, INFO

CAMPURI_R = ("P_mono", "P_tri", "cosfi", "curba", "In_mono", "In_tri", "S_mono", "S_tri", "L", "calcul", "tri_posibil",
             "grupa", "ddr", "ddr_tip", "continuu")
