# câmpurile globale (nivelul schemei) ale locuinței validate local (m-c4): valoarea invalidă se ignoră, nu oprește calculul
CAMPURI_GLOBALE_IGNORABILE = {"Zb_OD_ohm": "Ω", "RA_ohm": "Ω", "Ik3_OD_kA": "kA"}


def eticheta_receptor(cheie):
    """Denumirea românească a unui receptor al locuinței (cheia necunoscută rămâne ca atare, fără „_”)."""
    return ETICHETE_RECEPTOR.get(cheie) or str(cheie).replace("_", " ")


def eticheta_camp(cheie):
    """Denumirea românească a unui câmp de intrare al locuinței."""
    return ETICHETE.get(cheie) or str(cheie).replace("_", " ")
# câmpul unui circuit pe care îl privește o verificare fără câmp numit în mesaj (UX 13)
CAMP_DUPA_COD = {"V04": "In_A", "V05": "In_A", "V09": "L_m", "V13": "cablu.S_fortat", "V07": "P_kW"}
# v1.6 (P1-4): nivelul circuitului de iluminat dedus din nume (fără diacritice, litere mici)
NIVELURI = ((r"\b(sub|demi)sol", "subsol"), (r"\bparter", "parter"),
            (r"\bmansard", "mansarda"), (r"\b(exterior|ext\b|curte|gradin|fatad|terasa|gard)", "exterior"),
            (r"\b(etaj|et\.?)\s*(\d+)", "etaj{}"), (r"\betaj", "etaj1"), (r"\bpod\b", "pod"))


def _rec(cheie):
    return dict(zip(CAMPURI_R, norme.LOCUINTA_RECEPTORI[cheie]))


def _numar(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def _cablu_valid(cab, j, ob, camp):
    """Validează și NORMALIZEAZĂ pe loc dicționarul `cablu` (v1.5, m4: „cu” → Cu, „b2” → B2). Întoarce copia sau None."""
    from .scheme import _valideaza_dict
    if not isinstance(cab, dict):
        emite(j, "V07", BLOCANT, ob, "param", camp=camp, x=repr(cab), conditie="se așteaptă un obiect")
        return None
    cab = dict(cab)
    return cab if _valideaza_dict(cab, j, ob, sari=("L",)) else None


def _zb_valid(zb):
    """Aceeași regulă ca validarea generală (scheme._valideaza_intrare): modul > 0 sau pereche (R, X) ≥ 0, |Z| > 0."""
    if isinstance(zb, dict):
        vals = [zb.get("R", zb.get("R_ohm")), zb.get("X", zb.get("X_ohm"))]
    elif isinstance(zb, (list, tuple)):
        vals = list(zb)
    else:
        vals = [zb]
    if len(vals) not in (1, 2) or not all(_numar(v) for v in vals):
        return False
    if len(vals) == 1:
        return vals[0] > 0
    return vals[0] >= 0 and vals[1] >= 0 and math.hypot(vals[0], vals[1]) > 0


def prevalideaza(inp, j):
    """v1.7 (runda 4c, m-c4): câmpurile globale ale locuinței (Zb_OD_ohm, RA_ohm, Ik3_OD_kA) invalide → V07 BLOCANT cu
    `camp` și mesaj fără chei interne; valoarea se IGNORĂ (se folosește valoarea implicită, declarată ca presupusă), iar
    calculul continuă (rezultat parțial, exportul refuzat). Se apelează înaintea validării generale a schemei."""
    if not isinstance(inp, dict):
        return
    for k, um in CAMPURI_GLOBALE_IGNORABILE.items():
        v = inp.get(k)
        if v is None:
            continue
        ok = _zb_valid(v) if k == "Zb_OD_ohm" else (_numar(v) and v > 0)
        if ok:
            continue
        if k != "Zb_OD_ohm" and not _numar(v):
            x, cond = f"„{v}”" if isinstance(v, str) else repr(v), "valoare nenumerică (se așteaptă un număr)"
        else:
            x = f"{fmt_ro(v, 3)} {um}" if _numar(v) else repr(v)
            cond = ("trebuie > 0 (modul |Z| sau pereche (R, X) cu R, X ≥ 0)" if k == "Zb_OD_ohm" else "trebuie > 0")
        emite(j, "V07", BLOCANT, "schema", "param", camp=eticheta_camp(k), x=x,
              conditie=cond + " — valoarea se ignoră, calculul continuă cu valoarea implicită (presupusă)")
        v07 = j.verificari[-1]
        v07["camp"] = k
        v07["remediere"] = f"introdu {eticheta_camp(k)} ca număr pozitiv (din ATR / avizul OD / buletinul de măsurare)"
        inp.pop(k)
        j.presupune(f"{eticheta_camp(k)} invalidă → ignorată, se folosește valoarea implicită")


def _cu_camp(j, camp):
    """Pune `camp` pe ultima verificare emisă (dacă nu îl are deja)."""
    if j.verificari:
        j.verificari[-1].setdefault("camp", camp)


def _valideaza(inp, j, retea):
    """Validarea specifică locuinței (V07 / V09 / V10 / V12 BLOCANT). Întoarce (alimentare, circuite) sau None.

    v1.6 (UX 12, rezultate parțiale): o eroare LOCALĂ (un câmp al alimentării, un circuit) nu mai oprește calculul —
    câmpul invalid se ignoră (se folosește valoarea implicită, declarată), circuitul rămâne marcat `_blocat` (cu
    V-ul lui BLOCANT, exportul rămâne refuzat), iar restul se calculează normal. None doar fără niciun circuit."""
    from .scheme import _valideaza_dict, _valideaza_ddr, _fd
    al = inp.get("alimentare")
    if al is None:
        al = {}
    if not isinstance(al, dict):
        emite(j, "V07", BLOCANT, "alimentare", "param", camp="alimentare", x=repr(al), conditie="se așteaptă un obiect")
        al = {}
    al = dict(al)
    t = al.get("tip", "bransament_existent")
    if t not in TIPURI_ALIMENTARE:
        emite(j, "V12", BLOCANT, "alimentare", "camp", camp="alimentare.tip", valoare=t)
        t = "bransament_existent"
    al["tip"] = t
    for k in ("In_Q_bransament_A", "P_aprobata_kW", "L_coloana_m"):
        v = al.get(k)
        if v is not None and (not _numar(v) or v <= 0):
            if k == "L_coloana_m" and _numar(v):
                emite(j, "V09", BLOCANT, "alimentare", "B", L=v)
            else:
                # v1.7 (P2 verificator): textul spune „nenumerică” la text, nu „trebuie > 0”
                emite(j, "V07", BLOCANT, "alimentare", "param", camp=f"alimentare.{k}",
                      x=v if _numar(v) else (f"„{v}”" if isinstance(v, str) else repr(v)),
                      conditie="trebuie > 0" if _numar(v) else "valoare nenumerică (se așteaptă un număr)")
            _cu_camp(j, f"alimentare.{k}")
            al.pop(k)
            al.setdefault("_invalide", []).append(k)
    q = al.get("In_Q_bransament_A")
    if q is not None:
        # v1.7 (M-c1): Q în afara seriei (ex. 33 A; 63 A la monofazat) → V05 cu `camp`, Q ignorat; calculul continuă cu Q
        # presupus = calibrul standard imediat superior / limita blocului (exportul rămâne refuzat)
        serie = SERIE_Q_MONO if retea == "mono" else SERIE_Q_TRI_TOATE
        if q not in serie:
            sus = [x for x in serie if x > q]
            jos = [x for x in serie if x < q]
            emite(j, "V05", BLOCANT, "Q", In=q, tip="RCBO BMPM (ST 3-JT)" if retea == "mono" else "Q BMPT (ST 4-JT)",
                  vecini=f"{jos[-1] if jos else '—'} A / {sus[0] if sus else '—'} A")
            j.verificari[-1]["camp"] = "alimentare.In_Q_bransament_A"
            al.pop("In_Q_bransament_A")
            al["_q_invalid"] = q
    tb = al.get("DDR_bransament_tip")
    if tb is not None:
        # v1.7 (M-c3): tipul DDR-ului 300 mA din blocul de branșament (implicit AC, ST 3-JT / ST 4-JT)
        tbn = str(tb).strip().upper() if isinstance(tb, str) else None
        if tbn not in norme.LOCUINTA_DDR_TIPURI:
            emite(j, "V12", BLOCANT, "alimentare", "camp", camp="alimentare.DDR_bransament_tip", valoare=tb)
            al.pop("DDR_bransament_tip")
        else:
            al["DDR_bransament_tip"] = tbn
    if al.get("cablu") is not None:
        cab = _cablu_valid(al["cablu"], j, "C2", "alimentare.cablu")
        if cab is None:
            al.pop("cablu")
        else:
            al["cablu"] = cab
    pz = al.get("pozare_coloana")
    if pz is not None:
        met = POZARE_COLOANA.get(_fd(pz)) if isinstance(pz, str) else None
        if met is None:
            emite(j, "V12", BLOCANT, "C2", "camp", camp="alimentare.pozare_coloana", valoare=pz)
            al.pop("pozare_coloana")
        else:
            al["pozare_coloana"] = met
    zn = al.get("zona")
    if zn is not None:
        z = ZONE.get(_fd(zn)) if isinstance(zn, str) else None
        if z is None:
            emite(j, "V12", BLOCANT, "alimentare", "camp", camp="alimentare.zona", valoare=zn)
            al.pop("zona")
        else:
            al["zona"] = z
    circ = inp.get("circuite")
    if not isinstance(circ, list) or not circ:
        emite(j, "V07", BLOCANT, "schema", "plecari", tablou="tabloul locuinței")
        return None
    out = []
    for i, c in enumerate(circ, 1):
        nume = c.get("nume", "") if isinstance(c, dict) else ""
        nume = "" if nume is None else str(nume)          # v1.5 (m3): numele numeric → text
        ob = f"C{i}·{nume}"
        blocat = []
        if not isinstance(c, dict):
            emite(j, "V07", BLOCANT, ob, "param", camp="circuit", x=repr(c), conditie="se așteaptă un obiect")
            c, blocat = {}, ["V07"]
        c = dict(c)
        c["nume"] = nume
        for k in c:
            if k not in CHEI_CIRCUIT:
                # v1.5 (m12): cheile necunoscute nu se ignoră tacit
                emite(j, "V12", AVERTISMENT, ob, "necunoscut", camp=k,
                      acceptate=", ".join(ETICHETE.get(x, x) for x in CHEI_CIRCUIT))
        c = {k: v for k, v in c.items() if k in CHEI_CIRCUIT}
        rec = c.pop("receptor", None)
        if rec is None:
            rec = "alt_circuit"
            j.presupune("receptor nedeclarat → „Alt circuit” (2 kW, C16, 2,5 mm²)", ob)
        if not isinstance(rec, str) or rec.strip().lower() not in norme.LOCUINTA_RECEPTORI:
            emite(j, "V12", BLOCANT, ob, "camp", camp="receptor", valoare=rec)
            rec, blocat = "alt_circuit", blocat + ["V12"]
        rec = rec.strip().lower()
        f = c.pop("faza", None)
        if f is not None:
            fs = str(f).strip().upper()
            if fs not in FAZE or (retea == "mono" and fs not in ("L1",)):
                emite(j, "V12", BLOCANT, ob, "camp", camp="faza", valoare=f)
                fs, blocat = None, blocat + ["V12"]
            f = fs
        ddr_c = c.pop("DDR", None)
        if isinstance(ddr_c, dict):
            for k in ddr_c:
                if k not in CHEI_DDR:
                    # v1.6 (m-n4): cheile necunoscute ale DDR-ului impus nu se ignoră tacit
                    emite(j, "V12", AVERTISMENT, ob, "necunoscut", camp=f"DDR.{k}",
                          acceptate="IΔn, tipul DDR (AC / A / F / B), temporizare S, Δt")
            ddr_c = {k: v for k, v in ddr_c.items() if k in CHEI_DDR}
            if not _valideaza_ddr(ddr_c, j, ob, "DDR"):
                ddr_c, blocat = None, blocat + ["V12"]
            else:
                ddr_c = dict(ddr_c)
                if ddr_c.get("tip") is not None:
                    ddr_c["tip"] = str(ddr_c["tip"]).upper()
                if ddr_c.get("selectiv") and int(ddr_c["IdN_mA"]) < 100:
                    # v1.5 (m9): DDR 30 mA de tip S nu există
                    emite(j, "V12", BLOCANT, ob, "ddr_s", IdN=int(ddr_c["IdN_mA"]))
                    ddr_c, blocat = None, blocat + ["V12"]
        if ddr_c is not None and not isinstance(ddr_c, dict) and ddr_c is not False:
            emite(j, "V12", BLOCANT, ob, "camp", camp="DDR", valoare=ddr_c)
            ddr_c, blocat = None, blocat + ["V12"]
        cab = c.pop("cablu", None)
        if cab is not None:
            cab = _cablu_valid(cab, j, ob, "cablu")
            if cab is None:
                blocat.append("V10")
        nm = c.pop("nume")
        for k in list(c):
            # câmp cu câmp: un câmp invalid se ignoră (valoarea implicită), circuitul rămâne blocat
            d1 = {k: c[k]}
            n0 = len(j.verificari)
            if not _valideaza_dict(d1, j, ob, sari=("P_kW", "L_m")):
                blocat.append(j.verificari[-1]["cod"] if len(j.verificari) > n0 else "V12")
                c.pop(k)
            elif k in d1:
                c[k] = d1[k]
        for k, cod in (("P_kW", "V07"), ("L_m", "V09")):
            v = c.get(k)
            if v is not None and v <= 0:
                if cod == "V09":
                    emite(j, "V09", BLOCANT, ob, "B", L=v)
                else:
                    emite(j, "V07", BLOCANT, ob, P=v)
                c.pop(k)
                blocat.append(cod)
        if c.get("P_kW") is not None and c["P_kW"] > norme.LOCUINTA_P_CIRCUIT_MAX_KW:
            emite(j, "V07", BLOCANT, ob, "param", camp="P_kW", x=c["P_kW"],
                  conditie=f"neplauzibil pentru un circuit de locuință (> {fmt_ro(norme.LOCUINTA_P_CIRCUIT_MAX_KW, 0)} kW)")
            c.pop("P_kW")
            blocat.append("V07")
        if c.get("L_m") is not None and c["L_m"] > 1000:
            emite(j, "V09", AVERTISMENT, ob, "AV", L=c["L_m"])
        out.append(dict(c, nume=nm, receptor=rec, faza=f, DDR=ddr_c, cablu=cab, obiect=ob, idx=i, _blocat=blocat))
    return al, out


def _circuit(c, retea, j):
    """Intrarea B.1 a unui circuit al locuinței, cu valorile implicite ale receptorului (declarate)."""
    d = _rec(c["receptor"])
    tri = retea == "tri" and (c["faza"] == "3F" or (c["faza"] is None and d["tri_posibil"]))
    tri_fortat = c["faza"] == "3F" and not d["tri_posibil"]
    if tri_fortat:
        j.presupune(f"{eticheta_receptor(c['receptor'])} declarat trifazat (3F) — valorile implicite monofazate se aplică pe fază "
                    f"(P implicit = 3 × {fmt_ro(d['P_mono'])} kW)", c["obiect"])
    P = c.get("P_kW")
    if P is None:
        P = 3 * d["P_mono"] if tri_fortat else (d["P_tri"] if tri and d["P_tri"] else d["P_mono"])
        j.presupune(f"{eticheta_receptor(c['receptor'])}: P = {fmt_ro(P)} kW", c["obiect"])
    L = c.get("L_m", (c.get("cablu") or {}).get("L"))
    if L is None:
        L = d["L"]
        j.presupune(f"{eticheta_receptor(c['receptor'])}: lungime circuit {fmt_ro(L, 0)} m", c["obiect"])
    S_min = (d["S_tri"] if tri and d["S_tri"] else d["S_mono"])
    In_min = (d["In_tri"] if tri and d["In_tri"] else d["In_mono"])
    cab = {"material": "Cu", "metoda": "B2"}
    cab.update({k: v for k, v in (c.get("cablu") or {}).items() if v is not None})
    cab["L"] = float(L)
    cab["S_min"] = S_min
    if c["receptor"] in norme.LOCUINTA_S_MIN_FIX_MM2:
        cab["S_min_fix"] = norme.LOCUINTA_S_MIN_FIX_MM2[c["receptor"]]
    sf = cab.get("S_fortat")
    if sf is not None:
        # v1.5 (m11): secțiunea impusă sub minimul receptorului — prize < 2,5 mm² BLOCANT (I7-2011, §B.8), altfel AV
        prize = c["receptor"].startswith("prize")
        if lt(float(sf), S_min):
            emite(j, "V13", BLOCANT if prize else AVERTISMENT, c["obiect"], "loc", S=sf, Smin=S_min, rec=eticheta_receptor(c["receptor"]),
                  sursa="I7-2011 / SPEC §B.8" if prize else "valoare uzuală §C.8")
    if d["grupa"] == "VE" and sf is None:
        # v1.7 (N17): VE dimensionat normal (Ib / In, Iz, ΔU, Ik) cu minimul 4 mm² Cu — nu o secțiune fixă de 6 mm²
        j.presupune(f"{eticheta_receptor(c['receptor'])}: secțiunea din Ib / In, Iz, ΔU și Ik, minimum "
                    f"{fmt_ro(S_min)} mm² Cu (sarcină continuă, §C.8 — DECIZIE); pentru o rezervă de putere (ex. 22 kW) "
                    f"declară secțiunea impusă", c["obiect"])
    r = {"rol": "final", "receptor": d["calcul"], "retea": "tri" if tri else "mono", "P_kW": float(P),
         "cosfi": c.get("cosfi") or d["cosfi"], "prot_tip": "MCB", "curba": c.get("curba") or d["curba"],
         "cablu": cab, "In_minim": In_min, "_validat": True,
         # v1.7 (N13): cosφ din tabelul receptorului e presupus (nu „declarat”), cu eticheta receptorului în ipoteze
         "_cosfi_eticheta": eticheta_receptor(c["receptor"]), "_cosfi_implicit": c.get("cosfi") is None}
    if sf is None:
        # v1.7 (m-c6): mărirea pentru ΔU a circuitului final plafonată (peste — V20 cu remedierea „mărește coloana”)
        r["S_max_dU"] = norme.LOCUINTA_S_MAX_CIRCUIT_DU_MM2
    if c.get("In_A") is not None:
        r["In_fortat"] = c["In_A"]
        r.pop("In_minim")
    if d["calcul"] == "motor":
        r["pornire"] = "directa"
    return r, d, tri


def _categorie(x):
    """Cheia grupei DDR a unui circuit (v1.5): fără DDR, VE, DDR impus (propriu), saună, iluminat, apoi grupa receptorului."""
    c, d = x["c"], x["d"]
    if c["DDR"] is False:
        return "fara"
    if d["grupa"] == "VE":
        return "VE"
    if isinstance(c["DDR"], dict):
        return "propriu"
    if d["grupa"] == "sauna":
        return "sauna"
    if c["receptor"] == "iluminat":
        return "iluminat"
    return d["grupa"]


def _imparte(mem, k):
    """Împarte lista în k bucăți consecutive cât mai egale."""
    k = max(1, min(k, len(mem)))
    n, r = divmod(len(mem), k)
    out, i = [], 0
    for q in range(k):
        m = n + (1 if q < r else 0)
        out.append(mem[i:i + m])
        i += m
    return [x for x in out if x]


def nivel_din_nume(nume):
    """v1.6 (P1-4): nivelul unui circuit de iluminat dedus din nume (subsol / parter / etajN / mansarda / exterior / pod)
    sau None."""
    from .scheme import _fara_diacritice
    n = _fara_diacritice(str(nume or "")).lower()
    for rx, cheie in NIVELURI:
        m = re.search(rx, n)
        if m:
            return cheie.format(m.group(2)) if "{}" in cheie else cheie
    return None


def _pondere(x, ks, ks_decl):
    """v1.6 (m-n3): curentul de CALCUL al unui circuit pe faza lui: ks·Ib (general) sau Ib (sarcină continuă);
    `ks` declarat → ks·Ib pentru toate."""
    return x["Ib"] if (x["d"]["continuu"] and not ks_decl) else ks * x["Ib"]


def _loturi(pe_cat):
    """Loturile de grupare (categorie, membri, limită pe DDR, minimum 2 grupe?) în ordinea ORDINE_GRUPE.
    v1.6 (P1-4): iluminatul — cel mult LOCUINTA_ILUMINAT_PE_DDR circuite pe DDR, câte un lot pe nivel (dedus din nume);
    la un singur lot cu ≥ 2 circuite, cel puțin 2 grupe (v1.5)."""
    LIM = norme.LOCUINTA_CIRCUITE_PE_DDR
    out = []
    for cat in ORDINE_GRUPE:
        mem = pe_cat.get(cat) or []
        if not mem:
            continue
        if cat != "iluminat":
            # v1.7 (N16): prizele (și celelalte receptoare ale categoriei) de pe niveluri diferite, deduse din nume, nu se
            # amestecă pe același DDR; circuitele fără nivel completează lotul cel mai mic (în ordinea intrării), deci
            # fără niveluri / cu un singur nivel comportamentul e cel din v1.6
            niv = {}
            for x in mem:
                n_ = nivel_din_nume(x["c"].get("nume"))
                if n_ is not None:
                    niv.setdefault(n_, []).append(x)
            if len(niv) < 2:
                out.append((cat, mem, LIM, False))
                continue
            loturi = list(niv.values())
            for x in mem:
                if nivel_din_nume(x["c"].get("nume")) is None:
                    min(loturi, key=len).append(x)
            for m in loturi:
                m.sort(key=lambda y: y["c"]["idx"])
                out.append((cat, m, LIM, False))
            continue
        niv = {}
        for x in mem:
            niv.setdefault(nivel_din_nume(x["c"].get("nume")), []).append(x)
        unic = len(niv) == 1
        for m in niv.values():
            out.append((cat, m, norme.LOCUINTA_ILUMINAT_PE_DDR, unic and len(m) >= 2))
    return out


def _grupeaza_si_repartizeaza(ramuri, retea, ks=1.0, ks_decl=False):
    """v1.5 / v1.6 (§C.8 pct. 4–5): grupele DDR și fazele circuitelor.

    * cel mult LOCUINTA_CIRCUITE_PE_DDR circuite pe un DDR (iluminat: 2, pe niveluri); iluminatul separat de prize;
      bucătărie / baie / exterior separate; saună, VE și circuitele cu DDR impus — câte o grupă proprie;
    * la trifazat: circuitele 3F ale unei categorii formează grupe 4P (completate cu monofazate), restul monofazatelor
      formează grupe pe O SINGURĂ fază (DDR 2P);
    * v1.6 (m-n3) — ordinea repartizării, pe curentul de CALCUL (ks·Ib general, Ib continuu): întâi circuitele 3F,
      apoi fazele impuse, apoi toate unitățile monofazate libere — grupele 2P întregi și monofazatele din grupele 4P /
      „fără DDR”, individual — descrescător după curentul de calcul, fiecare pe faza cu cel mai mic curent de calcul.
    Întoarce (grupe, sarc) — sarc = Ib instalat pe fază; setează x["faza"]."""
    pe_cat = {}
    for x in ramuri:
        pe_cat.setdefault(_categorie(x), []).append(x)
    grupe = []                          # {cheie, membri, faza (None = de repartizat), poli}
    for cat, mem, lim, kmin2 in _loturi(pe_cat):
        m3 = [x for x in mem if x["tri"]]
        m1 = [x for x in mem if not x["tri"]]
        g4 = []
        if m3:
            for ch in _imparte(m3, math.ceil(len(m3) / lim)):
                g4.append({"cheie": cat, "membri": list(ch), "faza": "3F", "poli": "4P"})
            for g in g4:
                while len(g["membri"]) < lim and m1:
                    g["membri"].append(m1.pop(0))
        grupe += g4
        if not m1:
            continue
        if retea == "mono":
            k = math.ceil(len(m1) / lim)
            if kmin2 and not m3:
                k = max(k, 2)
            grupe += [{"cheie": cat, "membri": ch, "faza": "L1", "poli": "2P"} for ch in _imparte(m1, k)]
            continue
        impuse = {}
        libere = []
        for x in m1:
            (impuse.setdefault(x["c"]["faza"], []) if x["c"]["faza"] in ("L1", "L2", "L3") else libere).append(x)
        for f in ("L1", "L2", "L3"):
            for ch in _imparte(impuse.get(f) or [], math.ceil(len(impuse.get(f) or []) / lim)):
                grupe.append({"cheie": cat, "membri": ch, "faza": f, "poli": "2P"})
        if libere:
            k = math.ceil(len(libere) / lim)
            if kmin2 and not impuse and not m3:
                k = max(k, 2)
            grupe += [{"cheie": cat, "membri": ch, "faza": None, "poli": "2P"} for ch in _imparte(libere, k)]
    for x in ramuri:                    # grupe proprii, în ordinea de la intrare
        cat = _categorie(x)
        if cat in ("VE", "propriu", "sauna"):
            grupe.append({"cheie": cat, "membri": [x], "faza": "3F" if x["tri"] else
                          ("L1" if retea == "mono" else x["c"]["faza"]), "poli": "4P" if x["tri"] else "2P"})
    fara = pe_cat.get("fara") or []
    if fara:
        grupe.append({"cheie": "fara", "membri": fara, "faza": None, "poli": None})

    # ---- fazele ----
    sarc = {"L1": 0.0, "L2": 0.0, "L3": 0.0}
    calc = {"L1": 0.0, "L2": 0.0, "L3": 0.0}
    w = lambda x: _pondere(x, ks, ks_decl)  # noqa: E731

    def pune(x, f):
        x["faza"] = f
        for ff in (("L1", "L2", "L3") if f == "3F" else (f,)):
            sarc[ff] += x["Ib"]
            calc[ff] += w(x)

    for x in ramuri:
        if x["tri"]:
            pune(x, "3F")
        elif retea == "mono":
            pune(x, "L1")
        elif x["c"]["faza"] in sarc:
            pune(x, x["c"]["faza"])
    if retea == "tri":
        unitati = [(sum(w(x) for x in g["membri"]), n, g["membri"], g) for n, g in enumerate(grupe)
                   if g["cheie"] != "fara" and g["poli"] == "2P" and g["faza"] is None]
        n0 = len(unitati)
        in_grupe = {id(x) for u in unitati for x in u[2]}
        unitati += [(w(x), n0 + n, [x], None) for n, x in
                    enumerate(x for x in ramuri if "faza" not in x and id(x) not in in_grupe)]
        for _, _, mem, g in sorted(unitati, key=lambda u: (-u[0], u[1])):
            f = min(("L1", "L2", "L3"), key=lambda k: (calc[k], k))
            if g is not None:
                g["faza"] = f
            for x in mem:
                pune(x, f)
    for g in grupe:
        if g["cheie"] != "fara" and g["poli"] == "2P" and g["faza"] is None:
            g["faza"] = g["membri"][0]["faza"]
    return grupe, sarc


def _curenti_faza(ramuri, retea, ks, ks_declarat):
    """v1.5 (C1): curentul de calcul pe fiecare fază = ks·Σ Ib general + Σ Ib continuu (ks declarat: ks·Σ Ib);
    circuitele 3F încarcă toate fazele. Întoarce (calc, continuu)."""
    calc = {"L1": 0.0, "L2": 0.0, "L3": 0.0}
    cont = {"L1": 0.0, "L2": 0.0, "L3": 0.0}
    for x in ramuri:
        fz = ("L1", "L2", "L3") if x["faza"] == "3F" else (x["faza"],)
        for f in fz:
            if ks_declarat:
                calc[f] += ks * x["Ib"]
            elif x["d"]["continuu"]:
                calc[f] += x["Ib"]
                cont[f] += x["Ib"]
            else:
                calc[f] += ks * x["Ib"]
        if ks_declarat and x["d"]["continuu"]:
            for f in fz:
                cont[f] += x["Ib"]
    if retea == "mono":
        calc = {"L1": calc["L1"], "L2": 0.0, "L3": 0.0}
        cont = {"L1": cont["L1"], "L2": 0.0, "L3": 0.0}
    return calc, cont


def _capacitate_conditionata(ik3):
    """Inc / Icc condiționat (RCCB / IS) din seria uzuală ≥ Ik3 la bara TE; (valoare, ok)."""
    v = prima_din_serie(norme.LOCUINTA_INC_KA, ik3)
    return (v, True) if v is not None else (norme.LOCUINTA_INC_KA[-1], False)


def _umanizeaza(j, n_v, n_i, circ):
    """v1.6 (UX 13): mesajele emise de locuință fără chei interne — cheia tehnică (ex. „P_kW”) e înlocuită cu denumirea
    românească, iar calea câmpului merge în cheia separată `camp` („alimentare.In_Q_bransament_A”, „circuite[2].P_kW”,
    index de la 0, ca în lista de intrare). Se înlocuiesc doar tokenii care sunt chei: cu „_” / cale cu „.”, sau
    cuvintele simple doar în contextul „câmpul „X”” / „X = …”."""
    idx = {c["obiect"]: c["idx"] - 1 for c in circ or []}
    chei = sorted(ETICHETE, key=len, reverse=True)
    pref = r"(?:alimentare\.cablu\.|alimentare\.|DDR\.|cablu\.)?"

    def regexuri(k):
        # 1) forma cu prefix („alimentare.zona”, „DDR.In_A”); 2) forma simplă: cheile cu „_” oriunde, cuvintele simple
        # doar în contextul „câmpul „X””, „câmpului X”, „X = …”
        yield r"(?<![\w.])(" + pref.replace(")?", ")") + re.escape(k) + r")(?![\w])"
        if "_" in k:
            yield r"(?<![\w.])(" + re.escape(k) + r")(?![\w])"
        else:
            yield (r"(?<=câmpul „)(" + re.escape(k) + r")(?=”)|(?<=câmpului )(" + re.escape(k) + r")(?![\w.])|"
                   r"(?<![\w.])(" + re.escape(k) + r")(?= = )")

    def inlocuieste(txt, gasite):
        # v1.7 (P2 verificator): etichetele puse deja se țin în substituenți, ca să nu fie înlocuite a doua oară
        # („zona (urban / rural) (urban / rural)”)
        puse = []
        for rx, k in [(rx, k) for faza in (0, 1) for k in chei for i, rx in enumerate(regexuri(k)) if i == faza]:

            def rep(m):
                tok = next(g for g in m.groups() if g)
                gasite.append(tok)
                suf = (" (cablul coloanei)" if tok.startswith("alimentare.cablu.") else " (DDR impus)"
                       if tok.startswith("DDR.") else " (cablu)" if tok.startswith("cablu.") else "")
                puse.append(ETICHETE[k] + suf)
                return f"\x01{len(puse) - 1}\x02"
            txt = re.sub(rx, rep, txt)
        return re.sub("\x01(\\d+)\x02", lambda m: puse[int(m.group(1))], txt)

    for v in j.verificari[n_v:] + j.info[n_i:]:
        gasite = []
        v["mesaj"] = inlocuieste(v.get("mesaj") or "", gasite)
        if v.get("remediere"):
            v["remediere"] = inlocuieste(v["remediere"], [])
        if not gasite and v.get("obiect") in idx and v["cod"] in CAMP_DUPA_COD:
            gasite = [CAMP_DUPA_COD[v["cod"]]]
        if gasite and "camp" not in v:
            tok, ob = gasite[0], v.get("obiect")
            if tok.startswith("alimentare"):
                v["camp"] = tok
            elif ob in ("alimentare", "C2"):
                v["camp"] = f"alimentare.{tok}"
            elif ob in idx:
                v["camp"] = f"circuite[{idx[ob]}].{tok}"
            else:
                v["camp"] = tok


def calculeaza_locuinta(inp, j):
    """SPEC §C.8: bilanț, branșament + coloană C2, Q general, SPD T2, grupe DDR, circuite și repartizarea pe faze."""
    n_v, n_i, n_p = len(j.verificari), len(j.info), len(j._presupus)
    cutie = {}
    try:
        return _calculeaza(inp, j, cutie)
    finally:
        _umanizeaza(j, n_v, n_i, cutie.get("circ"))
        # v1.7 (m-c5 / UX C3): nicio cheie de receptor în mesaje, remedieri și presupuneri
        for v in j.verificari[n_v:] + j.info[n_i:]:
            v["mesaj"] = fara_chei_receptor(v.get("mesaj") or "")
            if v.get("remediere"):
                v["remediere"] = fara_chei_receptor(v["remediere"])
            if v["cod"] == "V34":
                # locuința nu are câmpul „IΔn amonte”: DDR-ul 300 mA din branșament e al blocului OD
                v["remediere"] = ("priză de pământ mai bună (RA mai mic, măsurat), astfel încât RA·IΔn ≤ 50 V cu IΔn al "
                                  "DDR-ului din branșament (300 mA → RA ≤ 166 Ω) și al grupelor (30 mA)")
        j._presupus[n_p:] = [(fara_chei_receptor(t), el) for t, el in j._presupus[n_p:]]
        for v in j.verificari[n_v:]:
            # Q presupus: câmpul de completat (m-n5 / N5)
            if v["cod"] == "V46" and "presupus" in v.get("mesaj", "") and "camp" not in v:
                v["camp"] = "alimentare.In_Q_bransament_A" if "Q " in v["mesaj"] else "alimentare.P_aprobata_kW"


def _verifica_ve_amonte(j, g, tip_av, am_nume, am_idn, am_tip, tt, declarat):
    """v1.7 (M-c3, DECIZIE §C.8 pct. 4): circuitul VE (DDR tip B, sau A / F cu RDC-DD 6 mA în stație) în aval de DDR-ul
    300 mA al branșamentului. Un curent de defect c.c. neted trece și prin DDR-ul din amonte și îl poate „orbi” (SR HD
    60364-5-53:2015 art. 531.3.2, IEC 60364-7-722:2018 art. 722.531.3.101):
    * amonte tip B → în regulă;
    * amonte tip A / F și DDR VE tip A / F (stația limitează c.c. la 6 mA prin RDC-DD; tip A / F e garantat până la
      6 mA c.c., SR EN 61008-1 / IEC 62423) → în regulă;
    * altfel (amonte AC; sau amonte A / F cu DDR VE tip B, fără limitarea c.c.) → V43 „ve_dc” AVERTISMENT la TN-C-S;
      **BLOCANT la TT** — acolo DDR-ul 300 mA e protecția la defect (RA·IΔn ≤ 50 V) a coloanei C2 și a intrării TE."""
    if am_tip == "B" or (am_tip in ("A", "F") and tip_av in ("A", "F")):
        return
    if not declarat:
        j.presupune(f"DDR-ul din branșament ({am_nume} {am_idn} mA) tip {am_tip} (ST 3-JT / ST 4-JT) — declară tipul "
                    f"real al DDR-ului din branșament dacă e altul")
    det = (" — în TT acest DDR e protecția la defect (RA·IΔn ≤ 50 V) a coloanei C2 și a intrării TE, care s-ar pierde"
           if tt else "")
    rem = ("DDR-ul din amonte de tip B (sau F-B / B+, pentru c.c. neted) — dacă e deja de tip B, declară tipul DDR-ului "
           "din branșament; sau alimentarea stației VE dintr-un circuit fără DDR tip AC / A în amonte, conform "
           "producătorului; sau stație cu RDC-DD 6 mA c.c. și DDR VE tip A, cu DDR-ul din amonte cel puțin tip A")
    emite(j, "V43", BLOCANT if tt else AVERTISMENT, f"{g['obiect']} vs {am_nume}", "ve_dc", av=g["obiect"],
          tip_av=tip_av, am=am_nume, IdN_am=am_idn, tip_am=am_tip, detaliu=det, rem=rem)
    j.verificari[-1]["camp"] = "alimentare.DDR_bransament_tip"


def fara_chei_receptor(txt):
    """v1.7 (m-c5): înlocuiește cheile interne ale receptorilor („prize_bucatarie”, „vehicul_electric”, „plita” între
    ghilimele) cu denumirea românească (ETICHETE_RECEPTOR)."""
    for k in sorted(ETICHETE_RECEPTOR, key=len, reverse=True):
        if k not in txt:
            continue
        txt = txt.replace(f"„{k}”", f"„{ETICHETE_RECEPTOR[k]}”")
        if "_" in k:
            txt = re.sub(r"(?<![\w.])" + re.escape(k) + r"(?![\w])", ETICHETE_RECEPTOR[k], txt)
    return txt


def _agrega_v43(j, lst):
    """v1.6 (P2-1): verificările V43 ale grupelor față de DDR-ul branșamentului, agregate — o singură atenționare pentru
    toate grupele cu același mesaj („… DDR1–DDR4”), în loc de una pe grupă."""
    pe_msg = {}
    for ob_g, v in lst:
        cheie = (v["cod"], v["nivel"], v["mesaj"].replace(ob_g, "\x00"), v.get("remediere", "").replace(ob_g, "\x00"))
        pe_msg.setdefault(cheie, []).append((ob_g, v))
    for (cod, nivel, msg, rem), el in pe_msg.items():
        nume = [o for o, _ in el]
        nr = [int(o[3:]) for o in nume if o.startswith("DDR") and o[3:].isdigit()]
        if len(nume) > 1 and len(nr) == len(nume) and nr == list(range(nr[0], nr[0] + len(nr))):
            et = f"{nume[0]}–{nume[-1]}"
        else:
            et = ", ".join(nume)
        ob = el[0][1]["obiect"].replace(nume[0], et)
        if nivel == "INFO":
            j.info.append({"cod": cod, "nivel": nivel, "obiect": ob, "mesaj": msg.replace("\x00", et)})
        else:
            j.verificari.append({"cod": cod, "nivel": nivel, "obiect": ob, "mesaj": msg.replace("\x00", et),
                                 "remediere": rem.replace("\x00", et)})


def _calculeaza(inp, j, cutie):
    from .scheme import _bransament, _tt_ra, RETELE, _fd
    rez = {}
    retea = inp.get("retea")
    retea = RETELE.get(_fd(retea)) if isinstance(retea, str) else None
    if retea not in ("mono", "tri"):
        # rețeaua nu se presupune: monofazat / trifazat schimbă tot tabloul (BMPM / BMPT, Q, DDR 2P / 4P, faze)
        gol = inp.get("retea") is None or (isinstance(inp.get("retea"), str) and not inp["retea"].strip())
        j.emite("V07", "BLOCANT", "retea", "rețeaua locuinței nu este specificată" if gol
                else f"rețea invalidă: {inp.get('retea')!r}",
                "alege monofazat 230 V (BMPM) sau trifazat 3 × 400 V (BMPT), conform ATR / branșamentului existent")
        return rez
    rez["retea"] = retea
    v = _valideaza(inp, j, retea)
    if v is None:
        return rez
    al, circ = v
    cutie["circ"] = circ
    U = SQRT3 * norme.U_N_V if retea == "tri" else norme.U_0_V
    tt = inp.get("schema_pamant") == "TT"

    # ---- circuitele: intrări B.1 și Ib -----------------------------------------------------------------------
    ramuri = []
    for c in circ:
        r, d, tri = _circuit(c, retea, j)
        u = SQRT3 * norme.U_N_V if tri else norme.U_0_V
        ramuri.append({"c": c, "r": r, "d": d, "tri": tri, "Ib": r["P_kW"] * 1000.0 / (u * r["cosfi"])})

    # ---- 1. bilanț ---------------------------------------------------------------------------------------------
    pi = sum(x["r"]["P_kW"] for x in ramuri)
    p_cont = sum(x["r"]["P_kW"] for x in ramuri if x["d"]["continuu"])
    p_gen = pi - p_cont
    ks_decl = inp.get("ks") is not None
    if ks_decl:
        ks, regula = float(inp["ks"]), "declarat"
        pc = ks * pi
    else:
        n_gen = sum(1 for x in ramuri if not x["d"]["continuu"])
        # v1.7 (P2 verificator): fără receptoare generale ks nu se aplică (= 1), iar presupunerea nu mai spune
        # „ks după 0 receptoare … 0,8”
        ks = next(k for n, k in norme.LOCUINTA_KS_GENERAL if n_gen <= n) if n_gen else 1.0
        regula = (f"ks {fmt_ro(ks)} pe cele {n_gen} receptoare generale (regulă proprie §C.8 după numărul "
                  f"receptoarelor — DECIZIE proiectant), 1 pe sarcinile continue (VE, pompă de căldură, încălzire "
                  f"electrică, saună)") if n_gen else "toate receptoarele sunt sarcini continue — ks = 1"
        pc = ks * p_gen + p_cont
        if n_gen:
            j.presupune(f"bilanț locuință: Pc = {fmt_ro(ks)}·Σ P generale + Σ P sarcini continue (ks după "
                        f"{n_gen} {'receptor general' if n_gen == 1 else 'receptoare generale'}, DECIZIE proiectant — "
                        f"declarați coeficientul de simultaneitate ks = Pa/Pi dacă diferă)")
        else:
            j.presupune("bilanț locuință: numai sarcini continue (VE, pompă de căldură, încălzire electrică, saună) → "
                        "Pc = Σ P, fără simultaneitate (ks = 1)")
    j.ipoteza("ks", ks, not ks_decl)
    ib_pc = pc * 1000.0 / (U * norme.LOCUINTA_COSFI)
    pa = al.get("P_aprobata_kW")
    ib_pa = pa * 1000.0 / (U * norme.LOCUINTA_COSFI) if pa is not None else None
    ib = ib_pa if ib_pa is not None else ib_pc        # P0-1: cu P aprobată, Ib general = sarcina contractată
    rez["bilant"] = {"Pi_kW": pi, "P_general_kW": p_gen, "P_continuu_kW": p_cont, "ks": ks, "ks_regula": regula,
                     "Pc_kW": pc, "cosfi": norme.LOCUINTA_COSFI, "Ib_A": ib, "Ib_Pc_A": ib_pc,
                     "Ib_baza": "P aprobată (ATR)" if pa is not None else "Pc din bilanț",
                     "P_aprobata_kW": pa, "n_circuite": len(ramuri)}
    uf = '√3·400' if retea == 'tri' else '230'
    j.pas(f"Bilanț locuință: Σ Pi = {fmt_ro(pi)} kW (general {fmt_ro(p_gen)} kW, continuu {fmt_ro(p_cont)} kW); "
          f"Pc = {fmt_ro(pc)} kW ({regula}); Ib(Pc) = {fmt_ro(pc)}·1000/({uf}·{fmt_ro(norme.LOCUINTA_COSFI)}) = "
          f"{fmt_ro(ib_pc)} A" + (f"; Ib general din P aprobată = {fmt_ro(pa)}·1000/({uf}·"
                                  f"{fmt_ro(norme.LOCUINTA_COSFI)}) = {fmt_ro(ib_pa)} A (Pc informativ)"
                                  if pa is not None else ""))
    if pa is not None and lt(pa, pc):
        emite(j, "V46", AVERTISMENT, "schema", "pc", Pc=pc, P=pa,
              rem="solicită ATR pentru mărirea puterii aprobate" + (" sau trecerea pe branșament trifazat"
                                                                     if retea == "mono" else "") +
              ", ori declară ks = Pa/Pi (simultaneitate justificată) / gestionarea dinamică a sarcinii (DLM la VE)")

    # ---- 2. grupele DDR și repartizarea pe faze (pe curentul de calcul, v1.6 m-n3) ------------------------------
    grupe, sarc = _grupeaza_si_repartizeaza(ramuri, retea, ks, ks_decl)
    calc, cont = _curenti_faza(ramuri, retea, ks, ks_decl)
    faze_act = ("L1", "L2", "L3") if retea == "tri" else ("L1",)
    f_max = max(faze_act, key=lambda f: (calc[f], -faze_act.index(f)))
    i_calc_max = calc[f_max]
    rez["faze"] = {"L1_A": sarc["L1"], "L2_A": sarc["L2"] if retea == "tri" else 0.0,
                   "L3_A": sarc["L3"] if retea == "tri" else 0.0,
                   "L1_calc_A": calc["L1"], "L2_calc_A": calc["L2"], "L3_calc_A": calc["L3"],
                   "L1_continuu_A": cont["L1"], "L2_continuu_A": cont["L2"], "L3_continuu_A": cont["L3"],
                   "faza_max": f_max, "I_calc_max_A": i_calc_max,
                   "definitie_calc": "Ib de calcul pe fază = ks·Σ Ib general + Σ Ib continuu (ks declarat: ks·Σ Ib)",
                   "repartizare": "pe curentul de calcul: 3F, faze impuse, apoi monofazatele descrescător (§C.8 pct. 5)"}
    if retea == "tri":
        imed = sum(sarc.values()) / 3.0
        dez = (max(sarc.values()) - imed) / imed * 100.0 if imed > 0 else 0.0
        cmed = sum(calc.values()) / 3.0
        dez_c = (max(calc.values()) - cmed) / cmed * 100.0 if cmed > 0 else 0.0
        rez["faze"].update({"dezechilibru_pct": dez, "dezechilibru_calc_pct": dez_c,
                            "definitie": "(Imax − Imed)/Imed, din Ib instalat al circuitelor"})
        j.pas(f"Repartizare pe faze (pe curentul de calcul): Ib instalat L1 {fmt_ro(sarc['L1'])} A, L2 {fmt_ro(sarc['L2'])} A, "
              f"L3 {fmt_ro(sarc['L3'])} A; dezechilibru {fmt_ro(dez, 1)} %; Ib de calcul (ks): L1 {fmt_ro(calc['L1'])} A, "
              f"L2 {fmt_ro(calc['L2'])} A, L3 {fmt_ro(calc['L3'])} A (dezechilibru {fmt_ro(dez_c, 1)} %)")
        if gt(dez, norme.LOCUINTA_DEZECHILIBRU_MAX_PCT):
            emite(j, "V47", AVERTISMENT, "faze", x=dez, lim=norme.LOCUINTA_DEZECHILIBRU_MAX_PCT)
    else:
        rez["faze"].update({"dezechilibru_pct": None, "definitie": "monofazat"})
        j.pas(f"Monofazat: Ib instalat L1 {fmt_ro(sarc['L1'])} A; Ib de calcul (ks) L1 {fmt_ro(calc['L1'])} A")

    # ---- 3. branșament (existent / nou) și coloana C2 -------------------------------------------------------------
    # curentul de dimensionare fără contract: max(Ib din Pc, faza cea mai încărcată)
    i_dim = ib if pa is not None else max(ib_pc, i_calc_max)
    q_decl = al.get("In_Q_bransament_A")
    bi = {"tip_schema": "bransament", "retea": retea, "cosfi": norme.LOCUINTA_COSFI,
          "_cosfi_eticheta": "coloana C2, cosφ mediu al locuinței",
          "L_coloana_m": al.get("L_coloana_m"), "cablu": dict(al.get("cablu") or {})}
    q_pres = None
    q_inv = al.get("_q_invalid")
    if q_inv is not None and q_decl is None and al["tip"] == "bransament_existent":
        # v1.7 (M-c1): Q declarat în afara seriei (V05 emis) → Q presupus = calibrul standard imediat superior, limitat la
        # limita blocului (mono: BMPM 40 A); calculul continuă, exportul rămâne refuzat
        if retea == "mono":
            serie_i, lim_i, bloc_i = SERIE_Q_MONO, norme.BMPM["I_max_A"], "BMPM"
        else:
            serie_i, lim_i, bloc_i = SERIE_Q_TRI_TOATE, norme.BMPT["BMPTi-250"]["I_max_A"], "BMPT"
        q_pres = prima_din_serie([x for x in serie_i if x <= lim_i], q_inv) or max(x for x in serie_i if x <= lim_i)
        j.presupune(f"Q branșament {fmt_ro(q_inv, 0)} A nu există în seria {bloc_i} → ignorat; Q presupus {q_pres} A "
                    f"({'calibrul standard imediat superior' if q_pres > q_inv else 'limita blocului ' + bloc_i}) — "
                    f"introdu Q-ul real din BMPM / BMPT (ATR / certificatul de racordare)")
    if al["tip"] == "bransament_existent" and q_pres is None:
        if q_decl is None:
            # P0-2: Q nedeclarat → calibrul standard ≥ Ib (nu mai mic decât sarcina), declarat ca presupus
            bloc_n, lim_b = LIMITA_BLOC[retea]
            serie = SERIE_Q_MONO if retea == "mono" else SERIE_Q_TRI
            if gt(i_dim, lim_b):
                emite(j, "V46", BLOCANT, "Q", "bloc", Ib=i_dim, bloc=bloc_n, lim=lim_b,
                      rem="declarați Q-ul de branșament existent (din ATR / certificatul de racordare) sau solicitați "
                          "ATR pentru " + ("trecerea pe branșament trifazat (BMPT)" if retea == "mono" else
                                           "un branșament cu măsură semidirectă (BMPTi)") + " / reduceți sarcina simultană")
                j.verificari[-1]["camp"] = "alimentare.In_Q_bransament_A"
                # v1.6 (UX 12): calculul continuă cu Q = limita blocului (exportul rămâne blocat)
                q_pres = max(x for x in serie if x <= lim_b)
            else:
                q_pres = prima_din_serie(serie, i_dim)
            baza = " din P aprobată" if pa is not None else ""
            j.presupune(f"Q branșament existent nedeclarat → Q presupus {q_pres} A (calibrul standard ≥ Ib "
                        f"{fmt_ro(i_dim)} A{baza}) — introduceți Q-ul real din BMPM/BMPT (ATR / certificatul de racordare)")
            # v1.6 (N5): Q-ul unui branșament EXISTENT e o dată, nu se alege — AVERTISMENT vizibil (DECIZIE: nu BLOCANT,
            # spre deosebire de rețea; mesajele BLOCANTE calculate pe Q presupus o spun explicit, m-n5)
            if "In_Q_bransament_A" not in (al.get("_invalide") or []):
                # v1.7: Q invalid (text / ≤ 0) are deja V07 BLOCANT — nu se mai spune „nedeclarat”
                emite(j, "V46", AVERTISMENT, "Q", "q_pres", Q=q_pres, Ib=i_dim, baza=baza,
                      rem="introduceți Q branșament real (calibrul RCBO / MCB din BMPM / BMPT, din ATR sau "
                          "certificatul de racordare)")
    if al["tip"] == "bransament_existent":
        q_in = q_decl if q_decl is not None else q_pres
        bi["Q_In_A"] = q_in
        # v1.6 (m8): coloana poartă curentul fazei celei mai încărcate (nu Ib echilibrat din Pa), limitat la In Q
        bi["Ib_A"] = min(float(q_in), max(i_dim, i_calc_max))
    else:
        bi["Ib_A"] = max(i_dim, ib_pc, i_calc_max)
    if pa is None and al["tip"] == "bransament_existent" and "P_aprobata_kW" not in (al.get("_invalide") or []):
        emite(j, "V46", AVERTISMENT, "schema", "pa_pres", Pc=pc, Ib=ib_pc,
              rem="introduceți puterea aprobată din ATR / certificatul de racordare")
    for k in ("Ik3_OD_kA", "Zb_OD_ohm", "schema_pamant", "RA_ohm"):
        if inp.get(k) is not None:
            bi[k] = inp[k]
    if inp.get("Zb_OD_ohm") is None:
        # v1.6 (P1-10): Zbuclă OD implicită după zonă
        if al.get("zona") == "rural":
            z = norme.LOCUINTA_ZB_OD_RURAL_OHM
            r0, x0 = norme.OD_ZBUCLA_IMPLICIT_OHM
            m0 = math.hypot(r0, x0)
            bi["Zb_OD_ohm"] = [z * r0 / m0, z * x0 / m0]
            # v1.7 (N11): valoarea după zonă e PRESUPUSĂ — nota de ipoteze / planșa nu o mai atribuie ATR-ului
            bi["_zb_presupus"] = "zonă rurală"
            j.presupune(f"Zbuclă OD {fmt_ro(z, 2)} Ω (zonă rurală) — presupus, valoare implicită prudentă [NEVERIFICAT]; "
                        f"se confirmă cu OD / ATR")
        else:
            j.presupune("zona alimentării nedeclarată → Zbuclă OD implicită urbană |Z| = 0,201 Ω (presupus); la case "
                        "rurale / capăt de linie declarați zona „rural” (0,45 Ω) sau Zb confirmată de OD / ATR")
    bi["_tt_ddr_defect"] = True
    if bi["cablu"].get("material") is None:
        bi["cablu"]["material"] = "Cu"
        j.presupune("coloană C2 Cu (locuință)")
    if bi["cablu"].get("metoda") is None:
        if al.get("pozare_coloana"):
            bi["cablu"]["metoda"] = al["pozare_coloana"]
        else:
            j.presupune("coloana C2 pozată în pământ (D1, CYABY) — pentru apartament / tablou în clădire declarați "
                        "pozarea coloanei „în clădire” (B2, CYY-F)")
    if al.get("L_coloana_m") is None:
        bi["L_coloana_m"] = 15.0
        j.presupune("lungime coloană BMPM/BMPT → tabloul locuinței 15 m")

    # v1.6 (N2): bugetul de ΔU — coloana se mărește ÎNAINTEA circuitelor finale. Proba (jurnal temporar): dacă vreun
    # circuit ar ieși peste secțiunea pe care o are cu coloana la buget, coloana primește ținta ΔU ≤ buget.
    rb = _bransament(dict(bi, cablu=dict(bi["cablu"])), Jurnal())
    buget = norme.LOCUINTA_DU_COLOANA_BUGET_PCT
    c2p, ctxp = rb.get("C2") or {}, rb.get("_ctx_C2")
    rez_buget = None
    if ctxp is not None and bi["cablu"].get("S_fortat") is None and gt(c2p.get("dU_ramura_pct") or 0.0, buget):
        du_or = (ctxp["dU_pct"] or 0.0) - (c2p.get("dU_ramura_pct") or 0.0)
        ctx_b = dict(ctxp, dU_pct=du_or + buget)

        def sect(ctx_):
            jt0 = Jurnal()
            out = []
            for x in ramuri:
                rr0 = calculeaza_ramura(dict(x["r"], cablu=dict(x["r"]["cablu"])), ctx_, jt0, "tmp")["rezultat"]
                out.append((rr0.get("n_paralel") or 1, rr0.get("S_faza_mm2") or 0))
            return out
        marite = [x["c"]["obiect"] for x, a_, b_ in zip(ramuri, sect(ctxp), sect(ctx_b)) if a_ > b_]
        if marite:
            bi["_tinta_dU_C2"] = du_or + buget
            rez_buget = (c2p.get("dU_ramura_pct"), c2p.get("S_faza_mm2"), marite)
    rb = _bransament(bi, j)
    ctx = rb.pop("_ctx_C2", None)
    q_br = rb.pop("_prot_Q", None)
    rez["alimentare"] = {k: v for k, v in rb.items() if k not in ("C2", "schema_pamant", "nota_schema_pamant", "C1")}
    rez["alimentare"]["tip"] = al["tip"]
    rez["alimentare"]["zona"] = al.get("zona")
    if pa is not None:
        rez["alimentare"]["Pa_kW"] = pa
    if q_pres is not None:
        rez["alimentare"]["Q_presupus"] = True
    if pa is None and al["tip"] == "bransament_existent":
        rez["alimentare"]["Pa_presupus"] = True
    # v1.6 (N3): conductoarele racordului OD (C1) — TT: fără PEN
    rez["alimentare"]["C1_conductoare"] = (("3L + N" if retea == "tri" else "L + N") if tt
                                           else ("3L + PEN" if retea == "tri" else "L + PEN"))
    if "C2" in rb:
        col = dict(rb["C2"], descriere="coloana BMPM/BMPT → tabloul locuinței (TE)")
        if tt:
            # v1.6 (N3): TT — coloana NU transportă PE/PEN; PE-ul instalației pornește din priza locală (PPL → BPE)
            from .texte import text_cablu
            col.update({"conductoare": "3L + N" if retea == "tri" else "L + N", "PE": "fara", "S_PE_mm2": None,
                        "PE_origine": "priza_locala", "legatura_BPE": False,
                        "PE_nota": "TT: coloana fără PE / PEN (L + N); PE-ul instalației pornește din priza de pământ "
                                   "locală (PPL → BPE)"})
            col["cablu"] = text_cablu(col["material"], col["izolatie"], col["metoda"], col.get("n_paralel") or 1,
                                      col["S_faza_mm2"], col.get("S_N_mm2"), None, "fara", retea,
                                      monopolar=col.get("monopolar", False))
        else:
            col.update({"conductoare": "3L + N + PE" if retea == "tri" else "L + N + PE", "PE_origine": "bloc",
                        "legatura_BPE": True,
                        "PE_nota": f"TN-C-S: PEN separat pe BN în {rb.get('bloc') or 'bloc'}; PE {fmt_ro(col.get('S_PE_mm2'))} "
                                   f"mm² din coloană la BPE"})
        if rez_buget is not None:
            col["marit_buget_dU"] = {"buget_pct": buget, "dU_initial_pct": rez_buget[0],
                                     "S_initial_mm2": rez_buget[1], "circuite": rez_buget[2]}
            j.pas(f"Coloana C2: ΔU {fmt_ro(rez_buget[0])} % pe {fmt_ro(rez_buget[1])} mm² > bugetul de "
                  f"{fmt_ro(buget)} % și circuitele {', '.join(rez_buget[2])} s-ar mări pentru ΔU → coloana mărită "
                  f"întâi la {fmt_ro(col.get('S_faza_mm2'))} mm² (ΔU {fmt_ro(col.get('dU_ramura_pct'))} %), §C.8 pct. 2")
        rez["coloana"] = col
    if ctx is None:
        return rez
    in_q_br = (rb.get("Q") or {}).get("In_A")

    # ---- 3b. V46 pe faza cea mai încărcată (C1) și P aprobată față de Q ------------------------------------------
    if in_q_br:
        lim113 = norme.LOCUINTA_I_NEDECLANSARE * in_q_br
        rem = ("solicită ATR pentru mărirea puterii (Q branșament mai mare)" +
               (" sau trecerea pe branșament trifazat" if retea == "mono" else " / mută circuite monofazate pe altă fază")
               + ", gestionarea dinamică a sarcinii (DLM la VE) sau redu circuitele simultane")
        if q_pres is not None:
            rem = "introdu Q branșament real din BMPM / BMPT (ATR / certificatul de racordare); altfel " + rem
        niveluri = []
        for f in faze_act:
            i_f = calc[f]
            if gt(i_f, lim113):
                niveluri.append((2, i_f, f, "ib"))
            elif gt(i_f, in_q_br) and cont[f] > 0:
                niveluri.append((2, i_f, f, "cont"))
            elif gt(i_f, in_q_br):
                niveluri.append((1, i_f, f, "av"))
        if niveluri:
            nv, i_f, f, var = max(niveluri)
            emite(j, "V46", BLOCANT if nv == 2 else AVERTISMENT, "Q", var, Ib=i_f, In=in_q_br, lim=lim113,
                  faza=f, cont=cont[f], rem=rem)
            if q_pres is not None:
                # m-n5: mesajul spune că Q e presupus
                v = j.verificari[-1]
                v["mesaj"] = (f"Q branșament presupus {in_q_br} A (nedeclarat) — " + v["mesaj"])
        if ib_pa is not None and q_decl is not None and gt(ib_pa, lim113):
            emite(j, "V46", BLOCANT, "Q", "pa", P=pa, Ib=ib_pa, lim=lim113, rem=rem)
    ik3_te = ctx["Ik3_kA"]
    amonte_txt = (f"Q branșament {(rb.get('Q') or {}).get('tip', '')} {in_q_br} A + SF gG").replace("  ", " ")

    # ---- 4. Q general al TE (întreruptor-separator implicit) și SPD T2 ----------------------------------------
    poli = "4P" if retea == "tri" else "2P"
    tip_qg = str(inp.get("Q_general_tip") or "IS").upper()
    if tip_qg not in ("IS", "MCB"):
        emite(j, "V12", BLOCANT, "Q general", "camp", camp="Q_general_tip", valoare=inp.get("Q_general_tip"))
        tip_qg = "IS"
    if tip_qg == "IS":
        # IS protejat la suprasarcină de Q branșament: In IS ≥ In Q (Ib > In Q e verificat de V46, nu mărește IS)
        In_g = prima_din_serie(norme.IS_IN_A, in_q_br or ib)
        icc, ok = _capacitate_conditionata(ik3_te)
        rez["Q_general"] = {"tip": "IS", "In_A": In_g, "poli": poli, "Icc_kA": icc,
                            "descriere": "întreruptor-separator (fără declanșare — selectivitate asigurată față de Q "
                                         "branșament; In ≥ In Q branșament, protejat la suprasarcină de Q)"}
        j.pas(f"Q general TE: întreruptor-separator {poli} In {In_g} A ≥ In Q branșament {in_q_br} A (protejat de Q)")
        emite(j, "V33", INFO if ok else AVERTISMENT, "Q general", "cond" if ok else "cond_AV",
              aparat=f"IS {In_g} A (curent condiționat de scurtcircuit)", icu=icc, ik3=ik3_te, amonte=amonte_txt)
    else:
        ib_q = min(ib, in_q_br) if in_q_br else ib      # Ib > In Q e verificat de V46, nu mărește Q general
        cand = [x for x in pr.SERII["MCB"] if x >= ib_q - 1e-9 and (in_q_br is None or x <= in_q_br)]
        In_g = cand[-1] if cand else prima_din_serie(pr.SERII["MCB"], ib_q)
        qg = pr.construieste("MCB", In_g, In_g, "C", are_aval=True)
        qg["Icu_kA"], ok = pr.alege_icu("MCB", ik3_te)
        rez["Q_general"] = {"tip": "MCB", "curba": "C", "In_A": In_g, "poli": poli, "Icu_kA": qg["Icu_kA"]}
        if in_q_br and gt(In_g, in_q_br):
            emite(j, "V40", BLOCANT, "Q general", "loc", aparat=f"Q general MCB C{In_g}", a=in_q_br, b=In_g)
        if q_br is not None:
            pr.selectivitate(q_br, qg, ik3_te, "Q general vs Q branșament", j)
    # v1.6 (m-n2 / N4): protecția de rezervă a SPD-ului (F2) — MCB C25 (norme.LOCUINTA_SPD_REZERVA), nu peste
    # Q general MCB / Q branșament; poli = poli SPD; Icu ≥ Ik3 la bara TE
    poli_spd = "1P+N" if retea == "mono" else "3P+N"
    rz = norme.LOCUINTA_SPD_REZERVA
    lim_rz = min(x for x in (rz["In_A"], in_q_br, rez["Q_general"]["In_A"] if tip_qg == "MCB" else None) if x)
    In_rz = max([x for x in pr.SERII["MCB"] if x <= lim_rz + 1e-9] or [pr.SERII["MCB"][0]])
    icu_rz, _ = pr.alege_icu("MCB", ik3_te)
    prot_rz = {"tip": rz["tip"], "In_A": In_rz, "curba": rz["curba"], "poli": poli_spd, "Icu_kA": icu_rz,
               "ref": "F2", "text": f"MCB {poli_spd} {rz['curba']}{In_rz}{NB}A"}
    rez["SPD"] = dict(norme.SPD_T2_LOCUINTA, poli=poli_spd,
                      configuratie=("CT2 („1+1” / „3+1”, eclator N–PE) — TT, în aval de DDR (SR HD 60364-5-534)" if tt
                                    else "CT1 (L–PE, N–PE) — TN-S în TE"),
                      loc="intrarea TE, după Q general",
                      protectie=f"protecție de rezervă F2: MCB {poli_spd} {rz['curba']}{In_rz}{NB}A (conform fișei SPD)",
                      protectie_rezerva=prot_rz, In_amonte_A=In_rz, prot_tip="MCB", curba_amonte=rz["curba"],
                      PE_la="BPE")
    j.pas(f"SPD T2 {poli_spd}: protecție de rezervă F2 MCB {rz['curba']}{In_rz} A (≤ {fmt_ro(lim_rz, 0)} A, fișa SPD "
          f"T2 In 20 kA admite MCB C ≤ 25…32 A), Icu {icu_rz} kA ≥ Ik3 TE {fmt_ro(ik3_te)} kA")

    # ---- 5. grupele DDR și circuitele -----------------------------------------------------------------------------
    jt = Jurnal()
    for x in ramuri:
        x["Ip"] = calculeaza_ramura(dict(x["r"], _doar_protectie=True), ctx, jt, "tmp")["Ip"] or 0
        if not x["Ip"]:
            # circuit invalid (V04 / V05 …): calibrul din intrare / cel uzual, ca grupa și desenul să existe (M-n1)
            x["Ip"] = x["r"].get("In_fortat") or x["r"].get("In_minim") or 16
            x["Ip_neales"] = True
    for x in (y for g in grupe if g["cheie"] == "fara" for y in g["membri"]):
        if x["c"]["receptor"].startswith("prize"):
            emite(j, "V29", BLOCANT, x["c"]["obiect"], "B", In=x["r"].get("In_fortat") or x["r"]["In_minim"])
        else:
            # v1.5 (M1): în locuințe toate circuitele finale au DDR ≤ 30 mA
            emite(j, "V49", BLOCANT, x["c"]["obiect"], rec=eticheta_receptor(x["c"]["receptor"]))
    sus = None
    if rb.get("RCCB"):
        sus = ddr_mod.descriere(rb["RCCB"]["IdN_mA"], rb["RCCB"].get("selectiv", True), "RCCB BMPT")
    elif (rb.get("Q") or {}).get("IdN_mA"):
        sus = ddr_mod.descriere(rb["Q"]["IdN_mA"], norme.BMPM_RCBO_SELECTIV, "RCBO BMPM")
    # v1.7 (M-c3): tipul DDR-ului 300 mA din branșament (declarat sau cel din ST 3-JT / ST 4-JT: AC)
    am_nume = "RCCB BMPT" if rb.get("RCCB") else "RCBO BMPM"
    am_idn = (rb.get("RCCB") or {}).get("IdN_mA") or (rb.get("Q") or {}).get("IdN_mA")
    am_tip = al.get("DDR_bransament_tip") or ((rb.get("RCCB") or {}).get("tip") if rb.get("RCCB")
                                              else norme.BMPM["rcd_tip"]) or "AC"
    rez["alimentare"]["DDR_bransament_tip"] = am_tip if sus is not None else None
    ra = None
    if tt:
        ra, lim = _tt_ra(inp, j)
        if lim is None:
            return rez
    v43 = []
    k_ddr = 0
    for g in grupe:
        mem = g["membri"]
        if g["cheie"] == "fara":
            g["obiect"] = "fără DDR"
            g["DDR"] = None
        else:
            k_ddr += 1
            g["obiect"] = f"DDR{k_ddr}"
            d0 = mem[0]["c"]["DDR"] if g["cheie"] in ("propriu", "VE") and isinstance(mem[0]["c"]["DDR"], dict) else None
            ve = g["cheie"] == "VE"
            idn = int(d0["IdN_mA"]) if d0 else 30
            tip_d = d0.get("tip") if d0 and d0.get("tip") else ("B" if ve else "A")
            rcbo = len(mem) == 1 and not ve      # VE: RCCB tip B + MCB (RCBO tip B — aparat rar, DECIZIE)
            # In DDR: Σ In MCB pe faza cea mai încărcată a grupei
            pe_f = {}
            for x in mem:
                for f in (("L1", "L2", "L3") if x["faza"] == "3F" else (x["faza"],)):
                    pe_f[f] = pe_f.get(f, 0.0) + x["Ip"]
            s_in = max(pe_f.values())
            if rcbo:
                In_d = mem[0]["Ip"]
                g["DDR"] = {"IdN_mA": idn, "tip": tip_d, "In_A": In_d, "poli": g["poli"], "aparat": "RCBO",
                            "curba": mem[0]["r"].get("curba"), "temporizare": "instantaneu", "selectiv": False}
            else:
                # In DDR ≥ cel mai mare MCB din grupă și ≥ min(In Q branșament, Σ In MCB pe fază): DDR-ul e protejat la
                # suprasarcină de Q-ul din amonte sau nu poate fi depășit de suma circuitelor (DECIZIE, art. 531.2);
                # In RCCB > In Q e corect (RCCB protejat de Q) — nu e V40
                ref = max(max(x["Ip"] for x in mem), min(in_q_br or s_in, s_in))
                In_d = prima_din_serie(norme.RCCB_IN_A, max(ref, norme.LOCUINTA_RCCB_IN_MIN_A)) or ref
                inc, ok = _capacitate_conditionata(ik3_te)
                g["DDR"] = {"IdN_mA": idn, "tip": tip_d, "In_A": In_d, "poli": g["poli"], "aparat": "RCCB",
                            "temporizare": "instantaneu", "selectiv": False, "Inc_kA": inc}
                emite(j, "V33", INFO if ok else AVERTISMENT, g["obiect"], "cond" if ok else "cond_AV",
                      aparat=f"RCCB {In_d} A (Inc)", icu=inc, ik3=ik3_te, amonte=amonte_txt)
            if ve:
                g["DDR"]["alternativa"] = "tip A-EV + RDC-DD 6 mA c.c. (SR HD 60364-7-722)"
                if d0 and tip_d != "B":
                    emite(j, "V49", AVERTISMENT, g["obiect"], "ve_tip", tip=tip_d, rec=eticheta_receptor("vehicul_electric"))
                if sus is not None:
                    _verifica_ve_amonte(j, g, tip_d, am_nume, am_idn, am_tip, tt, al.get("DDR_bransament_tip"))
            if d0 and d0.get("selectiv"):
                g["DDR"].update({"selectiv": True, "temporizare": "S"})
            if idn > 30:
                if any(x["c"]["receptor"].startswith("prize") for x in mem):
                    emite(j, "V29", BLOCANT, g["obiect"], "B", In=max(x["Ip"] for x in mem))
                else:
                    emite(j, "V49", BLOCANT, g["obiect"], "idn", IdN=idn, rec=eticheta_receptor(mem[0]["c"]["receptor"]))
            if tip_d == "AC":
                emite(j, "V49", AVERTISMENT, g["obiect"], "tip_ac", rec=eticheta_receptor(mem[0]["c"]["receptor"]))
            if tt and gt(ra * idn / 1000.0, 50.0):
                emite(j, "V34", BLOCANT, g["obiect"], RA=ra, IdN=idn, x=ra * idn / 1000.0)
            j.pas(f"{g['obiect']} ({NUME_GRUPE.get(g['cheie'], 'propriu')}, {g['faza']}): "
                  + (f"RCBO {idn} mA tip {tip_d} {g['poli']}, In {fmt_ro(In_d)} A (circuit singur)" if rcbo else
                     f"RCCB {idn} mA tip {tip_d} {g['poli']}, In {In_d} A ≥ max(In MCB max; min(In Q branșament, "
                     f"Σ In MCB pe fază = {fmt_ro(s_in)} A))")
                  + f"; {len(mem)} {'circuit' if len(mem) == 1 else 'circuite'}")
            if sus is not None:
                jv = Jurnal()
                ddr_mod.verifica(jv, sus, ddr_mod.descriere(idn, g["DDR"]["selectiv"], g["obiect"]),
                                 g["obiect"], RA_ohm=ra)
                v43 += [(g["obiect"], v) for v in jv.verificari + jv.info]
        cg = dict(ctx, schema="TT" if tt else ctx.get("schema", "TN"), idn_tt_mA=None, ddr_sus=None,
                  ddr_ramura=f"DDR {g['DDR']['IdN_mA']} mA ({g['obiect']})" if g["DDR"] else None)
        if tt and g["DDR"]:
            cg["tt_ddr_defect"] = {"IdN_mA": g["DDR"]["IdN_mA"], "RA_ohm": ra}
        g["circuite"] = []
        for x in mem:
            n_v0 = len(j.verificari)
            rr = calculeaza_ramura(x["r"], cg, j, x["c"]["obiect"])
            if (rr["rezultat"] or {}).get("dU_plafonat_mm2"):
                # v1.7 (m-c6): circuitul nu mai crește peste plafon — problema e coloana / poziția tabloului
                for v in j.verificari[n_v0:]:
                    if v["cod"] == "V20" and v["obiect"] == x["c"]["obiect"]:
                        v["mesaj"] += (f" — secțiunea circuitului plafonată la {fmt_ro(rr['rezultat']['dU_plafonat_mm2'], 0)}"
                                       f" mm² (ΔU la bara TE {fmt_ro(cg['dU_pct'])} %)")
                        v["remediere"] = ("mărește coloana C2 (secțiune mai mare / fără secțiune impusă) sau mută tabloul "
                                          "mai aproape de branșament; altfel scurtează / împarte circuitul (tablou secundar)")
            out = dict(rr["rezultat"], nume=x["c"].get("nume", ""), receptor=x["c"]["receptor"],
                       receptor_eticheta=eticheta_receptor(x["c"]["receptor"]),
                       receptor_calcul=x["r"]["receptor"], faza=x["faza"], P_kW=x["r"]["P_kW"],
                       DDR_grupa=g["obiect"] if g["DDR"] else None,
                       DDR_obligatoriu=x["d"]["ddr"] == "obligatoriu", continuu=x["d"]["continuu"])
            out.setdefault("obiect", x["c"]["obiect"])
            blocat = bool(rr.get("blocat")) or bool(x["c"].get("_blocat"))
            out["blocat"] = blocat
            if x["c"].get("_blocat"):
                out["blocat_coduri"] = sorted(set(x["c"]["_blocat"]))
            prot = out.get("protectie") or {}
            if not prot.get("In_A"):
                # v1.6 (M-n1 / UX 12): circuit blocat — protecția din intrare / calibrul uzual, marcată „neverificat”
                prot = {"tip": "MCB", "In_A": x["Ip"], "curba": x["r"].get("curba"), "neverificat": True}
                out["protectie"] = prot
            if g["DDR"] and g["DDR"]["aparat"] == "RCBO":
                out["protectie"] = dict(prot, tip="RCBO", IdN_mA=g["DDR"]["IdN_mA"], tip_ddr=g["DDR"]["tip"],
                                        poli="1P+N" if g["poli"] == "2P" else "4P")
                g["DDR"]["Icn_kA"] = prot.get("Icu_kA")
            if in_q_br and prot.get("In_A") and gt(prot["In_A"], in_q_br):
                emite(j, "V40", BLOCANT, x["c"]["obiect"], "loc",
                      aparat=f"{'RCBO' if g['DDR'] and g['DDR']['aparat'] == 'RCBO' else 'MCB'} {prot.get('curba', '')}"
                             f"{prot['In_A']}", a=in_q_br, b=prot["In_A"])
            # protecția la defect (contact indirect), explicit pe fiecare circuit (P0-3)
            idn_g = g["DDR"]["IdN_mA"] if g["DDR"] else None
            if g["DDR"] and tt:
                out["protectie_defect"] = (f"DDR {idn_g} mA ({g['obiect']}) — TT: RA·IΔn = {fmt_ro(ra * idn_g / 1000.0)} V "
                                           f"≤ 50 V; Ik1/Ia doar pentru scurtcircuitul L–N")
            elif out.get("Ia_A") is not None and out.get("Ik1min_capat_A") is not None \
                    and ge(out["Ik1min_capat_A"], out["Ia_A"]):
                out["protectie_defect"] = (f"MCB: Ik1min {fmt_ro(out['Ik1min_capat_A'], 0)} A ≥ Ia {fmt_ro(out['Ia_A'], 0)} A"
                                           + (f"; DDR {idn_g} mA protecție suplimentară" if g["DDR"] else ""))
            elif blocat:
                out["protectie_defect"] = (f"DDR {idn_g} mA ({g['obiect']}) — circuit blocat, Ik1 necalculat" if g["DDR"]
                                           else "circuit blocat, neverificat")
            elif g["DDR"]:
                out["protectie_defect"] = f"DDR {idn_g} mA ({g['obiect']}) — Ik1min < Ia"
            else:
                out["protectie_defect"] = "neasigurată fără DDR"
            if x["c"]["receptor"] == "sauna":
                out["cablu_nota"] = norme.LOCUINTA_SAUNA_CABLU
            g["circuite"].append(out)
        if g["DDR"]:
            fz = sorted({x["faza"] for x in mem})
            g["faza"] = "3F" if "3F" in fz or len(fz) > 1 else fz[0]
            if g["DDR"]["aparat"] == "RCBO" and g["DDR"].get("Icn_kA") is None:
                g["DDR"]["Icn_kA"] = icu_rz
    _agrega_v43(j, v43)
    rez["grupe_DDR"] = [{k: g[k] for k in ("obiect", "DDR", "faza", "circuite") if k in g} |
                        {"grupa": NUME_GRUPE.get(g["cheie"], "propriu")} |
                        ({"nivel": nivel_din_nume(g["membri"][0]["c"].get("nume"))} if g["cheie"] == "iluminat" else {})
                        for g in grupe]
    rez["circuite_blocate"] = [c["obiect"] for g in rez["grupe_DDR"] for c in g["circuite"] if c.get("blocat")]

    # ---- nota 3 -------------------------------------------------------------------------------------------------
    spl = inp.get("schema_pamant") or "TN-C-S"
    rez["schema_pamant"] = spl
    bloc = rb.get("bloc") or "bloc"
    n_g = sum(1 for g in grupe if g["DDR"])
    if spl == "TT":
        ddr_txt = (f"{'RCCB' if rb.get('RCCB') else 'RCBO'} {bloc} 300{NB}mA; DDR {30}{NB}mA pe {n_g} "
                   f"{'grupă' if n_g == 1 else 'grupe'} de circuite (protecția la defect în TT)")
        rez["nota_schema_pamant"] = nota_schema_pamant("tablou", "TT", bloc, inp.get("RA_ohm") if inp.get("RA_ohm")
                                                       is not None else ra, idn_mA=300, ddr_txt=ddr_txt)
    else:
        rez["nota_schema_pamant"] = (f"Schemă de legare la pământ: TN-C-S cu separarea PEN pe BN în {bloc}; TN-S în "
                                     f"tabloul locuinței, DDR 30{NB}mA pe {n_g} {'grupă' if n_g == 1 else 'grupe'} de "
                                     f"circuite. Rp ≤ 4{NB}Ω.")
    return rez

engine/calc/pamant.py:
"""pamant.py — calculul prizei de pământ (SPEC §C.7, v1.3): electrozi verticali în linie legați cu platbandă orizontală.

Intrare (cheia opțională `priza` a oricărei scheme; fără ea calculul NU rulează și nota de pe planșă rămâne
„priza de pământ: calcul separat”):

    {"rho_ohm_m": 100, "electrozi": {"n": 2, "L_m": 3, "d_m": 0.0635, "distanta_m": 6},
     "platbanda": {"L_m": 12, "latime_m": 0.04, "grosime_m": 0.004, "adancime_m": 0.8},   # sau false = fără platbandă
     "R_limita_ohm": null, "sezon": "I"|"II"|"III"|"implicit", "psi": 1.6, "psi_platbanda": 3.5}
    platbanda.L_m implicit = (n − 1)·a + L_racord_m (implicit 5 m); R_limita_ohm doar poate COBORÎ limita normată.

Formule (1.RE-Ip 30-2004 / STAS 12604/5-90, forma 0,366·ρ/L·lg(...) = ρ/(2πL)·ln(...)):
    ρ_e   = ψ_e·ρ ; ρ_pl = ψ_pl·ρ                                   (coeficienți sezonieri distincți, v1.3 R5)
    R_e   = ρ_e/(2πL)·[ln(2L/d) + ½·ln((4t + L)/(4t − L))],  t = h + L/2   (electrod vertical, capul la adâncimea h)
    R_pl  = ρ_pl/(2πL_p)·ln(2·L_p²/(b·h))                                    (platbandă orizontală, lățime b, adâncime h)
    Rp    = R_e·R_pl/(R_e·η_p + n·R_pl·η_e)                                 (combinația, coeficienți de utilizare η)
    Rp    = R_e/(n·η_e)                                                     (fără platbandă)
η_e, η_p: norme.PRIZA_ETA_ELECTROZI / PRIZA_ETA_PLATBANDA în funcție de n și a/L [NEVERIFICAT].
"""
import math

from . import norme
from .texte import fmt_ro, NB, X

OBIECT = "priza de pământ"
ZONE_IMPLICIT = ("k_sezon", "implicit", "")


def _numar(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


class _Erori(list):
    """Lista erorilor de validare: (cod, varianta, parametri) pentru verificari.emite."""

    def param(self, camp, x, conditie, cod="V07"):
        if cod == "V10":
            self.append(("V10", "", {"parametru": f"priza.{camp} = {x if not _numar(x) else fmt_ro(x, 4)}",
                                     "tabel": conditie}))
        elif cod == "V12":
            self.append(("V12", "camp", {"camp": f"priza.{camp}", "valoare": x}))
        else:
            self.append(("V07", "param", {"camp": f"priza.{camp}", "x": x if _numar(x) else repr(x),
                                          "conditie": conditie}))


def normalizeaza(p):
    """Validează și completează intrarea `priza` cu valorile implicite (declarate). Întoarce (par, erori, presupuse);
    la prima eroare (V07 valoare ≤ 0 / nenumerică / n nu e întreg ≥ 1, V10 în afara tabelelor, V12 enumerare)
    `par` este None."""
    er = _Erori()
    pres = []
    if not isinstance(p, dict):
        er.param("", p, "se așteaptă un obiect {rho_ohm_m, electrozi, platbanda, R_limita_ohm, sezon}")
        return None, er, pres

    def num(d, camp, cheie, implicit, text_implicit, cond=">0"):
        v = d.get(cheie)
        if v is None:
            if text_implicit:
                pres.append(text_implicit)
            return implicit
        if not _numar(v):
            er.param(camp, v, "valoare nenumerică (se așteaptă un număr)")
            return None
        if cond == ">=0" and not v >= 0:
            er.param(camp, v, "trebuie ≥ 0")
            return None
        if cond == ">0" and not v > 0:
            er.param(camp, v, "trebuie > 0")
            return None
        if cond == "int>=1" and not (float(v).is_integer() and v >= 1):
            er.param(camp, v, "trebuie număr întreg ≥ 1")
            return None
        return float(v) if cond != "int>=1" else int(v)

    rho = num(p, "rho_ohm_m", "rho_ohm_m", norme.PRIZA_RHO_IMPLICIT_OHM_M,
              f"ρ sol = {fmt_ro(norme.PRIZA_RHO_IMPLICIT_OHM_M)} Ω·m (sol argilos-nisipos) — măsurați rezistivitatea")
    if er:
        return None, er, pres
    if rho > norme.PRIZA_RHO_MAX_OHM_M:
        er.param("rho_ohm_m", rho, f"ρ ≤ {fmt_ro(norme.PRIZA_RHO_MAX_OHM_M, 0)} Ω·m (peste: rocă, priză specială)", "V10")
        return None, er, pres

    el = p.get("electrozi")
    if el is None:
        el = {}
    if not isinstance(el, dict):
        er.param("electrozi", el, "se așteaptă un obiect {n, L_m, d_m, distanta_m}")
        return None, er, pres
    n = num(el, "electrozi.n", "n", norme.PRIZA_N_IMPLICIT, None, "int>=1")      # declarat după dimensionare
    L = num(el, "electrozi.L_m", "L_m", norme.PRIZA_ELECTROD_L_IMPLICIT_M, None) if not er else None
    d = num(el, "electrozi.d_m", "d_m", norme.PRIZA_ELECTROD_D_IMPLICIT_M, None) if not er else None
    if el.get("L_m") is None and el.get("d_m") is None and not er:
        pres.append("electrozi țeavă OL-Zn 2½″ (Ø 63,5 mm) × 3 m")
    elif not er and (el.get("L_m") is None or el.get("d_m") is None):
        pres.append(f"electrod {'L = 3 m' if el.get('L_m') is None else 'Ø 63,5 mm (2½″)'}")
    if er:
        return None, er, pres
    a = num(el, "electrozi.distanta_m", "distanta_m", norme.PRIZA_A_PE_L_IMPLICIT * L,
            f"distanța între electrozi a = 2·L = {fmt_ro(norme.PRIZA_A_PE_L_IMPLICIT * L)} m")
    if er:
        return None, er, pres
    if n > norme.PRIZA_N_MAX:
        er.param("electrozi.n", n, f"n ≤ {norme.PRIZA_N_MAX} electrozi în linie (tabelele coeficienților de utilizare)", "V10")
    elif L > 30.0:
        er.param("electrozi.L_m", L, "L ≤ 30 m (peste: priză de adâncime, calcul dedicat)", "V10")
    elif d >= L:
        er.param("electrozi.d_m", d, "d < L (electrod vertical)", "V10")
    elif n > 1 and a / L < 1.0 - 1e-9:
        er.param("electrozi.distanta_m", a, f"a/L ≥ 1 (a/L = {fmt_ro(a / L, 2)}; tabelele η încep la a/L = 1)", "V10")
    if er:
        return None, er, pres

    pl = p.get("platbanda", {})
    if pl is None:
        pl = {}
    cu_pl = pl is not False
    Lp = b = g = None
    Lr = 0.0
    h = norme.PRIZA_ADANCIME_IMPLICIT_M
    Lp_impus = False
    if cu_pl:
        if not isinstance(pl, dict):
            er.param("platbanda", pl, "se așteaptă un obiect {L_m, L_racord_m, latime_m, adancime_m} sau false")
            return None, er, pres
        # v1.3 R5 (M5-1): n electrozi în linie se întind pe (n − 1)·a; se adaugă racordul la piesa de separație
        Lr = num(pl, "platbanda.L_racord_m", "L_racord_m", norme.PRIZA_L_RACORD_IMPLICIT_M,
                 f"racord platbandă → piesa de separație {fmt_ro(norme.PRIZA_L_RACORD_IMPLICIT_M)} m" if pl.get("L_m") is None
                 else None, ">=0")
        if er:
            return None, er, pres
        Lp_impus = pl.get("L_m") is not None
        Lp0 = (n - 1) * a + Lr
        Lp = num(pl, "platbanda.L_m", "L_m", Lp0, None)                         # declarat după dimensionare
        b = num(pl, "platbanda.latime_m", "latime_m", norme.PRIZA_PLATBANDA_LATIME_IMPLICIT_M, None) if not er else None
        g = num(pl, "platbanda.grosime_m", "grosime_m", norme.PRIZA_PLATBANDA_GROSIME_IMPLICIT_M, None) if not er else None
        h = num(pl, "platbanda.adancime_m", "adancime_m", norme.PRIZA_ADANCIME_IMPLICIT_M, None) if not er else None
        if not er and (pl.get("latime_m") is None or pl.get("adancime_m") is None):
            pres.append("platbandă OL-Zn 40 × 4 mm la 0,8 m adâncime")
        if er:
            return None, er, pres
        if h > 5.0:
            er.param("platbanda.adancime_m", h, "adâncime ≤ 5 m", "V10")
        elif 2 * Lp ** 2 / (b * h) <= math.e:
            er.param("platbanda.L_m", Lp, "platbandă prea scurtă față de b·h (ln(2L²/(b·h)) ≤ 1, formula nu se aplică)", "V10")
    else:
        h = num(el, "electrozi.adancime_m", "adancime_m", norme.PRIZA_ADANCIME_IMPLICIT_M,
                "capul electrozilor la 0,8 m adâncime")
    if er:
        return None, er, pres

    # coeficienții sezonieri ψ (v1.3 R5, M5-1): distincți pentru electrozi (ψ_e) și platbandă (ψ_pl)
    sez = p.get("sezon")
    psi = p.get("psi")
    psi_pl = p.get("psi_platbanda")
    if psi is None and _numar(sez):
        psi = sez
    zona = None
    if sez is not None and not _numar(sez):
        z = str(sez).strip()
        if z.upper() in norme.PRIZA_PSI_ZONE:
            zona = z.upper()
        elif z.lower() not in ZONE_IMPLICIT:
            er.param("sezon", sez, "", "V12")
            return None, er, pres
    for camp, v, lo, hi, txt in (("psi", psi, 1.0, 3.0, "ψ_e ∈ [1; 3] (1.RE-Ip 30: 1,4…1,8 la electrozi verticali)"),
                                 ("psi_platbanda", psi_pl, 1.0, 7.0, "ψ_pl ∈ [1; 7] (1.RE-Ip 30: 2,5…4,5 la platbandă)")):
        if v is not None:
            if not _numar(v):
                er.param(camp, v, "valoare nenumerică (se așteaptă un număr)")
            elif not lo <= v <= hi:
                er.param(camp, v, txt, "V10")
            if er:
                return None, er, pres
    zona_ef = zona or "II"
    if psi is None:
        psi = norme.PRIZA_PSI_ZONE[zona_ef]
        if zona is None:
            pres.append(f"coeficient sezonier electrozi ψ_e = {fmt_ro(psi)} (zona climatică II, 1,4…1,8)")
    if psi_pl is None and cu_pl:
        psi_pl = norme.PRIZA_PSI_PLATBANDA_ZONE[zona_ef]
        if zona is None:
            pres.append(f"coeficient sezonier platbandă ψ_pl = {fmt_ro(psi_pl)} (zona climatică II, 2,5…4,5)")

    rl = p.get("R_limita_ohm")
    if rl is not None and (not _numar(rl) or not rl > 0):
        er.param("R_limita_ohm", rl, "trebuie > 0" if _numar(rl) else "valoare nenumerică (se așteaptă un număr)")
        return None, er, pres
    par = {"n_implicit": el.get("n") is None, "rho": rho, "psi": float(psi), "psi_pl": float(psi_pl) if psi_pl is not None else None, "zona": zona,
           "n": n, "L": L, "d": d, "a": a, "platbanda": cu_pl, "Lp": Lp, "L_racord": Lr, "Lp_impus": Lp_impus,
           "b": b, "g": g, "h": h, "R_limita": float(rl) if rl is not None else None}
    return par, er, pres


def presupuneri_adoptate(par, c0, c):
    """v1.3 (P0-2, pct. 3): valorile presupuse ale prizei declarate cu valorile ADOPTATE după dimensionarea automată
    (numărul de electrozi și lungimea platbandei), cu valorile inițiale între paranteze când diferă."""
    out = []
    marit = c["n"] != c0["n"]
    if par["n_implicit"] or marit:
        t = f"priză: {c['n']} {'electrod' if c['n'] == 1 else 'electrozi'}"
        if marit:
            t += f" (mărit automat de la {c0['n']} pentru Rp ≤ limită)"
        out.append(t)
    if par["platbanda"] and (not par["Lp_impus"] or marit):
        t = f"platbandă {fmt_ro(c['Lp'], 1)} m"
        if not par["Lp_impus"]:
            t += f" = (n − 1)·a + racord = {c['n'] - 1}·{fmt_ro(par['a'])} + {fmt_ro(par['L_racord'])} m"
        if marit:
            t += f" (inițial {fmt_ro(c0['Lp'], 1)} m)"
        out.append(t)
    return out


def r_electrod(rho_c, L, d, h):
    """R unui electrod vertical cu capul la adâncimea h: ρ/(2πL)·[ln(2L/d) + ½·ln((4t+L)/(4t−L))], t = h + L/2."""
    t = h + L / 2.0
    return rho_c / (2 * math.pi * L) * (math.log(2 * L / d) + 0.5 * math.log((4 * t + L) / (4 * t - L))), t


def r_platbanda(rho_c, Lp, b, h):
    """R platbandei orizontale: ρ/(2πL)·ln(2L²/(b·h)) (= 0,366·ρ/L·lg(2L²/(b·h)), 1.RE-Ip 30 / STAS 12604/5)."""
    return rho_c / (2 * math.pi * Lp) * math.log(2 * Lp ** 2 / (b * h))


def lungime_platbanda(par, n):
    """Lungimea platbandei pentru n electrozi (v1.3 R5): impusă + (n − n_impus)·a la electrozii adăugați, altfel
    (n − 1)·a + racordul la piesa de separație."""
    if not par["platbanda"]:
        return 0.0
    if par["Lp_impus"]:
        return par["Lp"] + max(0, n - par["n"]) * par["a"]
    return (n - 1) * par["a"] + par["L_racord"]


def calcul(par, n):
    """Rezistența prizei cu n electrozi (formulele din antetul modulului). Întoarce dict cu valorile intermediare."""
    rho_c = par["psi"] * par["rho"]
    rho_pl = par["psi_pl"] * par["rho"] if par["platbanda"] else None
    re, t = r_electrod(rho_c, par["L"], par["d"], par["h"])
    aL = par["a"] / par["L"]
    eta_e = norme.priza_eta(norme.PRIZA_ETA_ELECTROZI, n, aL)
    Lp = lungime_platbanda(par, n)
    if par["platbanda"]:
        rpl = r_platbanda(rho_pl, Lp, par["b"], par["h"])
        eta_p = norme.priza_eta(norme.PRIZA_ETA_PLATBANDA, n, aL)
        rp = re * rpl / (re * eta_p + n * rpl * eta_e)
    else:
        rpl = eta_p = None
        rp = re / (n * eta_e)
    return {"n": n, "rho_c": rho_c, "rho_pl": rho_pl, "R_e": re, "t": t, "aL": aL, "eta_e": eta_e, "Lp": Lp, "R_pl": rpl,
            "eta_p": eta_p, "Rp": rp}


def dimensioneaza(par, lim):
    """Rp cu n-ul dat; dacă depășește limita, cel mai mic n ≤ 30 cu Rp ≤ limită (platbanda crește cu a la fiecare
    electrod adăugat). Întoarce (calcul_initial, calcul_final, n_necesar | None)."""
    c0 = calcul(par, par["n"])
    if c0["Rp"] <= lim + 1e-9:
        return c0, c0, par["n"]
    c = c0
    if par["a"] / par["L"] < 1.0 - 1e-9:
        return c0, c0, None              # a/L < 1: nu se pot adăuga electrozi în tabelele η (doar n = 1 calculabil)
    for n in range(par["n"] + 1, norme.PRIZA_N_MAX + 1):
        c = calcul(par, n)
        if c["Rp"] <= lim + 1e-9:
            return c0, c, n
    return c0, c, None


def _idn_max(x, acc):
    """IΔn [mA] ale tuturor DDR-urilor din rezultat (DDR, RCCB, Q BMPM, IdN_amonte_mA, DDR_TT_IdN_mA)."""
    if isinstance(x, dict):
        for k, v in x.items():
            if k in ("IdN_mA", "IdN_amonte_mA", "DDR_TT_IdN_mA") and _numar(v):
                acc.append(v)
            else:
                _idn_max(v, acc)
    elif isinstance(x, list):
        for v in x:
            _idn_max(v, acc)
    return acc


def limita_normata(tip, inp, rez):
    """Limita normată Rp [Ω] și motivul: TT → RA·IΔn ≤ 50 V cu cel mai mare IΔn din schemă; PT și CEF cu PT → 1 Ω
    (NTE 001, priză comună MT/JT); altfel 4 Ω (branșament, tablou, prosumator, CEF JT, GE)."""
    if str(inp.get("schema_pamant") or "").strip().upper() == "TT":
        idn = max(_idn_max(rez, []) or [norme.BMPT_RCCB["idn_ma"]])
        return 50000.0 / idn, f"TT: RA·IΔn ≤ 50 V cu IΔn max {fmt_ro(idn, 0)} mA (SR HD 60364-4-41 art. 411.5.3)"
    cheie = "cef_pt" if tip == "cef" and inp.get("pt_Sn_kVA") is not None else tip
    v = norme.PRIZA_R_LIMITA_OHM.get(cheie, 4.0)
    if v <= 1.0:
        return v, "priză comună MT/JT la PT (NTE 001/03/00)"
    return v, "NTE 001/03/00, I7-2011, ST 4-JT (priza locală a consumatorului)"


def limita(tip, inp, rez, par):
    """Limita folosită (v1.3 R5, M5-2): `R_limita_ohm` dat poate doar COBORÎ limita normată. Întoarce
    (limita, motiv, ridicata) — `ridicata` = (valoare cerută, limita normată, motiv normat) când utilizatorul a cerut o
    limită mai mare (→ V12 BLOCANT în schemă; calculul continuă cu limita normată), altfel None."""
    ln, mn = limita_normata(tip, inp, rez)
    u = par["R_limita"]
    if u is None:
        return ln, mn, None
    if u <= ln + 1e-9:
        return u, f"impusă, ≤ limita normată {fmt_ro(ln, 2)} Ω ({mn})", None
    return ln, mn, (u, ln, mn)


def _txt_electrod(par):
    if abs(par["d"] - 0.0635) < 1e-6:
        return f"țeavă OL-Zn 2½″ (Ø 63,5{NB}mm) {X} {fmt_ro(par['L'])}{NB}m"
    return f"OL-Zn Ø {fmt_ro(par['d'] * 1000, 1)}{NB}mm {X} {fmt_ro(par['L'])}{NB}m"


def _txt_platbanda(par):
    return f"platbandă OL-Zn {fmt_ro(par['b'] * 1000, 0)}{X}{fmt_ro(par['g'] * 1000, 0)}{NB}mm"


def materiale(par, c):
    """Lista de materiale din calcul (E.1: cantități din parametri, rotunjite în sus la unitatea de livrare):
    electrozi, platbandă (+10 %, m întregi), piesă de separație, îmbinări sudate, vopsea bitum (kg întregi), săpătură
    (m întregi). v1.3 R5: fiecare articol are `ore_u` (manoperă orientativă pe unitate, norme.PRIZA_ORE_U) și `ref`
    (PP-E, PP-PL, PS, PP-SUD, PP-VOP, PP-SAP) — PS poate coincide cu piesa de separație din blocul BN·PS·PPL."""
    o = norme.PRIZA_ORE_U
    n = c["n"]
    out = [{"ref": "PP-E", "denumire": f"Electrod de pământ {_txt_electrod(par)}", "cantitate": n, "um": "buc",
            "ore_u": o["electrod"]}]
    imbinari = n + 1
    if par["platbanda"]:
        lp = math.ceil(c["Lp"] * (1 + norme.PRIZA_REZERVA_PLATBANDA) - 1e-9)
        out.append({"ref": "PP-PL", "denumire": f"{_txt_platbanda(par)[0].upper()}{_txt_platbanda(par)[1:]} (+10{NB}% rezervă)",
                    "cantitate": lp, "um": "m", "ore_u": o["platbanda_m"]})
        imbinari += max(0, math.ceil(c["Lp"] / norme.PRIZA_BARA_PLATBANDA_M - 1e-9) - 1)
    out.append({"ref": "PS", "denumire": "Piesă de separație (cutie de separație, montaj aparent)", "cantitate": 1,
                "um": "buc", "ore_u": o["piesa_separatie"]})
    out.append({"ref": "PP-SUD", "denumire": "Îmbinare sudată OL-Zn (electrod–platbandă, platbandă–platbandă, racord PS)",
                "cantitate": imbinari, "um": "buc", "ore_u": o["sudura"]})
    out.append({"ref": "PP-VOP", "denumire": "Vopsea bitum pentru protecția îmbinărilor sudate",
                "cantitate": max(1, math.ceil(imbinari * norme.PRIZA_VOPSEA_KG_IMBINARE - 1e-9)), "um": "kg",
                "ore_u": o["vopsea_kg"]})
    if par["platbanda"]:
        out.append({"ref": "PP-SAP", "denumire": f"Săpătură și astupare șanț pentru platbandă, adâncime {fmt_ro(par['h'])}{NB}m",
                    "cantitate": math.ceil(c["Lp"] - 1e-9), "um": "m", "ore_u": o["sapatura_m"]})
    return out


def pasi(par, c, lim, lim_motiv, c0=None):
    """Pașii de calcul pentru memoriu (SPEC §H.3)."""
    out = [f"Priză de pământ: ρ = {fmt_ro(par['rho'])} Ω·m{' (zona ' + par['zona'] + ')' if par.get('zona') else ''}; "
           f"electrozi ψ_e = {fmt_ro(par['psi'])} → ρ_e = {fmt_ro(c['rho_c'])} Ω·m"
           + (f"; platbandă ψ_pl = {fmt_ro(par['psi_pl'])} → ρ_pl = {fmt_ro(c['rho_pl'])} Ω·m" if par["platbanda"] else "")]
    out.append(f"Electrod vertical L = {fmt_ro(par['L'])} m, d = {fmt_ro(par['d'], 4)} m, capul la h = {fmt_ro(par['h'])} m, "
               f"t = h + L/2 = {fmt_ro(c['t'], 3)} m: R_e = ρ_e/(2πL)·[ln(2L/d) + ½·ln((4t+L)/(4t−L))] = "
               f"{fmt_ro(c['rho_c'])}/(2π·{fmt_ro(par['L'])})·[ln({fmt_ro(2 * par['L'] / par['d'], 2)}) + ½·ln("
               f"{fmt_ro((4 * c['t'] + par['L']) / (4 * c['t'] - par['L']), 4)})] = {fmt_ro(c['R_e'], 3)} Ω")

    def linie(x, eticheta):
        s = []
        if par["platbanda"]:
            s.append(f"{eticheta}platbandă L = {fmt_ro(x['Lp'])} m, b = {fmt_ro(par['b'], 3)} m, h = {fmt_ro(par['h'])} m: "
                     f"R_pl = ρ_pl/(2πL)·ln(2L²/(b·h)) = {fmt_ro(x['R_pl'], 3)} Ω")
        s.append(f"{eticheta}n = {x['n']} electrozi în linie, a = {fmt_ro(par['a'])} m, a/L = {fmt_ro(x['aL'], 2)} → "
                 f"η_e = {fmt_ro(x['eta_e'], 3)}" + (f", η_p = {fmt_ro(x['eta_p'], 3)}" if par["platbanda"] else ""))
        if par["platbanda"]:
            s.append(f"{eticheta}Rp = R_e·R_pl/(R_e·η_p + n·R_pl·η_e) = {fmt_ro(x['R_e'], 3)}·{fmt_ro(x['R_pl'], 3)}/"
                     f"({fmt_ro(x['R_e'], 3)}·{fmt_ro(x['eta_p'], 3)} + {x['n']}·{fmt_ro(x['R_pl'], 3)}·"
                     f"{fmt_ro(x['eta_e'], 3)}) = {fmt_ro(x['Rp'], 3)} Ω")
        else:
            s.append(f"{eticheta}Rp = R_e/(n·η_e) = {fmt_ro(x['R_e'], 3)}/({x['n']}·{fmt_ro(x['eta_e'], 3)}) = "
                     f"{fmt_ro(x['Rp'], 3)} Ω")
        return s

    if c0 is not None and c0["n"] != c["n"]:
        out += linie(c0, f"[n = {c0['n']}] ")
        out.append(f"Rp = {fmt_ro(c0['Rp'], 3)} Ω > {fmt_ro(lim, 2)} Ω → se mărește numărul de electrozi")
        out += linie(c, f"[n = {c['n']}] ")
    else:
        out += linie(c, "")
    out.append(f"Limita Rp ≤ {fmt_ro(lim, 2)} Ω ({lim_motiv}) → "
               f"{'îndeplinită' if c['Rp'] <= lim + 1e-9 else 'NEÎNDEPLINITĂ'}")
    return out


def rezultat(par, c0, c, n_nec, lim, lim_motiv, ra_din_priza=False):
    """Dicționarul rez["priza"] (contractul de date §C.7)."""
    ok = c["Rp"] <= lim + 1e-9
    r = {"Rp_ohm": c["Rp"], "R_limita_ohm": lim, "limita_motiv": lim_motiv, "ok": ok,
         "n_electrozi": c["n"], "n_initial": c0["n"], "Rp_initial_ohm": c0["Rp"], "n_necesar": n_nec,
         "L_electrod_m": par["L"], "d_electrod_m": par["d"], "distanta_m": par["a"], "a_pe_L": c["aL"],
         "adancime_m": par["h"], "t_m": c["t"],
         "L_platbanda_m": c["Lp"] if par["platbanda"] else 0.0,
         "latime_platbanda_m": par["b"], "grosime_platbanda_m": par["g"],
         "rho_ohm_m": par["rho"], "psi": par["psi"], "rho_calcul_ohm_m": c["rho_c"],
         "psi_platbanda": par["psi_pl"], "rho_calcul_platbanda_ohm_m": c["rho_pl"],
         "L_racord_m": par["L_racord"] if par["platbanda"] and not par["Lp_impus"] else None,
         "eta_e": c["eta_e"], "eta_p": c["eta_p"], "R_electrod_ohm": c["R_e"], "R_platbanda_ohm": c["R_pl"],
         "dispunere": "electrozi verticali în linie" + (", legați cu platbandă" if par["platbanda"] else ""),
         "materiale": materiale(par, c), "RA_din_priza": bool(ra_din_priza),
         "pasi": pasi(par, c, lim, lim_motiv, c0)}
    pl = (f", legați cu {_txt_platbanda(par)}, L = {fmt_ro(c['Lp'], 1)}{NB}m" if par["platbanda"] else "")
    r["nota"] = (f"Priză de pământ: {c['n']} electrozi {_txt_electrod(par)} în linie, la a = {fmt_ro(par['a'])}{NB}m"
                 f"{pl}, la {fmt_ro(par['h'])}{NB}m adâncime; Rp calculat = {fmt_ro(c['Rp'], 2)}{NB}Ω "
                 f"{'≤' if ok else '>'} {fmt_ro(lim, 2)}{NB}Ω (ρ = {fmt_ro(par['rho'])}{NB}Ω·m, ψ_e = {fmt_ro(par['psi'])}"
                 f"{', ψ_pl = ' + fmt_ro(par['psi_pl']) if par['platbanda'] else ''}). "
                 f"Valoarea se confirmă prin măsurare înainte de punerea în funcțiune.")
    return r

engine/calc/protectii.py:
"""protectii.py — aparatele de protecție: tipul (SPEC §B.3), seriile (§B.4), calibrul și reglajele (§B.5),
I2 (§B.6), curentul de deconectare Ia (§B.15), capacitatea de rupere (§B.5 pct. 6 / §B.16)
și selectivitatea amonte–aval (§B.18).

O protecție se reprezintă ca dict: {tip, In_A, curba?, Ir_A?, Ir_multiplu?, decl ('TM'|'EL')?, Im_A?, Isd_A?,
Isd_multiplu?, Ii_A?, tsd_s?, Icu_kA}. Curentul de reglaj Ip = Ir pentru MCCB/ACB, altfel In.
"""
from . import norme
from .comun import ge, gt, lt, eq, prima_din_serie

SERII = {"MCB": norme.MCB_IN_A, "MCCB": norme.MCCB_IN_A, "ACB": norme.ACB_IN_A, "gG": norme.GG_IN_A,
         "gPV": norme.GPV_IN_A}
SERII_ICU = {"MCB": norme.MCB_ICN_KA, "MCCB": norme.MCCB_ICU_KA, "ACB": norme.ACB_ICU_KA}
IN_MAX_ABSOLUT = 4000


def normalizeaza_tip(tip):
    """Normalizează denumirea tipului de aparat („mccb” → „MCCB”, „GG” → „gG”) la seriile SPEC §B.4."""
    if tip is None:
        return None
    t = str(tip).strip()
    return {"MCB": "MCB", "MCCB": "MCCB", "ACB": "ACB", "GG": "gG", "GPV": "gPV"}.get(t.upper(), t)


def tip_implicit(rol, receptor, ip_min):
    """SPEC §B.3: tipul protecției când utilizatorul nu îl impune, după rolul ramurii și Ip,min."""
    if rol == "plecare":
        if ip_min <= 630 + 1e-9:
            return "gG"
        return "MCCB" if ip_min <= 1600 + 1e-9 else "ACB"
    if rol in ("qg", "q_trafo"):
        return "MCCB" if ip_min <= 1600 + 1e-9 else "ACB"
    # final, intrare, invertor, pcs, c2
    if ip_min <= 63 + 1e-9:
        return "MCB"
    return "MCCB" if ip_min <= 1600 + 1e-9 else "ACB"


def curba_implicita(receptor):
    """SPEC §B.3: MCB curba B pentru iluminat și prize, C pentru restul."""
    return "B" if receptor in ("iluminat", "prize") else "C"


def declansator(tip, In):
    """SPEC §B.5 pct. 2–3: MCCB In ≤ 250 A termomagnetic (TM), In ≥ 320 A electronic (EL); ACB electronic."""
    if tip == "MCCB":
        return "TM" if In <= norme.MCCB_TM_IN_MAX else "EL"
    if tip == "ACB":
        return "EL"
    return None


def alege_reglaj_ir_max(tip, In, ir_max):
    """SPEC §C.6 pct. 1 (v1.2): Ir = cel mai mare multiplu din treaptă cu k·In ≤ ir_max (protecție strictă la
    suprasarcină a generatorului). Returnează (k, Ir) sau (None, None) dacă nici treapta minimă nu încape."""
    trepte = norme.IR_TREPTE["MCCB_TM"] if declansator(tip, In) == "TM" else norme.IR_TREPTE["MCCB_EL"]
    ok = [k for k in trepte if ge(ir_max, k * In)]
    if not ok:
        return None, None
    k = max(ok)
    return k, k * In


def ip(prot):
    """Curentul de reglaj al protecției: Ir pentru MCCB/ACB, In pentru MCB/gG (SPEC §B.5)."""
    return prot["Ir_A"] if prot.get("Ir_A") is not None else prot["In_A"]


def alege_reglaj_ir(tip, In, ip_min):
    """SPEC §B.5 pct. 2: Ir = (cel mai mic multiplu din treaptă ≥ Ip,min/In)·In. Dacă niciun multiplu nu ajunge
    (calibru impus prea mic), Ir = In (verificarea se face prin V04/V40/V60/V65)."""
    trepte = norme.IR_TREPTE["MCCB_TM"] if declansator(tip, In) == "TM" else norme.IR_TREPTE["MCCB_EL"]
    for k in trepte:
        if ge(k * In, ip_min):
            return k, k * In
    return 1.0, float(In)


def construieste(tip, In, ip_min, curba=None, are_aval=False):
    """SPEC §B.5: completează protecția (In ales, Ir, Im/Ii, tsd) pentru tipul dat."""
    p = {"tip": tip, "In_A": In}
    if tip == "MCB":
        p["curba"] = curba or "C"
    elif tip in ("MCCB", "ACB"):
        k, ir = alege_reglaj_ir(tip, In, ip_min)
        p["Ir_multiplu"] = k
        p["Ir_A"] = ir
        p["decl"] = declansator(tip, In)
        if p["decl"] == "TM":
            p["Im_A"] = norme.IM_TM_MULTIPLU * In
        else:
            p["Ii_A"] = 12.0 * In
            p["tsd_s"] = norme.TSD_S if are_aval else 0.0
    return p


def alege_calibru(tip, ip_min, serie=None):
    """SPEC §B.5 pct. 1–3: cel mai mic In din serie ≥ Ip,min (None dacă depășește seria)."""
    return prima_din_serie(serie or SERII[tip], ip_min)


def in_max(tip, serie=None):
    """Calibrul maxim al seriei (SPEC §B.3: MCB 125, gG 1250, MCCB 1600, ACB 4000)."""
    return max(serie or SERII[tip])


def alege_icu(tip, ik3_kA):
    """SPEC §B.5 pct. 6: cea mai mică capacitate de rupere din serie ≥ Ik3max la bara aparatului.
    gG NH: 120 kA (v1.2, SR EN 60269-2). Returnează (Icu, suficient)."""
    if tip == "gG":
        return norme.GG_ICU_KA, ge(norme.GG_ICU_KA, ik3_kA)
    serie = SERII_ICU.get(tip)
    if not serie:
        return None, True
    v = prima_din_serie(serie, ik3_kA)
    if v is None:
        return max(serie), False
    return v, True


def i2(prot):
    """SPEC §B.6: curentul convențional de funcționare I2 (MCB 1,45·In; MCCB/ACB 1,30·Ir; gG 1,6/1,9/2,1·In; gPV 1,45·In)."""
    t = prot["tip"]
    if t in ("MCCB", "ACB"):
        return norme.I2_MULTIPLU[t] * prot["Ir_A"]
    if t == "gG":
        return norme.i2_gg(prot["In_A"]) * prot["In_A"]
    return norme.I2_MULTIPLU.get(t, 1.45) * prot["In_A"]


def alege_isd(prot, ik1_A):
    """SPEC §B.5 pct. 4: cel mai mare multiplu m cu 1,2·m·Ir ≤ Ik1min; dacă niciunul nu satisface, m = 1,5."""
    ok = [m for m in norme.ISD_MULTIPLI if ge(ik1_A, norme.TOLERANTA_MAGNETIC * m * prot["Ir_A"])]
    m = max(ok) if ok else norme.ISD_MULTIPLI[0]
    prot["Isd_multiplu"] = m
    prot["Isd_A"] = m * prot["Ir_A"]
    return m


def timp_deconectare_cerut(receptor, ip_A, schema="TN"):
    """SPEC §B.15: 0,4 s pentru circuitele finale cu Ip ≤ 63 A (receptor ≠ tablou), altfel 5 s; TT: 0,2 s / 1 s."""
    final = receptor != "tablou" and ip_A <= norme.IN_MAX_CIRCUIT_FINAL_0_4S_A + 1e-9
    return norme.T_DECONECTARE_S[("TT" if schema == "TT" else "TN", "final" if final else "distributie")]


def ia(prot, t_s):
    """SPEC §B.15, tabelul Ia: MCB 5/10/20·In; MCCB TM 1,2·Im; EL/ACB 1,2·Isd; gG din tabel la 0,4 s / 5 s.
    Returnează None dacă valoarea nu există pentru calibru și timp (V30 AVERTISMENT)."""
    t = prot["tip"]
    if t == "MCB":
        return norme.MCB_IA_MULTIPLU[prot.get("curba", "C")] * prot["In_A"]
    if t in ("MCCB", "ACB"):
        if prot.get("decl") == "TM":
            return norme.TOLERANTA_MAGNETIC * prot["Im_A"]
        return norme.TOLERANTA_MAGNETIC * prot["Isd_A"]
    if t == "gG":
        tab = norme.GG_IA_0_4S_A if t_s <= 0.4 + 1e-9 else (norme.GG_IA_5S_A if t_s >= 5 - 1e-9 else None)
        if tab is None:
            return None
        return tab.get(prot["In_A"])
    return None


def timp_termic(prot, ik1_A, stare):
    """SPEC §B.17, timpul t la Ik1min pentru verificarea adiabatică: aparate instantanee 0,1 s; gG 0,1 / 0,4 / 5 s
    după porți; deconectare prin DDR 0,3 s; deconectare neîndeplinită 5 s."""
    if stare in ("ddr_propriu", "ddr_amonte"):
        return 0.3
    if stare in ("blocant", "z_implicit", "regim_ge"):
        return 5.0
    if prot["tip"] == "gG":
        In = prot["In_A"]
        porti = norme.GG_PORTI_A.get(In)
        if porti and ge(ik1_A, porti[3]):
            return 0.1
        ia04 = norme.GG_IA_0_4S_A.get(In)
        if ia04 is not None and ge(ik1_A, ia04):
            return 0.4
        return 5.0
    return 0.1


def t_ik3(prot, are_aval):
    """SPEC §B.11 / §B.17: durata pentru verificarea termică la Ik3max a MCCB/ACB: 0,02 s (+0,1 s electronic cu tsd)."""
    t = 0.02
    if prot.get("decl") == "EL" and are_aval:
        t += norme.TSD_S
    return t


def prag_selectivitate(prot):
    """SPEC §B.18 pct. 4b: limita de selectivitate Is [A] = pragul inferior instantaneu al aparatului amonte."""
    t = prot["tip"]
    In = prot["In_A"]
    if t == "MCB":
        return {"B": 3.0, "C": 5.0, "D": 10.0}[prot.get("curba", "C")] * In
    if t in ("MCCB", "ACB"):
        if prot.get("decl") == "TM":
            return 0.8 * norme.IM_TM_MULTIPLU * In
        return 0.8 * 12.0 * In
    if t == "gG":
        porti = norme.GG_PORTI_A.get(In)
        if porti:
            return float(porti[2])
        return float(norme.GG_IA_0_4S_A.get(In, 5 * In))
    return 0.0


def selectivitate(amonte, aval, ik_kA, obiect, jurnal, bmpt=False):
    """SPEC §B.18: regula simplificată de selectivitate pentru perechea (amonte, aval), cu Ik = Ik3max la bara aparatului
    aval. Emite V40 / V41 / V42."""
    from .verificari import emite, BLOCANT, AVERTISMENT, INFO
    a, b = ip(amonte), ip(aval)
    if bmpt:
        emite(jurnal, "V41", INFO, obiect, "bmpt")
        return
    if lt(a, b):
        emite(jurnal, "V40", BLOCANT, obiect, a=a, b=b)
        return
    if eq(a, b):
        emite(jurnal, "V41", AVERTISMENT, obiect, "egal", a=a)
        return
    r = a / b
    if amonte["tip"] == "gG" and aval["tip"] == "gG":
        rr = amonte["In_A"] / aval["In_A"]
        if ge(rr, norme.RAPORT_SELECTIVITATE_GG):
            emite(jurnal, "V42", INFO, obiect, "INFO_gg", r=rr)
        else:
            emite(jurnal, "V41", AVERTISMENT, obiect, "gg", r=rr)
        return
    if lt(r, norme.RAPORT_SELECTIVITATE_SUPRASARCINA):
        emite(jurnal, "V41", AVERTISMENT, obiect, "raport", r=r)
    is_kA = prag_selectivitate(amonte) / 1000.0
    if ge(is_kA, ik_kA):
        emite(jurnal, "V42", INFO, obiect, "INFO", Ik=ik_kA, Is=is_kA)
    else:
        emite(jurnal, "V42", AVERTISMENT, obiect, "AV", Ik=ik_kA, Is=is_kA)


def in_serie(prot):
    """Verifică apartenența protecției la seriile din norme (SPEC §B.4; folosit și de testul de proprietate)."""
    t = prot["tip"]
    if prot["In_A"] not in SERII[t]:
        return False
    if t in ("MCCB", "ACB"):
        trepte = norme.IR_TREPTE["MCCB_TM"] if prot.get("decl") == "TM" else norme.IR_TREPTE["MCCB_EL"]
        if not any(eq(k * prot["In_A"], prot["Ir_A"]) for k in trepte):
            return False
    if t in SERII_ICU and prot.get("Icu_kA") is not None and prot.get("Icu_fortat") is None:
        if prot["Icu_kA"] not in SERII_ICU[t]:
            return False
    return True

engine/calc/ramura.py:
"""ramura.py — lanțul de dimensionare al unei ramuri (SPEC §B.0–§B.22, ordinea pașilor din §B.21).

O ramură = aparat de protecție + cablul protejat + sarcina de la capăt. Se calculează cu contextul de amonte
(valorile la bara de origine, SPEC §B.1).

API:
    calculeaza_ramura(ramura, context, jurnal, obiect, amonte=None, obiect_sel=None, bmpt_sel=False) -> dict
        {"rezultat": {...forma 'asteptat' din cazuri_golden.json...}, "prot": {...}, "ctx_aval": {...},
         "blocat": bool, "Ib": float, "Ip": float|None}
"""
import math

from . import norme
from . import cabluri as cb
from . import protectii as pr
from . import scurtcircuit as sc
from . import ddr as ddr_mod
from .comun import ge, gt, lt, u_calcul
from .texte import fmt_ro, text_cablu
from .verificari import emite, BLOCANT, AVERTISMENT, INFO

FALLBACK = [(None, "XLPE"), ("Cu", "PVC"), ("Cu", "XLPE")]
PORNIRE_TXT = {"directa": "directă", "stea_triunghi": "stea-triunghi", "soft": "soft-starter", "vfd": "VFD"}


def limita_du(receptor, origine):
    """SPEC §B.12, limitele ΔU: iluminat 3/6 %, forță/prize/motor 5/8 % (V20 BLOCANT); bara unui tablou secundar
    = limita de forță − 2 % (V21 AVERTISMENT, DECIZIE); invertor/PCS → PCC 1 % (V21 AVERTISMENT)."""
    pt = origine == "pt_propriu"
    if receptor in ("invertor", "pcs"):
        return norme.DU_CEF_CA_RECOMANDAT_PCT, "V21"
    if receptor == "iluminat":
        return norme.DU_MAX_PCT[("pt_propriu" if pt else "retea_publica", "iluminat")], "V20"
    forta = norme.DU_MAX_PCT[("pt_propriu" if pt else "retea_publica", "forta")]
    if receptor == "tablou":
        return forta - norme.DU_REZERVA_CIRCUITE_FINALE_PCT, "V21"
    return forta, "V20"


def limita_du_max(receptor, origine):
    """SPEC §B.12 (v1.2): limita peste care ΔU devine BLOCANT pentru ramurile cu limită de AVERTISMENT: bara unui tablou
    → limita I7 de forță (5 % / 8 %); invertor/PCS → 3 % (mărire automată până la această valoare). Altfel None."""
    if receptor in ("invertor", "pcs"):
        return norme.DU_CEF_CA_MAX_PCT
    if receptor == "tablou":
        return norme.DU_MAX_PCT[("pt_propriu" if origine == "pt_propriu" else "retea_publica", "forta")]
    return None


def idn_aval_tt(idn):
    """IΔn al DDR-urilor din aval, selectiv față de un DDR S de IΔn dat: ≤ IΔn/3 (dacă nu există, aceeași treaptă)."""
    return next((x for x in (300, 100, 30) if 3 * x <= idn), idn)


def prag_pornire(tip, In, curba):
    """SPEC §B.3.1 (v1.2): curentul sub care protecția NU declanșează în timpul pornirii motorului: gG → poarta
    Imin(10 s) din SR EN 60269-1; MCB → pragul instantaneu inferior (B 3·In, C 5·In, D 10·In); MCCB TM → 0,8·Im;
    electronic / ACB → 0,8·Ii. None dacă nu e tabelat."""
    if tip == "gG":
        porti = norme.GG_PORTI_A.get(In)
        return float(porti[0]) if porti else None
    if tip == "MCB":
        return {"B": 3.0, "C": 5.0, "D": 10.0}.get(curba or "C", 5.0) * In
    if tip in ("MCCB", "ACB"):
        if pr.declansator(tip, In) == "TM":
            return 0.8 * norme.IM_TM_MULTIPLU * In
        return 0.8 * 12.0 * In
    return None


def _blocat(ib=None):
    """Rezultatul unei ramuri oprite de un BLOCANT (SPEC §B.21: „⇒ STOP ramura”)."""
    rez = {"blocat": True}
    if ib is not None:
        rez["Ib_A"] = ib
    return {"rezultat": rez, "prot": None, "ctx_aval": None, "blocat": True, "Ib": ib, "Ip": None}


def valideaza(r, cablu, j, obiect):
    """SPEC §B.2, validările prealabile (prima care pică oprește ramura): cosφ ∉ (0;1] → V08; L ≤ 0 → V09 (L > 1000 m
    → V09 AVERTISMENT); P ≤ 0 → V07; ks ∉ (0;1] → V10. Returnează False dacă ramura se oprește."""
    cosfi = r.get("cosfi")
    if cosfi is not None:
        if not (0 < cosfi <= 1):
            emite(j, "V08", BLOCANT, obiect, "B", x=cosfi)
            return False
        if cosfi < 0.7:
            emite(j, "V08", AVERTISMENT, obiect, "AV", x=cosfi)
    L = cablu.get("L")
    if L is not None:
        if L <= 0:
            emite(j, "V09", BLOCANT, obiect, "B", L=L)
            return False
        if L > 1000:
            emite(j, "V09", AVERTISMENT, obiect, "AV", L=L)
    sarcini = [r.get(k) for k in ("P_kW", "In_A", "S_kVA", "Pn_kW", "Ib_A")]
    if all(v is None for v in sarcini):
        emite(j, "V07", BLOCANT, obiect, "lipsa")
        return False
    for k in ("P_kW", "S_kVA", "Pn_kW", "In_A", "Ib_A"):
        if r.get(k) is not None and r[k] <= 0:
            emite(j, "V07", BLOCANT, obiect, P=r[k])
            return False
    ks = r.get("ks")
    if ks is not None and not (0 < ks <= 1):
        emite(j, "V10", BLOCANT, obiect, parametru=f"ks = {fmt_ro(ks)}", tabel="IEC 61439-2 tab. 101")
        return False
    return True


def calculeaza_ramura(r, ctx, j, obiect, amonte=None, obiect_sel=None, bmpt_sel=False):
    """SPEC §B.21: pașii 1–16 pentru o ramură, cu contextul de amonte `ctx` (SPEC §B.1)."""
    retea = r.get("retea", "tri")
    receptor = r.get("receptor", "forta")
    rol = r.get("rol", "final")
    cin = dict(r.get("cablu") or {})
    are_aval = bool(r.get("are_aval", False))
    metoda_explicita = cin.get("metoda") is not None and not cin.get("metoda_implicit")
    invertor = receptor in ("invertor", "pcs")

    # ---- 1. validări B.2 -------------------------------------------------------------------------------------
    if not r.get("_validat") and not valideaza(r, cin, j, obiect):
        return _blocat()

    # valorile implicite B.0
    metoda = cin.get("metoda") or ("C" if rol == "final" else "D1")
    material = cin.get("material")
    mat_implicit = cin.get("material_implicit", material is None)
    if material is None:
        material = "Al" if metoda in norme.METODE_IN_PAMANT else "Cu"
    izolatie = cin.get("izolatie") or "PVC"
    if cin.get("izolatie") is None:
        j.presupune("izolație PVC (Iz mai mic, conservator)")
    theta = cin.get("theta")
    if theta is None:
        theta = cb.theta_implicit(metoda)
        j.presupune("temperatura de referință: aer 30 °C, sol 20 °C")
    rho = cin.get("rho_sol")
    if rho is None:
        rho = 2.5
        if metoda in norme.METODE_IN_PAMANT:
            j.presupune("rezistivitatea termică a solului 2,5 K·m/W (sol uscat, conservator)")
    n_alte = int(cin.get("n_alte") or 0)
    L = cin.get("L")
    if L is None:
        L = 50.0
        j.presupune("lungime 50 m", obiect)
    L = float(L)
    c = {"material": material, "izolatie": izolatie, "metoda": metoda, "retea": retea, "theta": theta,
         "rho_sol": rho, "n_alte": n_alte, "distanta": cin.get("distanta", "atingere"),
         "aranjament": cin.get("aranjament")}
    j.ipoteza("pozare", (metoda, theta, rho if metoda in norme.METODE_IN_PAMANT else None, n_alte + 1),
              cin.get("metoda") is None)

    # ---- 2. Ib, Ip,min (B.2) ------------------------------------------------------------------------------------
    U = u_calcul(retea)
    cos_dat = r.get("cosfi")
    cosfi = cos_dat if cos_dat is not None else norme.COSFI_IMPLICIT.get(receptor, 0.9)
    if cos_dat is None and not invertor:
        j.presupune(f"cosφ {fmt_ro(cosfi)} ({'motor' if receptor == 'motor' else 'forță, iluminat, prize, tablou'})")
    ks = r.get("ks", 1.0) or 1.0
    in_dat = r.get("In_A")
    if invertor:
        pn = float(r["Pn_kW"])
        iac = r.get("Iac_max_A") or norme.FACTOR_SMAX_INVERTOR * pn * 1000.0 / U
        ib = float(iac)
        ip_min = max(ib, norme.FACTOR_IP_INVERTOR * pn * 1000.0 / U)
        cosfi = 1.0
        u_txt = "(√3·400)" if retea == "tri" else "230"
        j.pas(f"{obiect}: Ib = Iac,max = 1,1·{fmt_ro(pn)}·1000/{u_txt} = {fmt_ro(ib)} A; "
              f"Ip,min = max(Ib; 1,25·Pn/U = {fmt_ro(norme.FACTOR_IP_INVERTOR * pn * 1000.0 / U)}) = {fmt_ro(ip_min)} A")
    elif r.get("Ib_A") is not None:
        ib = float(r["Ib_A"])
        ip_min = ib
        j.pas(f"{obiect}: Ib dat = {fmt_ro(ib)} A (cosφ {fmt_ro(cosfi)} pentru ΔU)")
    elif in_dat is not None:
        ib = float(in_dat)
        ip_min = ib
        j.pas(f"{obiect}: plecare dată prin calibru {fmt_ro(in_dat)} A → Ib presupus = In = {fmt_ro(ib)} A")
        j.presupune("Ib presupus = In (plecare dată prin calibru)", obiect)
    elif r.get("S_kVA") is not None:
        ib = float(r["S_kVA"]) * 1000.0 / U
        ip_min = ib
        j.pas(f"{obiect}: S = {fmt_ro(r['S_kVA'])} kVA → Ib = {fmt_ro(ib)} A")
    else:
        pc = ks * float(r["P_kW"])
        ib = pc * 1000.0 / (U * cosfi)
        ip_min = ib
        j.pas(f"{obiect}: Pc = {fmt_ro(ks)}·{fmt_ro(r['P_kW'])} = {fmt_ro(pc)} kW → Ib = {fmt_ro(ib)} A "
              f"(cosφ {fmt_ro(cosfi)})")
    inm = r.get("In_minim")
    if inm is not None and gt(inm, ip_min):
        # v1.4 (§C.8): calibrul minim uzual al circuitului (ex. prize C16), chiar dacă Ib e mai mic
        ip_min = float(inm)
        j.pas(f"{obiect}: Ip,min = calibrul minim uzual {fmt_ro(inm)} A")
    extra = r.get("Ip_min_extra")
    if extra is not None and gt(extra, ip_min):
        ip_min = float(extra)
        j.pas(f"{obiect}: Ip,min ridicat peste aval max {fmt_ro(extra - 0.01)} A")

    # ---- 3–4. tip protecție, In, Ir, Icu (B.3–B.5) ----------------------------------------------------------------
    tip_f = pr.normalizeaza_tip(r.get("prot_tip"))
    in_f = r.get("In_fortat", in_dat)
    ref = in_f if in_f is not None else ip_min
    tip = tip_f or pr.tip_implicit(rol, receptor, ref)
    serie = r.get("serie_In") or pr.SERII[tip]
    if in_f is not None:
        if in_f not in serie:
            jos, sus = _vecini(serie, in_f)
            emite(j, "V05", BLOCANT, obiect, In=in_f, tip=tip, vecini=f"{jos} A / {sus} A")
            return _blocat(ib)
        In = in_f
    else:
        In = None
        if not gt(ip_min, pr.IN_MAX_ABSOLUT):
            In = pr.alege_calibru(tip, ip_min, serie)
        if In is None:
            emite(j, "V06", BLOCANT, obiect, Ib=ib, tip=tip)
            return _blocat(ib)
    curba = r.get("curba") or pr.curba_implicita(receptor)
    # SPEC §B.3.1 (v1.2): motor cu pornire directă — protecția trebuie să suporte Ip = k·Ib timp de tp
    pornire = r.get("pornire") or ("directa" if receptor == "motor" else None)
    k_porn = norme.MOTOR_IP_MULTIPLU.get(pornire, 0.0) if receptor == "motor" else 0.0
    ip_porn = k_porn * ib if k_porn > 1.0 else None
    motor_v23 = None
    if ip_porn is not None and tip == "gG" and tip_f is None and in_f is None:
        # pornire directă fără tip impus: întreruptor MCCB TM (motor) în locul siguranțelor gG — pragul magnetic
        # 0,8·10·In ≥ 6·Ib, iar cablul rămâne dimensionat la Ir (fără supradimensionarea cerută de gG la pornire)
        tip = "MCCB"
        serie = r.get("serie_In") or pr.SERII[tip]
        In = pr.alege_calibru(tip, ip_min, serie)
        if In is None:
            emite(j, "V06", BLOCANT, obiect, Ib=ib, tip=tip)
            return _blocat(ib)
        j.pas(f"{obiect}: motor cu pornire {PORNIRE_TXT.get(pornire, pornire)} → MCCB (întreruptor-motor) în loc de gG")
    if ip_porn is not None:
        prag = prag_pornire(tip, In, curba)
        if prag is None or lt(prag, ip_porn):
            if in_f is None:
                for x in sorted(serie):
                    if x < In:
                        continue
                    pg = prag_pornire(tip, x, curba)
                    if pg is not None and ge(pg, ip_porn):
                        j.pas(f"{obiect}: pornire {PORNIRE_TXT.get(pornire, pornire)}: Ip = {fmt_ro(k_porn)}·Ib = {fmt_ro(ip_porn)} A > prag "
                              f"{fmt_ro(prag) if prag is not None else '—'} A al {tip} {fmt_ro(In)} A → calibru {fmt_ro(x)} A "
                              f"(prag {fmt_ro(pg)} A)")
                        In = x
                        motor_v23 = ("INFO", pg)
                        break
                else:
                    motor_v23 = ("AV", prag)
            else:
                motor_v23 = ("AV", prag)
        else:
            motor_v23 = ("INFO", prag)
    prot = pr.construieste(tip, In, ip_min, curba, are_aval)
    ik3o = ctx["Ik3_kA"]
    icu_f = r.get("Icu_fortat")
    if icu_f is not None:
        prot["Icu_kA"] = icu_f
        prot["Icu_fortat"] = True
    else:
        icu, ok = pr.alege_icu(tip, ik3o)
        if tip == "MCB" and not ok and not tip_f:
            tip = "MCCB"
            In = in_f if (in_f is not None and in_f in pr.SERII["MCCB"]) else pr.alege_calibru("MCCB", max(ip_min, in_f or 0))
            prot = pr.construieste(tip, In, ip_min, None, are_aval)
            icu, ok = pr.alege_icu(tip, ik3o)
            j.pas(f"{obiect}: Ik3max {fmt_ro(ik3o)} kA > 25 kA → MCCB în loc de MCB")
        prot["Icu_kA"] = icu
    Ip = pr.ip(prot)
    if tip in ("MCCB", "ACB"):
        j.pas(f"{obiect}: protecție {tip} In = {fmt_ro(In)} A, Ir = {fmt_ro(prot['Ir_multiplu'])}·In = {fmt_ro(Ip)} A")
    elif tip == "MCB":
        j.pas(f"{obiect}: protecție MCB {prot['curba']} In = {fmt_ro(In)} A")
    else:
        j.pas(f"{obiect}: protecție {tip} In = {fmt_ro(In)} A")
    if gt(ib, Ip):
        emite(j, "V04", BLOCANT, obiect, Ib=ib, Ip=Ip)
        return _blocat(ib)
    ddr_out = None
    ddr_tt = None
    ddr_f = r.get("ddr") if isinstance(r.get("ddr"), dict) else None
    if ddr_f is not None:
        # v1.3 (SPEC §B.18.1): DDR impus pe ramură {IdN_mA, selectiv, dt_s, tip} — de utilizator (se verifică, nu se
        # modifică) sau de motor (`_motor`: bloc diferențial reglabil pe intrarea TT, §C.2 pct. 13)
        idn_f = int(ddr_f["IdN_mA"])
        dt_f = ddr_f.get("dt_s")
        mare = In > norme.RCCB_IN_A[-1] or dt_f is not None
        d_f = ddr_mod.descriere(idn_f, bool(ddr_f.get("selectiv", False)), "", dt_f)
        ddr_out = {"IdN_mA": idn_f, "tip": ddr_f.get("tip") or "A",
                   "In_A": In if mare else (pr.prima_din_serie(norme.RCCB_IN_A, max(In, 16 if retea == "mono" else 25)) or In),
                   "poli": "2P" if retea == "mono" else "4P", "aparat": "bloc_diferential" if mare else "RCCB",
                   "selectiv": d_f["selectiv"], "temporizare": d_f["temporizare"]}
        if dt_f is not None:
            ddr_out.update({"dt_s": float(dt_f), "reglabil": True, "asociat": obiect.split("·")[0].split("/")[0]})
        if not ddr_f.get("_motor"):
            ddr_out["impus"] = True
        ctx = dict(ctx, ddr_ramura=f"DDR {idn_f} mA" + (" (impus)" if not ddr_f.get("_motor") else ""))
        if not r.get("_doar_protectie"):
            if receptor == "prize" and In <= 32 and not invertor and idn_f > 30:
                emite(j, "V29", BLOCANT, obiect, "B", In=In)
            if ctx.get("schema") == "TT":
                ra_c = ctx.get("RA_tt", 4.0)
                if gt(ra_c * idn_f / 1000.0, 50.0):
                    emite(j, "V34", BLOCANT, obiect, RA=ra_c, IdN=idn_f, x=ra_c * idn_f / 1000.0)
                ddr_tt = idn_f
    elif receptor == "prize" and In <= 32 and not invertor:
        # SPEC §C.2 pct. 10 (v1.2: orice plecare sau circuit final de prize ≤ 32 A): DDR 30 mA tip A obligatoriu
        # (SR HD 60364-4-41 art. 411.3.3); DDR refuzat explicit → V29 BLOCANT
        if r.get("ddr") is False:
            if not r.get("_doar_protectie"):
                emite(j, "V29", BLOCANT, obiect, "B", In=In)
        else:
            # RCCB 4P se fabrică de la 25 A (16 A doar 2P)
            ddr_out = {"IdN_mA": 30, "tip": "A", "In_A": pr.prima_din_serie(norme.RCCB_IN_A, max(In, 1 if retea == "mono" else 25)) or In,
                       "poli": "2P" if retea == "mono" else "4P"}
            ctx = dict(ctx, ddr_ramura="DDR 30 mA tip A")
            j.pas(f"{obiect}: circuit de prize ≤ 32 A → DDR 30 mA tip A")
            if not r.get("_doar_protectie"):
                emite(j, "V29", INFO, obiect, "INFO", In=In)
    if ddr_out is None and ctx.get("schema") == "TT" and rol in ("plecare", "final", "intrare", "invertor"):
        # v1.2 R2 (N-C2, SR HD 60364-4-41 art. 411.5): în TT fiecare circuit are DDR propriu cu RA·IΔn ≤ 50 V
        idn = ctx.get("idn_tt_mA")
        sus = ctx.get("ddr_sus")
        if r.get("ddr") is False:
            if not r.get("_doar_protectie"):
                emite(j, "V34", BLOCANT, obiect, "lipsa")
        elif are_aval and sus and rol in ("plecare", "intrare"):
            # v1.3 R5 (SPEC §C.2 pct. 13, M5-4): intrarea tabloului și alimentările tablourilor secundare NU primesc DDR
            # propriu — sunt protejate de DDR-ul temporizat din amonte (RA·IΔn ≤ 50 V verificat acolo); un al doilea
            # DDR temporizat în serie nu ar fi selectiv. Circuitele din aval primesc DDR instantaneu.
            ctx = dict(ctx, ddr_ramura=f"DDR {sus['IdN_mA']} mA din amonte ({sus['denumire']})")
            j.pas(f"{obiect}: TT — fără DDR propriu, protejat de {sus['denumire']} {sus['IdN_mA']} mA"
                  f"{' (' + sus['temporizare'] + ')' if sus.get('temporizare') else ''}; circuitele din aval: DDR "
                  f"{idn} mA instantaneu")
        elif idn:
            mare = In > norme.RCCB_IN_A[-1]
            ddr_out = {"IdN_mA": idn, "tip": "A",
                       "In_A": In if mare else (pr.prima_din_serie(norme.RCCB_IN_A, max(In, 16 if retea == "mono" else 25)) or In),
                       "poli": "2P" if retea == "mono" else "4P", "aparat": "bloc_diferential" if mare else "RCCB",
                       "selectiv": False, "temporizare": "instantaneu"}
            if mare:
                ddr_out["asociat"] = obiect.split("·")[0]
            ctx = dict(ctx, ddr_ramura=f"DDR {idn} mA (TT)")
            ddr_tt = idn
            j.pas(f"{obiect}: schema TT → DDR {idn} mA instantaneu pe circuit (RA·IΔn ≤ 50 V)")
    if r.get("_doar_protectie"):
        # SPEC §C.2 pct. 4: protecțiile plecărilor se calculează întâi (doar Ip; nu depind de bara TG)
        return {"rezultat": None, "prot": prot, "ctx_aval": None, "blocat": False, "Ib": ib, "Ip": Ip}
    # v1.3 (SPEC §B.18.1): selectivitatea DDR-ului ramurii față de cel mai apropiat DDR din amonte
    ddr_sus_aval = ctx.get("ddr_sus")
    if ddr_out:
        d_aici = ddr_mod.descriere(ddr_out["IdN_mA"], ddr_out.get("selectiv"), f"DDR {obiect}", ddr_out.get("dt_s"))
        if ctx.get("ddr_sus"):
            ddr_mod.verifica(j, ctx["ddr_sus"], d_aici, obiect,
                             RA_ohm=ctx.get("RA_tt") if ctx.get("schema") == "TT" else None)
        ddr_sus_aval = d_aici
    if r.get("_cosfi_eticheta"):
        # v1.7 (§C.8, N13): locuința — cosφ din tabelul receptorului (presupus) sau declarat, cu eticheta receptorului
        j.ipoteza("cosfi", (cosfi, r["_cosfi_eticheta"]), bool(r.get("_cosfi_implicit")))
    else:
        j.ipoteza("cosfi", (cosfi, "invertor" if invertor else ("motor" if receptor == "motor" else "forță/iluminat/prize/tablou")
                             if cos_dat is None else "declarat"), cos_dat is None and not invertor)
    j.ipoteza("origine", ctx["origine"], False)

    # ---- 5. I2, Iz_min (B.6, B.10 pct. 5–6) -------------------------------------------------------------------------
    I2 = pr.i2(prot)
    iz_min = max(Ip, I2 / 1.45)
    h3 = r.get("h3_pct", r.get("h3"))
    if h3 is not None and retea == "tri":
        if 15 < h3 <= 33:
            iz_min = iz_min / 0.86
        elif h3 > 33:
            i_n = 3.0 * h3 / 100.0 * ib
            iz_min = max(iz_min, i_n / 0.86 if h3 <= 45 else i_n)
            # SR HD 60364-4-43 art. 431.2.3: curentul din neutru > curentul de fază → detecția supracurentului în N
            emite(j, "V24", AVERTISMENT, obiect, h3=h3)
    j.pas(f"{obiect}: I2 = {fmt_ro(I2)} A → Iz' ≥ max(Ip; I2/1,45) = {fmt_ro(iz_min)} A")

    lim, cod_lim = r.get("limita_dU") or limita_du(receptor, ctx["origine"])
    lim_max = limita_du_max(receptor, ctx["origine"]) if r.get("limita_dU") is None else None
    # v1.3 (P0-2): la invertoare ΔU se cumulează cu ΔU pe C0 (TGD-CF → punctul de racord), dacă există
    du0 = ctx.get("dU_cef_pct", 0.0) if invertor else ctx["dU_pct"]

    def du(cc, n, S):
        """ΔU pe ramură [%] cu Ib, nu cu Ip (SPEC §B.12)."""
        return cb.du_pct(retea, ib, L, cc["material"], cc["izolatie"], S, n, cosfi)

    def smin(mat):
        """Secțiunea minimă pentru material (SPEC §B.8)."""
        s0 = cb.s_min(mat, receptor, metoda)
        # v1.4: secțiune minimă cerută pe receptor (ex. plită mono / VE 6 mm² Cu la locuințe, §C.8)
        if cin.get("S_min") is not None and mat == "Cu":
            s0 = max(s0, float(cin["S_min"]))
        # v1.5 (§C.8): receptoare fixe ≤ 10 A ale locuinței (centrală, poartă) — 1,5 mm² Cu admis (I7-2011)
        if cin.get("S_min_fix") is not None and mat == "Cu" and metoda not in norme.METODE_IN_PAMANT:
            s0 = float(cin["S_min_fix"])
        return s0

    plafon = [False]

    def creste_du(cc, n, S):
        """SPEC §B.12, mărirea automată pentru ΔU (S, apoi n), dacă S nu e impusă și receptorul nu e invertor/PCS."""
        marit = False
        tinta = lim_max if invertor else lim      # invertor/PCS: mărire doar peste 3 % (v1.2), 1 % rămâne recomandare
        if r.get("tinta_dU") is not None and not invertor:
            # v1.6 (§C.8, N2): ținta de mărire mai strictă decât limita (bugetul coloanei locuinței); limita V20/V21
            # rămâne cea normată
            tinta = min(tinta, float(r["tinta_dU"]))
        sect = cb.sectiuni(cc)
        s_max = r.get("S_max_dU")
        while gt(du0 + du(cc, n, S), tinta):
            i = sect.index(S)
            if s_max is not None and (i + 1 >= len(sect) or gt(sect[i + 1], float(s_max))):
                # v1.7 (§C.8, m-c6): plafonul măririi pentru ΔU (circuitele finale ale locuinței) — fără paralel
                plafon[0] = True
                break
            if i + 1 < len(sect):
                S = sect[i + 1]
            elif n < cb.n_max(cc):
                S2 = cb.cea_mai_mica_s(cc, n + 1, iz_min, smin(cc["material"]))
                if S2 is None:
                    break
                n, S = n + 1, S2
            else:
                break
            marit = True
        return n, S, marit

    def solutie(cc):
        """SPEC §B.8: căutarea (n, S), apoi fallback (material, XLPE) → (Cu, PVC) → (Cu, XLPE); plus bucla ΔU."""
        sol = cb.cauta(cc, iz_min, smin(cc["material"]))
        schimb = None
        if sol is None:
            incercate = {(cc["material"], cc["izolatie"])}
            for m, iz in FALLBACK:
                m = m or cc["material"]
                if (m, iz) in incercate:
                    continue
                incercate.add((m, iz))
                c2 = dict(cc, material=m, izolatie=iz)
                sol = cb.cauta(c2, iz_min, smin(m))
                if sol is not None:
                    schimb = (cc["material"], cc["izolatie"], m, iz)
                    cc = c2
                    break
        if sol is None and retea == "tri" and not cb.monopolar(cc):
            # v1.2 R2/R3 (N-M5, N3-C1): curenți mari — sisteme de cabluri monopolare Cu XLPE în treflă, până la 6 pe
            # fază. Metoda cerută explicit în pământ (D1/D2) se păstrează (Iz și grupare din tabelele metodei, fiecare
            # treflă = un circuit); metoda în aer cerută (C/E) sau implicită → pat de cabluri în aer, metoda F.
            if metoda_explicita and cc["metoda"] in norme.METODE_IN_PAMANT:
                cF = dict(cc, material="Cu", izolatie="XLPE", monopolar=True)
            else:
                cF = dict(cc, material="Cu", izolatie="XLPE", metoda="F_trefla",
                          theta=cin.get("theta") if cin.get("theta") is not None else 30.0)
            sol = cb.cauta(cF, iz_min, 0.0)
            if sol is not None:
                schimb = (cc["material"], cc["izolatie"], "Cu", "XLPE", cF["metoda"])
                cc = cF
        if sol is None:
            return None
        n0, S0 = sol
        n, S, marit = creste_du(cc, n0, S0)
        return {"c": cc, "n": n, "S": S, "n0": n0, "S0": S0, "schimb": schimb, "marit_du": marit}

    # ---- 6–8. secțiune (B.7, B.8), Al→Cu, ΔU (B.12) ---------------------------------------------------------------
    S_f = cin.get("S_fortat")
    try:
        if S_f is not None:
            if float(S_f) not in cb.sectiuni(c):
                emite(j, "V13", BLOCANT, obiect, S=S_f, mat=material)
                return _blocat(ib)
            n = int(cin.get("n_fortat") or 1)
            S = float(S_f)
            st = {"c": c, "n": n, "S": S, "n0": n, "S0": S, "schimb": None, "marit_du": False}
        else:
            st = solutie(c)
            if st is None:
                emite(j, "V01", BLOCANT, obiect, Iz_min=iz_min)
                return _blocat(ib)
            if st["schimb"] and len(st["schimb"]) == 5:
                m0, i0 = st["schimb"][:2]
                met1 = st["schimb"][4]
                if met1.startswith("F"):
                    emite(j, "V45", AVERTISMENT, obiect, "F", mat=m0, iz=i0, n=st["n"], S=st["S"])
                    # N3-C1: trecerea în aer e o ipoteză de pozare — scrisă explicit în nota de ipoteze (G.2)
                    j.ipoteza("pozare_F", obiect, not metoda_explicita)
                    j.presupune("pozare pe pat de cabluri în aer, monopolare în treflă (metoda F, sisteme distanțate "
                                "≥ 2·De, tab. B.52.21) — multipolarele în pământ nu ajung; confirmați traseul", obiect)
                else:
                    emite(j, "V45", AVERTISMENT, obiect, "Fsol", mat=m0, iz=i0, n=st["n"], S=st["S"], met=met1)
                    j.presupune(f"sisteme de cabluri monopolare Cu XLPE în treflă, metoda {met1} (în pământ), fiecare treflă "
                                f"= un circuit la grupare", obiect)
                j.pas(f"{obiect}: cablurile multipolare nu ajung → {st['n']} sisteme monopolare Cu XLPE 1×{fmt_ro(st['S'])} "
                      f"mm² în treflă (metoda {met1})")
            elif st["schimb"]:
                m0, i0, m1, i1 = st["schimb"]
                emite(j, "V45", AVERTISMENT, obiect, mat=m0, iz=i0, mat2=m1, iz2=i1)
                j.pas(f"{obiect}: material/izolație schimbate → {m1} {i1}")
            if (mat_implicit and c["material"] == "Al" and not st["schimb"] and st["n"] == 1
                    and st["S"] == norme.S_MIN_AL):
                st_cu = solutie(dict(c, material="Cu"))
                if st_cu and st_cu["n"] == 1 and not st_cu["schimb"] and st_cu["S"] <= 10:
                    j.pas(f"{obiect}: Al ar rezulta < 16 mm² (Cu {fmt_ro(st_cu['S'])} mm² satisface Iz și ΔU) "
                          f"→ se trece pe Cu")
                    emite(j, "V48", INFO, obiect, S=st_cu["S"])
                    st = st_cu
        c = st["c"]
        n, S = st["n"], st["S"]
        iz0, k0, izp0 = cb.iz_corectat(c, st["n0"], st["S0"])
    except cb.InAfaraTabelelor as e:
        emite(j, "V10", BLOCANT, obiect, parametru=e.parametru, tabel=e.tabel)
        return _blocat(ib)
    metoda = c["metoda"]
    j.pas(f"{obiect}: {c['material']} {c['izolatie']} metoda {metoda}: k = {fmt_ro(k0, 4)}; "
          f"{st['n0']}×{fmt_ro(st['S0'])} mm² Iz = {fmt_ro(iz0)} A → Iz' = {fmt_ro(izp0)} A")
    if st["marit_du"]:
        j.pas(f"{obiect}: secțiune mărită pentru ΔU → {n}×{fmt_ro(S)} mm² (Iz' = {fmt_ro(cb.iz_corectat(c, n, S)[2])} A)")
    if S_f is not None:
        _, _, izp = cb.iz_corectat(c, n, S)
        if gt(Ip, izp):
            emite(j, "V02", BLOCANT, obiect, Ip=Ip, Iz=izp)
        if gt(I2, 1.45 * izp):
            emite(j, "V03", BLOCANT, obiect, I2=I2, lim=1.45 * izp)

    mat, izl = c["material"], c["izolatie"]
    N_f, PE_f, PE_loc_f = cin.get("N_fortat"), cin.get("PE_fortat"), cin.get("PE_loc")

    # ---- 9. N, PE (B.10, B.11) ----------------------------------------------------------------------------------------
    def compune(n, S, pe_cfg=None):
        """Compunerea N și PE pentru (n, S), cu valorile impuse (SPEC §B.10, §B.11, pasul 9 din §B.21)."""
        N, motiv = cb.compune_neutru(mat, S, retea, receptor, h3, N_f)
        if PE_loc_f == "PEN":
            # v1.2 R2 (N-M2): TN-C — conductorul PEN este neutrul cablului (4 conductoare, fără PE separat)
            return {"n": n, "S": S, "N": N, "motiv_N": motiv, "s_pe": N, "loc": "PEN", "s_tab": N}
        if PE_f is not None:
            loc = PE_loc_f or ("cablu" if cb.pe_in_cablu(mat, S, retea) else "separat")
            s_tab = cb.s_pe_tabel(mat, izl, n, S, loc == "separat")
            s_pe = float(PE_f)
        elif pe_cfg is not None:
            s_pe, loc = pe_cfg
            s_tab = cb.s_pe_tabel(mat, izl, n, S, loc == "separat")
        else:
            s_pe, loc, s_tab = cb.compune_pe(mat, izl, n, S, retea)
        return {"n": n, "S": S, "N": N, "motiv_N": motiv, "s_pe": s_pe, "loc": loc, "s_tab": s_tab}

    # ---- 10–12. Ik3, Ik1, Isd, Ia, deconectare (B.13–B.15) ------------------------------------------------------------
    schema = ctx.get("schema", "TN")
    t_cer = pr.timp_deconectare_cerut(receptor, Ip, schema)
    f_faza = norme.FACTOR_R_IK1MIN[izl]

    def evalueaza(cfg):
        """Iz', ΔU, Ik3/Ik1 la capăt, Isd, Ia și starea deconectării pentru o configurație (SPEC §B.7, §B.12–§B.15)."""
        n, S = cfg["n"], cfg["S"]
        iz_t, k, izp = cb.iz_corectat(c, n, S)
        dur = du(c, n, S)
        r20 = norme.R20_OHM_KM[mat][float(S)]
        zq = sc.z_capat(ctx["Zq"], r20, L, n)
        fpe = f_faza if cfg["loc"] in ("cablu", "PEN") else norme.FACTOR_R_IK1MIN["PVC"]
        zb = sc.zb_capat(ctx["Zb"], r20, f_faza, cb.r20_pe(mat, cfg["loc"], cfg["s_pe"]), fpe, L, n)
        ik1 = sc.ik1_din_zb(zb)
        if prot.get("decl") == "EL":
            pr.alege_isd(prot, ik1)
        ia_v = pr.ia(prot, t_cer)
        if ia_v is None and ctx.get("ddr_ramura") and schema == "TT":
            stare = "ddr_propriu"     # TT: deconectarea se face prin DDR (Ia doar informativ, §B.15)
        elif ia_v is None:
            stare = "ia_lipsa"
        elif ge(ik1, ia_v):
            stare = "ok"
        elif ctx.get("ddr_ramura"):
            stare = "ddr_propriu"
        elif ctx.get("ddr_amonte"):
            stare = "ddr_amonte"
        elif ctx.get("regim_ge"):
            stare = "regim_ge"
        elif ctx.get("z_implicit"):
            stare = "z_implicit"
        else:
            stare = "blocant"
        e = dict(cfg)
        e.update({"Iz_tab": iz_t, "k": k, "Izp": izp, "dU_r": dur, "dU_c": du0 + dur, "Zq": zq, "Zb": zb,
                  "Ik3c": sc.ik3_din_z(zq), "Ik1": ik1, "Ia": ia_v, "stare": stare})
        return e

    try:
        ev = evalueaza(compune(n, S))
        marit_deconectare = False
        if (ev["stare"] not in ("ok", "ia_lipsa") and not ctx.get("z_implicit") and S_f is None
                and not ctx.get("ddr_ramura") and not ctx.get("regim_ge")):
            sect = cb.sectiuni(c)
            for S2 in sect[sect.index(S) + 1:]:
                e2 = evalueaza(compune(n, S2))
                if e2["stare"] == "ok":
                    ev, marit_deconectare = e2, True
                    j.pas(f"{obiect}: secțiune mărită pentru deconectare → {n}×{fmt_ro(S2)} mm²")
                    break
            if not marit_deconectare:
                ev = evalueaza(compune(n, S))

        # ---- 14. stabilitatea termică a fazei (B.17) -------------------------------------------------------------------
        t3 = pr.t_ik3(prot, are_aval)
        v35 = None
        if tip in ("MCCB", "ACB"):
            need_f = ik3o * 1000.0 * math.sqrt(t3) / norme.K_FAZA[(mat, izl)]
            j.pas(f"{obiect}: termic fază la Ik3max (t = {fmt_ro(t3)} s): n·S ≥ {fmt_ro(need_f, 1)} mm²")
            if lt(ev["n"] * ev["S"], need_f):
                if S_f is not None:
                    v35 = ("B", need_f)
                elif ctx.get("ik3_implicit"):
                    v35 = ("AV", need_f)
                else:
                    S3 = next((s for s in cb.sectiuni(c) if ge(ev["n"] * s, need_f)), None)
                    if S3 is None:
                        v35 = ("B", need_f)
                    else:
                        ev = evalueaza(compune(ev["n"], S3))
                        v35 = ("INFO_marit", need_f)
            else:
                v35 = ("INFO", need_f)
        else:
            v35 = ("INFO", None)

        # ---- 14. stabilitatea termică a PE (B.11) ---------------------------------------------------------------------
        def necesar_pe(e):
            """Secțiunea PE necesară la Ik1min (t după B.17) și la Ik3max pentru MCCB/ACB (SPEC §B.11, §B.17)."""
            kp = cb.k_pe(mat, izl, e["loc"])
            t1 = pr.timp_termic(prot, e["Ik1"], e["stare"])
            n1 = e["Ik1"] * math.sqrt(t1) / kp
            if tip == "gG":
                # v1.2 R2 (N-M4): siguranța gG în zona limitatoare (Ik1 ≥ Imax(0,1 s)) — energia lăsată să treacă
                # I²t ≈ 2·I²t prearc max (SR EN 60269-2), nu Ik1²·0,1 s
                porti = norme.GG_PORTI_A.get(In)
                i2t = norme.GG_I2T_PREARC_KA2S.get(In)
                if porti and i2t and ge(e["Ik1"], porti[3]):
                    n1 = min(n1, math.sqrt(norme.GG_I2T_TOTAL_FACTOR * i2t[1] * 1e3) / kp)
            elif tip == "MCB" and prot.get("curba", "C") in ("B", "C") and e["Ia"] is not None and ge(e["Ik1"], e["Ia"]):
                # MCB clasa 3 (SR EN 60898-1 anexa ZA): I²t limitat în zona instantanee
                e_lim = norme.mcb_i2t(In, e["Ik1"])
                if e_lim is not None:
                    n1 = min(n1, math.sqrt(e_lim) / kp)
            n3 = ik3o * 1000.0 * math.sqrt(t3) / kp if tip in ("MCCB", "ACB") else 0.0
            return n1, n3, t1

        n1, n3, t1 = necesar_pe(ev)
        tot = ev["n"] * ev["s_pe"]
        v36 = ("INFO", max(n1, n3))
        if lt(tot, n1) or lt(tot, n3):
            f1, f3 = lt(tot, n1), lt(tot, n3)
            alt = None
            if ev["loc"] == "cablu" and S_f is None and PE_f is None and not (f3 and not f1 and ctx.get("ik3_implicit")):
                # v1.2 R2 (N-M4): Cu ≤ 35 mm² — PE rămâne în cablu (5×S, §B.11), se mărește secțiunea cablului
                for S4 in cb.sectiuni(c):
                    if S4 <= ev["S"] or not cb.pe_in_cablu(mat, S4, retea):
                        continue
                    e4 = evalueaza(compune(ev["n"], S4))
                    a1, a3, _ = necesar_pe(e4)
                    if e4["loc"] == "cablu" and ge(e4["n"] * e4["s_pe"], max(a1, a3)):
                        alt = e4
                        break
            if alt is not None:
                ev = alt
                n1, n3, t1 = necesar_pe(ev)
                v36 = ("INFO_marit_cablu", max(n1, n3))
            elif (S_f is not None and not r.get("_pe_liber")) or PE_f is not None or ev["loc"] == "PEN":
                v36 = ("B", max(n1, n3))
            elif f3 and not f1 and ctx.get("ik3_implicit"):
                v36 = ("AV", n3)
            else:
                kp = norme.K_PE_SEPARAT[("Cu", "PVC")]
                tinta = ev["Ik1"] * math.sqrt(t1) / kp
                n3s = ik3o * 1000.0 * math.sqrt(t3) / kp if tip in ("MCCB", "ACB") else 0.0
                if not ctx.get("ik3_implicit"):
                    tinta = max(tinta, n3s)
                s_nou = cb.sectiune_std_minima(tinta / ev["n"], max(ev["s_pe"], norme.S_MIN_PE_SEPARAT["neprotejat"]))
                if s_nou is None:
                    v36 = ("B", max(n1, n3))
                else:
                    ev = evalueaza(compune(ev["n"], ev["S"], (s_nou, "separat")))
                    n1, n3, t1 = necesar_pe(ev)
                    v36 = ("INFO_marit", tinta)
                    if lt(ev["n"] * ev["s_pe"], n3) and ctx.get("ik3_implicit"):
                        v36 = ("AV", n3)
    except cb.InAfaraTabelelor as e:
        emite(j, "V10", BLOCANT, obiect, parametru=e.parametru, tabel=e.tabel)
        return _blocat(ib)

    n, S = ev["n"], ev["S"]
    j.pas(f"{obiect}: ΔU = {fmt_ro(ev['dU_r'])} % (L = {fmt_ro(L, 0)} m); cumulat = {fmt_ro(du0)} + "
          f"{fmt_ro(ev['dU_r'])} = {fmt_ro(ev['dU_c'])} % (limită {fmt_ro(lim)} %)")
    j.pas(f"{obiect}: Ik3max la origine {fmt_ro(ik3o)} kA, la capăt {fmt_ro(ev['Ik3c'])} kA; Ik1min la capăt "
          f"{fmt_ro(ev['Ik1'])} A; Ia({fmt_ro(t_cer)} s) = {fmt_ro(ev['Ia']) if ev['Ia'] is not None else '—'} A")
    t3_txt = (f"; la Ik3max {fmt_ro(ik3o)} kA (t = {fmt_ro(t3)} s): S ≥ {fmt_ro(n3, 1)} mm²" if n3 > 0 else "")
    j.pas(f"{obiect}: N = {fmt_ro(ev['N'])} mm², PE = {fmt_ro(ev['s_pe'])} mm² ({ev['loc']}); termic PE: "
          f"la Ik1min {fmt_ro(ev['Ik1'], 0)} A (t = {fmt_ro(t1)} s): S ≥ {fmt_ro(n1, 1)} mm²{t3_txt} "
          f"→ necesar {fmt_ro(max(n1, n3), 1)} mm²")

    # ---- emiterea verificărilor pașilor 8–14, pe configurația finală ---------------------------------------------------
    if gt(ev["dU_c"], lim):
        if lim_max is not None and gt(ev["dU_c"], lim_max):
            # v1.2 (C6): peste limita I7 nici mărirea automată nu ajută → BLOCANT
            emite(j, "V20", BLOCANT, obiect, "inv" if invertor else "bara", x=ev["dU_c"], lim=lim_max,
                  detaliu=" cu secțiunea impusă" if S_f is not None else " chiar la secțiunea maximă (4 × 240 mm²)")
        elif cod_lim == "V21" or invertor:
            emite(j, "V21", AVERTISMENT, obiect, x=ev["dU_c"], lim=lim)
        else:
            emite(j, "V20", BLOCANT, obiect, x=ev["dU_c"], lim=lim)
    # SPEC §B.12 / §B.3.1: ΔU la pornirea directă a motorului (Ip = k·Ib, cosφ 0,35), cu impedanța sursei până la bară
    du_porn = None
    if ip_porn is not None:
        cp = norme.MOTOR_COSFI_PORNIRE
        sp = math.sqrt(1 - cp ** 2)
        zq0 = ctx.get("Zq") or (0.0, 0.0)
        if retea == "mono":
            du_src = 100.0 * 2 * ip_porn * (zq0[0] * cp + zq0[1] * sp) / norme.U_0_V
        else:
            du_src = 100.0 * math.sqrt(3) * ip_porn * (zq0[0] * cp + zq0[1] * sp) / norme.U_N_V
        # v1.2 R2: pe sursă se adaugă doar creșterea de curent (Ip − Ib); ΔU_origine conține deja Ib
        du_src = du_src * max(ip_porn - ib, 0.0) / ip_porn
        du_porn = du0 + du_src + cb.du_pct(retea, ip_porn, L, mat, izl, S, n, cp)
        j.pas(f"{obiect}: ΔU la pornire ({PORNIRE_TXT.get(pornire, pornire)}, Ip = {fmt_ro(ip_porn)} A, cosφ {fmt_ro(cp)}) = {fmt_ro(du0)} + "
              f"{fmt_ro(du_src)} (sursă) + {fmt_ro(du_porn - du0 - du_src)} (cablu) = {fmt_ro(du_porn)} %")
        if gt(du_porn, norme.DU_PORNIRE_MOTOR_PCT):
            emite(j, "V22", AVERTISMENT, obiect, x=du_porn, lim=norme.DU_PORNIRE_MOTOR_PCT, k=k_porn)
        if motor_v23 is not None:
            prag_txt = motor_v23[1]
            if motor_v23[0] == "INFO":
                emite(j, "V23", INFO, obiect, "INFO", prot=f"{tip} {fmt_ro(In)} A", Ip=ip_porn,
                      t=norme.MOTOR_T_PORNIRE_S)
            else:
                emite(j, "V23", AVERTISMENT, obiect, "AV", prot=f"{tip} {fmt_ro(In)} A", Ip=ip_porn,
                      t=norme.MOTOR_T_PORNIRE_S, prag=prag_txt if prag_txt is not None else "—")
    if ev["motiv_N"]:
        emite(j, "V25", BLOCANT, obiect, N=ev["N"], motiv=ev["motiv_N"], S=S)
    if PE_f is not None and lt(n * ev["s_pe"], ev["s_tab"]):
        emite(j, "V26", BLOCANT, obiect, S_PE=ev["s_pe"], S_tab=round(ev["s_tab"], 1))
    stare = ev["stare"]
    ia_v = ev["Ia"]
    if ctx.get("tt_ddr_defect") and schema == "TT" and ctx.get("ddr_ramura"):
        # v1.5 (§C.8 pct. 6, runda 4 P0-3): în TT curentul de defect la masă se închide prin pământ (≈ U0/(RA + RB),
        # câțiva amperi) — MCB-ul NU asigură deconectarea; protecția la defect = DDR (RA·IΔn ≤ 50 V, art. 411.5.3).
        # Ik1 (bucla fază–nul) rămâne doar pentru protecția la scurtcircuit L–N.
        idn_tt = ctx["tt_ddr_defect"]["IdN_mA"]
        ra_tt = ctx["tt_ddr_defect"]["RA_ohm"]
        par = dict(ddr=f"DDR {idn_tt} mA", RA=ra_tt, IdN=idn_tt, x=ra_tt * idn_tt / 1000.0, ik1=round(ev["Ik1"]),
                   ia=ia_v if ia_v is not None else "—")
        if ia_v is not None and ge(ev["Ik1"], ia_v):
            emite(j, "V30", INFO, obiect, "TT", **par)
        else:
            emite(j, "V30", AVERTISMENT, obiect, "TT_AV", **par)
        stare = None
    if stare is None:
        pass
    elif stare == "ok":
        if marit_deconectare:
            emite(j, "V30", INFO, obiect, "INFO_marit", S=S, ik1=round(ev["Ik1"]), ia=ia_v)
        else:
            emite(j, "V30", INFO, obiect, "INFO", ik1=round(ev["Ik1"]), ia=ia_v, t=t_cer)
    elif stare == "ddr_propriu":
        emite(j, "V31", INFO, obiect, "INFO", ik1=round(ev["Ik1"]), ia=ia_v)
    elif stare == "ddr_amonte":
        emite(j, "V31", AVERTISMENT, obiect, "AV", ik1=round(ev["Ik1"]), ia=ia_v)
    elif stare == "z_implicit":
        emite(j, "V32", AVERTISMENT, obiect, ik1=round(ev["Ik1"]), ia=ia_v)
    elif stare == "regim_ge":
        # v1.2 R2 (N-C1): regim GE fără DDR — deconectarea automată nu este asigurată
        emite(j, "V85", BLOCANT, obiect, "ramura", x=round(ev["Ik1"]), y=ia_v)
    elif stare == "blocant":
        emite(j, "V30", BLOCANT, obiect, "B", ik1=round(ev["Ik1"]), ia=ia_v)
    else:
        emite(j, "V30", AVERTISMENT, obiect, "AV", prot=f"{tip} {fmt_ro(In)} A", t=t_cer)
    # 13. Icu (B.16)
    icu = prot.get("Icu_kA")
    if icu is not None and lt(icu, ik3o):
        if r.get("bmpt"):
            emite(j, "V33", INFO, obiect, "bmpt", icu=icu, ik3=ik3o)
        elif r.get("rezerva_gG"):
            emite(j, "V33", AVERTISMENT, obiect, "rezerva", icu=icu, ik3=ik3o)
        else:
            emite(j, "V33", BLOCANT, obiect, icu=icu, ik3=ik3o)
    else:
        emite(j, "V33", INFO, obiect, "ok", icu=icu, ik3=ik3o)
    # 14. termic
    niv, x = v35
    if niv == "B":
        emite(j, "V35", BLOCANT, obiect, "B", n=n, S=S, x=round(x, 1))
    elif niv == "AV":
        emite(j, "V35", AVERTISMENT, obiect, "AV", n=n, S=S, x=round(x, 1), ik3=ik3o)
    elif niv == "INFO_marit":
        emite(j, "V35", INFO, obiect, "INFO_marit", n=n, S=S, x=round(x, 1))
    else:
        emite(j, "V35", INFO, obiect, "INFO", detaliu=("aparat limitator, SR HD 60364-4-43 art. 435.1" if x is None
                                                       else f"n·S ≥ {fmt_ro(x, 1)} mm²"))
    niv, x = v36
    if niv == "B":
        emite(j, "V36", BLOCANT, obiect, "B", S=ev["s_pe"], x=round(x, 1))
    elif niv == "AV":
        emite(j, "V36", AVERTISMENT, obiect, "AV", S=ev["s_pe"], x=round(x, 1))
    elif niv == "INFO_marit":
        emite(j, "V36", INFO, obiect, "INFO_marit", S=ev["s_pe"], x=round(x, 1))
    elif niv == "INFO_marit_cablu":
        emite(j, "V36", INFO, obiect, "INFO_cablu", S=ev["S"], x=round(x, 1))
    else:
        emite(j, "V36", INFO, obiect, "INFO", x=round(x, 1))

    # ---- 15. selectivitate (B.18) -----------------------------------------------------------------------------------
    if amonte is not None:
        pr.selectivitate(amonte, prot, ik3o, obiect_sel or f"{obiect} vs amonte", j, bmpt=bmpt_sel)

    # ---- rezultat și 16. contextul barei din aval ------------------------------------------------------------------
    prot_out = {"tip": tip, "In_A": In}
    if tip == "MCB":
        prot_out["curba"] = prot["curba"]
    if tip in ("MCCB", "ACB"):
        prot_out.update({"Ir_A": prot["Ir_A"], "Ir_multiplu": prot["Ir_multiplu"], "decl": prot["decl"]})
        if prot["decl"] == "TM":
            prot_out["Im_A"] = prot["Im_A"]
        else:
            prot_out.update({"Isd_A": prot.get("Isd_A"), "Isd_multiplu": prot.get("Isd_multiplu"),
                             "Ii_A": prot["Ii_A"], "tsd_s": prot["tsd_s"]})
    prot_out["Icu_kA"] = prot.get("Icu_kA")
    if prot.get("Icu_fortat"):
        prot_out["Icu_fortat"] = True
    rez = {"obiect": obiect, "Ib_A": ib, "Ip_min_A": ip_min, "protectie": prot_out, "I2_A": I2, "Iz_min_A": iz_min,
           "material": mat, "izolatie": izl, "metoda": c["metoda"], "n_paralel": n, "S_faza_mm2": S,
           "S_N_mm2": ev["N"], "S_PE_mm2": ev["s_pe"], "PE": ev["loc"], "Iz_tabel_A": ev["Iz_tab"],
           "k_total": ev["k"], "Iz_corectat_A": ev["Izp"],
           "cablu": text_cablu(mat, izl, c["metoda"], n, S, ev["N"], ev["s_pe"], ev["loc"], retea,
                               monopolar=cb.monopolar(c)),
           "L_m": L, "dU_ramura_pct": ev["dU_r"], "dU_cumulat_pct": ev["dU_c"], "dU_limita_pct": lim,
           "Ik3max_origine_kA": ik3o, "Ik3max_capat_kA": ev["Ik3c"], "Ik1min_capat_A": ev["Ik1"],
           "Ia_A": ia_v, "t_deconectare_s": t_cer, "retea": retea, "receptor": receptor}
    if cb.monopolar(c):
        rez["monopolar"] = True
    if plafon[0] and gt(ev["dU_c"], lim):
        rez["dU_plafonat_mm2"] = float(r["S_max_dU"])
    if ddr_out:
        rez["DDR"] = ddr_out
    if h3 is not None and retea == "tri" and h3 > 33:
        rez["protectie_neutru"] = True
    if ip_porn is not None:
        rez.update({"pornire": pornire, "Ip_pornire_A": ip_porn, "dU_pornire_pct": du_porn})
    # M9: Ik1min nu poate depăși Ik3max (impedanțe incoerente) → V15 BLOCANT
    if gt(ev["Ik1"], ev["Ik3c"] * 1000.0 * (1 + 1e-6)):
        emite(j, "V15", BLOCANT, obiect, ik1=round(ev["Ik1"]), ik3=round(ev["Ik3c"] * 1000.0))
    ctx_aval = {"Zq": ev["Zq"], "Zb": ev["Zb"], "Ik3_kA": ev["Ik3c"], "dU_pct": ev["dU_c"],
                "origine": ctx["origine"], "z_implicit": ctx.get("z_implicit", False),
                "ik3_implicit": ctx.get("ik3_implicit", False),
                "ddr_amonte": bool(ctx.get("ddr_amonte") or ctx.get("ddr_ramura")), "ddr_ramura": None,
                "are_aval": False, "schema": schema,
                # TT (v1.2 R3): DDR-urile din aval ≤ IΔn/3 (selectivitate, SR HD 60364-5-53 art. 535.3)
                "idn_tt_mA": idn_aval_tt(ddr_tt) if ddr_tt else ctx.get("idn_tt_mA"),
                "regim_ge": ctx.get("regim_ge", False),
                # v1.3: cel mai apropiat DDR din amonte (selectivitatea DDR în serie, §B.18.1) și RA în TT
                "ddr_sus": ddr_sus_aval, "RA_tt": ctx.get("RA_tt")}
    return {"rezultat": rez, "prot": prot, "ctx_aval": ctx_aval, "blocat": False, "Ib": ib, "Ip": Ip}


def _vecini(serie, v):
    """Vecinii unui calibru inexistent din serie, pentru remedierea V05 (SPEC §D)."""
    s = sorted(serie)
    jos = [x for x in s if x < v]
    sus = [x for x in s if x > v]
    return (jos[-1] if jos else "—"), (sus[0] if sus else "—")


def verifica_cablu(param_cablu, protectie, obiect="cablu"):
    """v1.2 R2 (N-M1): verificarea unui cablu din model (desenat / editat manual) față de protecția lui, cu Iz'
    RECALCULAT din secțiune, material, izolație, metodă și pozare (nu preluat din `Iz_corectat_A`).

    param_cablu: {material, izolatie, metoda, S_faza_mm2 (sau S), n_paralel (sau n), retea, theta?, rho_sol?, n_alte?,
                  distanta?, aranjament?, Iz_corectat_A? (doar comparat)}
    protectie:   {tip: MCB|MCCB|ACB|gG, In_A, Ir_A?, curba?}
    Întoarce lista verificărilor {cod, nivel, obiect, mesaj, remediere}: V13 (secțiune inexistentă), V10 (pozare/
    material în afara tabelelor), V02 (Ip > Iz'), V03 (I2 > 1,45·Iz') — BLOCANT; plus un V02 INFO cu `Iz_corectat_A`
    recalculat (și `Iz_declarat_A` dacă diferă de valoarea din parametri cu > 1 %)."""
    from .comun import Jurnal
    j = Jurnal()
    p = dict(param_cablu or {})
    q = dict(protectie or {})
    mat = p.get("material")
    mat = mat.strip().capitalize() if isinstance(mat, str) else mat
    izl = (p.get("izolatie") or "PVC")
    izl = izl.strip().upper() if isinstance(izl, str) else izl
    met = p.get("metoda") or "D1"
    S = p.get("S_faza_mm2", p.get("S"))
    n = p.get("n_paralel", p.get("n")) or 1
    retea = p.get("retea") or "tri"
    if mat not in ("Cu", "Al") or izl not in ("PVC", "XLPE") or met not in norme.METODE_POZARE:
        emite(j, "V10", BLOCANT, obiect, parametru=f"material/izolație/metodă „{mat} {izl} {met}”", tabel="B.52.2–B.52.13")
        return j.verificari
    c = {"material": mat, "izolatie": izl, "metoda": met, "retea": "mono" if retea == "mono" else "tri",
         "theta": p.get("theta") if p.get("theta") is not None else cb.theta_implicit(met),
         "rho_sol": p.get("rho_sol") if p.get("rho_sol") is not None else 2.5, "n_alte": int(p.get("n_alte") or 0),
         "distanta": p.get("distanta", "atingere"), "aranjament": p.get("aranjament")}
    try:
        S = float(S)
        n = int(n)
    except (TypeError, ValueError):
        emite(j, "V13", BLOCANT, obiect, S=S, mat=mat)
        return j.verificari
    if S not in cb.sectiuni(c) or n < 1 or n > cb.n_max(c):
        emite(j, "V13", BLOCANT, obiect, S=fmt_ro(S), mat=mat)
        return j.verificari
    try:
        _, _, izp = cb.iz_corectat(c, n, S)
    except cb.InAfaraTabelelor as e:
        emite(j, "V10", BLOCANT, obiect, parametru=e.parametru, tabel=e.tabel)
        return j.verificari
    tip = pr.normalizeaza_tip(q.get("tip"))
    if tip not in pr.SERII or q.get("In_A") is None:
        emite(j, "V07", BLOCANT, obiect, "param", camp="protectie", x=repr(q.get("tip")), conditie="protecție necunoscută")
        return j.verificari
    prot = {"tip": tip, "In_A": float(q["In_A"]), "curba": q.get("curba", "C")}
    if tip in ("MCCB", "ACB"):
        prot["Ir_A"] = float(q.get("Ir_A") or q["In_A"])
    Ip = pr.ip(prot)
    I2 = pr.i2(prot)
    if gt(Ip, izp):
        emite(j, "V02", BLOCANT, obiect, Ip=Ip, Iz=izp)
    if gt(I2, 1.45 * izp):
        emite(j, "V03", BLOCANT, obiect, I2=I2, lim=1.45 * izp)
    info = {"cod": "V02", "nivel": "INFO", "obiect": obiect, "remediere": "",
            "mesaj": f"{obiect}: Iz' recalculat = {fmt_ro(izp, 1)} A (Ip = {fmt_ro(Ip)} A, I2 = {fmt_ro(I2)} A)",
            "Iz_corectat_A": izp}
    dec = p.get("Iz_corectat_A")
    if isinstance(dec, (int, float)) and abs(dec - izp) > 0.01 * izp:
        info["Iz_declarat_A"] = dec
        info["mesaj"] += f" — valoarea din parametri {fmt_ro(dec, 1)} A ignorată"
    return j.verificari + [info]

engine/calc/scheme.py:
"""scheme.py — regulile pe tip de schemă (SPEC §C.1–§C.6), verificarea modelului (V80/V81, SPEC §E.1) și
punctul de intrare `calculeaza(intrare)`.

    calculeaza(intrare) -> {"rezultat", "verificari", "info", "blocheaza_export", "presupus", "pasi", "ipoteze"}

`intrare` are exact forma câmpului "intrare" din tests/date/cazuri_golden.json.
"""
import copy
import math
import unicodedata

from . import norme
from . import protectii as pr
from . import scurtcircuit as sc
from .comun import Jurnal, ge, gt, lt, eq, prima_din_serie, u_calcul, SQRT3
from .ramura import calculeaza_ramura, valideaza
from . import cabluri as cb
from . import ddr as ddr_mod
from . import pamant
from .texte import fmt_ro, NB, X, note_generate, verifica_aparat, verifica_nota, nota_bransament, nota_schema_pamant
from .verificari import emite, BLOCANT, AVERTISMENT, INFO

DT_QG = norme.DDR_DT_SELECTIVITATE_S         # Δt al blocului diferențial reglabil pe intrarea TT (v1.3 R5)
RCCB_IN_BRANSAMENT = [16, 25, 40, 63, 80, 100, 125, 160, 200, 250]   # SPEC §C.1 (peste 125 A: bloc diferențial, M11)
CAMPURI_CABLU_SCHEMA = ("material", "izolatie", "metoda", "theta", "rho_sol", "n_alte", "S_fortat", "n_fortat",
                        "N_fortat", "PE_fortat", "PE_loc", "distanta", "aranjament")
C1_TEXT = "racord OD — nu se dimensionează în proiectul consumatorului"


# ============================================================================================================
# utilitare comune schemelor
# ============================================================================================================
def _fara_diacritice(s):
    """Copia de lucru fără diacritice, litere mici (SPEC §C.2 „Receptorul după nume”, §F.2 pct. 2)."""
    s = unicodedata.normalize("NFKD", s or "")
    return "".join(ch for ch in s if not unicodedata.combining(ch)).lower()


def receptor_dupa_nume(nume, nivel):
    """SPEC §C.2, „Receptorul după nume”: ilumin → iluminat; priz → prize; motor/pomp/compresor/ventila/moar/
    concasor/malaxor → motor; altfel tablou (nivel 0) sau forță (nivel ≥ 1)."""
    n = _fara_diacritice(nume)
    if "ilumin" in n:
        return "iluminat"
    if "priz" in n or "socket" in n:
        return "prize"
    if any(k in n for k in ("motor", "pomp", "compresor", "ventila", "moar", "concasor", "malaxor")):
        return "motor"
    return "tablou" if nivel == 0 else "forta"


def _zb_din_intrare(zb, j):
    """M2 (v1.2): impedanța buclei OD din ATR — perechea (R, X), dict {R, X} sau modulul |Z| (număr). La modul,
    R/X = 2 (raportul valorii implicite 0,18 + j0,09 Ω, rețea rurală LEA/LES) — declarat ca presupus."""
    if zb is None:
        return None
    if isinstance(zb, dict):
        return (float(zb.get("R", zb.get("R_ohm", 0.0))), float(zb.get("X", zb.get("X_ohm", 0.0))))
    if isinstance(zb, (list, tuple)):
        return (float(zb[0]), float(zb[1]))
    z = float(zb)
    r0, x0 = norme.OD_ZBUCLA_IMPLICIT_OHM
    m0 = math.hypot(r0, x0)
    j.presupune(f"Zbuclă OD dată ca modul |Z| = {fmt_ro(z, 3)} Ω: R/X = {fmt_ro(r0 / x0)} presupus (ca la valoarea "
                f"implicită 0,18 + j0,09 Ω) → Zb = {fmt_ro(z * r0 / m0, 3)} + j{fmt_ro(z * x0 / m0, 3)} Ω")
    return (z * r0 / m0, z * x0 / m0)


def _context_od(inp, j, ddr_amonte):
    """SPEC §B.0 și §B.13: contextul rețelei OD la punctul de delimitare, cu declararea valorilor implicite.
    M9 (v1.2): cu Ik3 dat și Zb implicit, Zb implicit se ridică la cel puțin 2·Z_Q (pe componente), astfel încât
    Ik1min ≤ Ik3max pe orice ramură."""
    ik3 = inp.get("Ik3_OD_kA")
    zb = _zb_din_intrare(inp.get("Zb_OD_ohm"), j)
    ctx = sc.context_od(ik3, zb, ddr_amonte=ddr_amonte, schema="TT" if inp.get("schema_pamant") == "TT" else "TN")
    if ik3 is None:
        j.presupune(f"Ik3max OD la punctul de delimitare {fmt_ro(norme.OD_IK3MAX_IMPLICIT_KA)} kA (valoare implicită "
                    f"presupusă — se confirmă cu OD / ATR)")
    if zb is None:
        if ctx.get("zb_ajustat"):
            j.presupune(f"Zbuclă OD implicită ridicată la 2·Z_Q = {fmt_ro(ctx['Zb'][0], 3)} + j{fmt_ro(ctx['Zb'][1], 3)} Ω "
                        f"(consistentă cu Ik3 OD = {fmt_ro(ctx['Ik3_kA'])} kA; Ik1min ≤ Ik3max) — presupusă, se confirmă cu OD / ATR")
        else:
            j.presupune("Zbuclă OD 0,18 + j0,09 Ω (|Z| = 0,201 Ω, valoare implicită presupusă — se confirmă cu OD / ATR)")
    j.ipoteza("ik3_od", ctx["Ik3_kA"], ik3 is None)
    # v1.7 (§C.8, N11): Zb presupus după zonă (locuință rurală) — marcat presupus, cu sursa, nu „declarat”
    j.ipoteza("zb_od", sc.modul(ctx["Zb"]), inp.get("_zb_presupus") or zb is None)
    return ctx


