    if rz.get("servicii_proprii"):
        m["plecari"].append(_plecare(rz["servicii_proprii"], f"Q{len(m['plecari']) + 4}", {"nume": "Servicii proprii PT"}))
    m["carcasa"] = {"titlu": f"PT {sn} kVA", "sub": "post de transformare 20/0,4 kV · celule MT + trafo + TGJT"}
