    m["intrari"] = [{"sursa": {"titlu": "CÂMP PV", "sub": f"invertor {_f(pn)} kW"}, "cablu": {"ref": "", "cond": "c.c.", "text": "H1Z2Z2-K"},
                     "cablu_ca": _cablu(inv), "aparate": ap}]
    spd = {"tip": "spd", "ref": "F1", "param": {"sablon": "spd_ca", "tip": "T2", "poli": "2P" if mono else "4P", "In_amonte_A": 40}}
    m["bara"] = {"afisare": True, "forteaza": True, "eticheta": "TE consumator · bare existente", "laterale": [spd]}
    qb = inp.get("In_Q_bransament_A")
    m["plecari"] = [{"aparate": [], "cablu": {"ref": "", "cond": "L + N + PE" if mono else "3 + N + PE", "text": "existent"},
                     "sarcina": {"titlu": "Branșament existent", "sub": (f"Q {qb}{NB}A {PUNCT} " if qb else "") + "contor bidirecțional (OD)"}}]
    # circuitele consumatorului (generic, cerut de OD): pe aceeași bară a TE
    for k, cg in enumerate(_te_generic(mono, qb)[0]["copii"]):
        cg["aparate"][0]["ref"] = f"Q{k + 2}"
        cg["sarcina"]["sub"] = "existent / generic"
        m["plecari"].append(cg)
    m["carcasa"] = {"titlu": "TE", "sub": "tablou electric consumator · prosumator"}
    m["cartus"]["denumire2"] = f"PROSUMATOR {_f(pn)} kW {'MONOFAZAT' if mono else 'TRIFAZAT'}"
    return "prosumator"


def _ge(inp, rz, m):
    """GE + ATS (SPEC §C.6): două intrări DISTINCTE în ATS — I: rețea (QR → C1), II: GE (QG → C2) —, cei doi poli ai
    comutatorului interblocați mecanic + electric (sursele nu pot fi niciodată în paralel), ieșirea ATS → C3 → consumatori"""
    qg, qr, ats = rz.get("Q_G") or {}, rz.get("Q_retea") or {}, rz.get("ATS") or {}
    c1, c2, c3 = rz.get("C1") or {}, rz.get("C2") or {}, rz.get("C3") or {}
    sn = inp.get("Sn_GE_kVA")
    p_ats = {"In_A": ats.get("In_A")}
    pol = lambda poz, buc: dict(_ap("separator", f"ATS·{poz}", "ats", p_ats, interblocaj="ATS", buc=buc))
    ap_r = []
    p = _prot((c1.get("protectie") or dict(qr, tip=qr.get("tip", "MCCB"))), "QR")
    if p:
        p["in_carcasa"] = False
        ap_r.append(p)
    ap_r.append(pol("I", 1))
    ap_g = [_ap("generator", "G", "ge", {"Sn_kVA": sn, "In_G_A": rz.get("In_G_A")}, in_carcasa=False, neutru_pamant=True)]
    p = _prot((c2.get("protectie") or dict(qg, tip=qg.get("tip", "MCCB"))), "QG")
    if p:
        p["in_carcasa"] = False
        ap_g.append(p)
    d = _ddr(qg.get("DDR"), "DDR-G")      # bloc diferențial pe QG: deconectarea în regim GE (Ik1 ≈ In_G)
    if d:
        d["in_carcasa"] = False
        ap_g.append(d)
    den, car = text_lista("ats", p_ats)   # al doilea pol al ATS: același aparat → aceeași poziție în listă, fără text dublat
    ap_g.append({"tip": "separator", "ref": "ATS·II", "spec": [], "lista": [den, car], "interblocaj": "ATS", "buc": 0})
    m["intrari"] = [{"sursa": {"titlu": "RED 0,4 kV", "sub": "alimentare normală (poziția I)"},
                     "cablu": {"ref": "", "cond": "3 + N + PE", "text": "existent"}, "cablu_ca": _cablu(c1, "C1"), "aparate": ap_r},
                    {"sursa": {"titlu": "GRUP ELECTROGEN", "sub": f"{sn} kVA {PUNCT} In_G = {_f(rz.get('In_G_A'))}{NB}A (poziția II)"},
                     "cablu": {"ref": "", "cond": "", "text": ""}, "cablu_ca": _cablu(c2, "C2"), "aparate": ap_g}]
    m["bara"] = {"afisare": True, "eticheta": f"Ieșire ATS {PUNCT} bare 3P + N + PE {PUNCT} {ats.get('In_A', '')}{NB}A"}
    m["plecari"] = [{"aparate": [], "cablu": _cablu(c3, "C3"),
                     "sarcina": {"titlu": "Consumatori", "sub": f"P = {_f(inp.get('P_sarcina_kW'))}{NB}kW {PUNCT} {_sub_ramura(c3)}"}}]
    m["carcasa"] = {"titlu": "TAR", "sub": "tablou de anclanșare automată a rezervei (ATS 4P, comută și N)"}
    m["lista_pe"] = ["Neutrul GE legat la priza de pământ locală (TN-S), Rp ≤ 4 Ω", "ATS 4P: comută și conductorul N"]
    m["cartus"]["denumire2"] = f"GRUP ELECTROGEN {sn} kVA + ATS"
    return "grup electrogen + ATS"



def _locuinta(inp, rz, m):
    """tabloul unei locuințe (SPEC §C.8): branșamentul (în afara TE: SF, contor, Q / RCBO, RCCB), coloana C2, TE cu bara PE / N
    și legătura la priza de pământ, Q general, SPD pe bară, grupe DDR 30 mA desenate ca „pieptene” în același tablou
    (plecare cu `grup`), circuitele finale sub ele"""
    ret = rz.get("retea") or inp.get("retea")
    ret = {"trifazat": "tri", "trifazic": "tri", "monofazat": "mono", "monofazic": "mono"}.get(str(ret).strip().lower(), str(ret).strip().lower())
    mono = ret != "tri"
    tt = (rz.get("schema_pamant") or inp.get("schema_pamant")) == "TT"
    al = rz.get("alimentare") or {}
    col = rz.get("coloana") or {}
    bloc = al.get("bloc") or ("BMPM" if mono else "BMPT")
    _ia = inp.get("alimentare") if isinstance(inp.get("alimentare"), dict) else {}
    nou = _ia.get("tip") == "bransament_nou"
    # ---- branșamentul: aparatele blocului de măsură, desenate DEASUPRA tabloului (în afara carcasei TE)
    br = []
    SF, Q, rc = al.get("SF") or {}, al.get("Q") or {}, al.get("RCCB") or {}
    if SF.get("In_A"):
        if mono:
            br.append(_ap("fuzibil", "SF", "sep_sig", {"In_A": SF["In_A"], "poli": 1, "gabarit": "00"}, in_carcasa=False))
        else:
            br.append(_ap("sep_fuzibil", "SF", "sf", {"In_A": SF["In_A"], "soclu_A": SF.get("soclu_A"), "gabarit": SF.get("gabarit")}, in_carcasa=False))
    br.append(_ap("contor_direct", "P", "contor", {"retea": "mono" if mono else "tri", "masura": "directa"}, in_carcasa=False))
    if Q.get("In_A"):
        if mono:
            q = _ap("rcbo", "QB", "rcbo", {"In_A": Q["In_A"], "IdN_mA": 300, "tip_ddr": al.get("DDR_bransament_tip") or "AC"}, in_carcasa=False)
        elif Q.get("tip") == "MCB":
            q = _ap("mcb", "QB", "mcb", {"In_A": Q["In_A"], "curba": Q.get("curba", "C"), "poli": "4P", "Icn_kA": Q.get("Icn_kA", 6)}, in_carcasa=False)
        else:
            q = _ap("mccb", "QB", "mccb", {"In_A": Q["In_A"], "Ir_A": Q.get("Ir_A"), "poli": "4P", "Icu_kA": Q.get("Icu_kA") or 25}, in_carcasa=False)
        br.append(q)
    if rc.get("In_A"):
        par = {"In_A": rc["In_A"], "poli": f"{rc.get('poli', 4)}P" if str(rc.get("poli", 4)).isdigit() else rc.get("poli"),
               "IdN_mA": rc.get("IdN_mA", 300), "tip_ddr": al.get("DDR_bransament_tip") or rc.get("tip", "AC")}
        for k in ("selectiv", "aparat", "asociat"):
            if rc.get(k) is not None:
                par[k] = rc[k]
        br.append(_ap("rccb", "RCCB", "rccb", par, in_carcasa=False))
    # ---- TE: bara PE / N (cu legătura PE → priza de pământ), Q general
    ap = list(br)
    ap.append({"tip": "nod", "ref": "", "laterale": [{"tip": "bareta_nul", "la_stanga": True, "eticheta": "BPE",
                                                      "nota": "bare N și PE separate" if not tt else "PE local de la priza proprie (TT)",
                                                      "fara_legatura": col.get("legatura_BPE") is False or tt}]})
    qg = rz.get("Q_general") or {}
    poli_g = qg.get("poli") or ("2P" if mono else "4P")
    if qg.get("tip") == "IS" and qg.get("In_A"):
        ap.append({"tip": "separator", "ref": "QG", "spec": [f"{poli_g} {PUNCT} {qg['In_A']}{NB}A", "întreruptor-separator"],
                   "lista": [f"Întreruptor-separator modular {poli_g}, In {qg['In_A']}{NB}A, {'230' if mono else '400'}{NB}V",
                             "SR EN 60947-3, AC-22A, montaj pe șină DIN — separare generală TE"]})
    else:
        p = _prot(qg, "QG", poli=poli_g)
        if p:
            ap.append(p)
    c2 = _cablu(col, "C2")
    c1 = {"ref": "C1", "cond": al.get("C1_conductoare") or (("L + N" if mono else "3 + N") if tt else ("L + PEN" if mono else "3 + PEN")),
          "text": "racord OD — conform ATR"}
    if c2.get("cond") and col.get("conductoare"):
        c2["cond"] = col["conductoare"]
    elif tt and c2.get("cond"):      # TT: fără PEN / PE în coloană; PE-ul vine de la priza de pământ proprie
        c2["cond"] = "L + N" if mono else "3 + N"
    pres = [x for x, k in (("Q", "Q_presupus"), ("Pa", "Pa_presupus")) if al.get(k)]
    sub_src = f"{bloc} {'nou, conform ATR' if nou else 'existent'} — racord OD" + (" · TT" if tt else "")
    if pres:       # valorile presupuse se văd pe planșă, nu par date confirmate
        sub_src += f" · {' și '.join(pres)} PRESUPUS — de confirmat din ATR"
    m["intrari"] = [{"sursa": {"titlu": "RED 0,4 kV", "sub": sub_src},
                     "cablu": c1, "cablu_ca": c2, "aparate": ap}]
    S_pe = max(10, col.get("S_PE_mm2") or 0) if col else 16
    ra = inp.get("RA_ohm")
    if tt:
        m["lista_pe"] = [f"Bară PE și bară N în TE · bornă principală de împământare (BPI) · conductor PE FY {fmt_ro(S_pe, 0)} mm² Cu spre priza de pământ",
                         "priză de pământ proprie (TT): electrozi OL-Zn + platbandă OL-Zn 40×4 mm · RA·IΔn ≤ 50 V · BEP baie legată la BPI"]
        m["rp"] = (f"RA = {fmt_ro(ra, 0)} Ω · RA·IΔn ≤ 50 V" if ra else "RA·IΔn ≤ 50 V")
    else:
        m["lista_pe"] = [f"Bară PE și bară N în TE (separate) · bornă principală de împământare (BPI) · conductor PE FY {fmt_ro(S_pe, 0)} mm² Cu",
                         f"PE din coloana C2 legat la BN din {bloc} · priză de pământ locală (repetată) Rp ≤ 4 Ω · BEP baie legată la BPI"]
        m["rp"] = "Rp ≤ 4 Ω"
    m["ref_pe"] = "BPE·PS·PPL"
    spd = rz.get("SPD") or {}
    lat = []
    if spd:
        pr = spd.get("protectie_rezerva") or {}
        par = {"sablon": "spd_ca", "tip": spd.get("tip", "T2"), "poli": spd.get("poli") or ("1P+N" if mono else "3P+N"),
               "In_amonte_A": pr.get("In_A") or spd.get("In_amonte_A") or qg.get("In_A") or 32}
        if pr.get("tip"):
            par["prot_tip"] = pr["tip"]
            if pr.get("curba"):
                par["curba"] = pr["curba"]
        sp = {"tip": "spd", "ref": "F1", "param": par, "fara_pamant": True}
        if pr.get("In_A"):
            txt = pr.get("text") or f"MCB {pr.get('poli') or ''} {pr.get('curba') or 'C'}{pr['In_A']}{NB}A"
            sp["rezerva"] = {"ref": pr.get("ref") or "F2", "tip": "mcb",
                             "spec": [f"{pr.get('curba') or 'C'}{pr['In_A']}{NB}A", "rezervă SPD"],
                             "lista": [f"Protecție de rezervă SPD: {txt}",
                                       "conform fișei SPD; derivația SPD ≤ 0,5 m până la BPE (SR HD 60364-5-534)"
                                       + ("; SPD în configurație CT2 (eclator N–PE) — TT" if tt else "")]}
        lat.append(sp)
    m["bara"] = {"afisare": True, "forteaza": True, "eticheta": f"Bare / pieptene Cu {PUNCT} {'L + N + PE' if mono else '3P + N + PE'}"
                 + f" {PUNCT} {max(63, qg.get('In_A') or 0)}{NB}A" + (f" (In QG {qg['In_A']}{NB}A)" if qg.get("In_A") else ""), "laterale": lat}
    n_q = 0
    def circuit(c):
        nonlocal n_q
        n_q += 1
        ref = f"Q{n_q}"            # numerotare de la stânga la dreapta, în ordinea de pe planșă
        f = c.get("faza")
        poli = "4P" if (f == "3F" or (not mono and f not in ("L1", "L2", "L3"))) else "1P+N"
        sub = [f if f and not mono else None,
               f"{_f(c['Ib_A'])}{NB}A" if c.get("Ib_A") is not None else None,
               f"ΔU {_f(c['dU_cumulat_pct'], 1)}{NB}%" if c.get("dU_cumulat_pct") is not None else None]
        out = {"aparate": [], "cablu": _cablu(c), "sarcina": {"titlu": c.get("nume") or ref, "sub": f" {PUNCT} ".join(x for x in sub if x)}}
        pr = _prot(c.get("protectie"), ref, poli=poli, retea="mono" if poli == "1P+N" else "tri")
        if pr:
            pr["param"]["lat_desen"] = 12          # coloane înguste: textul aparatului pe 2–3 rânduri scurte
            out["aparate"].append(pr)
        return out
    pl = []
    for g in rz.get("grupe_DDR") or []:
        copii = [circuit(c) for c in g.get("circuite") or []]
        dd = g.get("DDR") or {}
        if dd.get("aparat") == "RCBO":        # circuit singur: RCBO în locul MCB + DDR (protecția circuitului e deja RCBO)
            pl.extend(copii)
            continue
        d = _ddr(g.get("DDR"), g.get("obiect") or "DDR")
        if d:
            d["param"]["lat_desen"] = 14
            if (g.get("DDR") or {}).get("alternativa"):
                d["param"]["nota"] = g["DDR"]["alternativa"]
            et = g.get("faza") if g.get("faza") in ("L1", "L2", "L3") and not mono else ""
            pl.append({"grup": True, "eticheta_grup": et, "aparate": [d], "copii": copii})
        else:
            pl.extend(copii)
    m["plecari"] = pl
    b = rz.get("bilant") or {}
    m["carcasa"] = {"titlu": "TE", "sub": "tablou electric locuință"
                    + (f" {PUNCT} Pi = {_f(b.get('Pi_kW'))} kW {PUNCT} Pc = {_f(b.get('Pc_kW'))} kW" if b.get("Pc_kW") is not None else "")
                    + (f" {PUNCT} Pa = {_f(b.get('P_aprobata_kW'))} kW " + ("(PRESUPUS)" if al.get("Pa_presupus") else "(ATR)") if b.get("P_aprobata_kW") else "")}
    m["cartus"]["denumire2"] = "TABLOU ELECTRIC LOCUINȚĂ (TE) — " + ("MONOFAZAT" if mono else "TRIFAZAT")
    return "tablou locuință"

CONSTRUCTORI = {"bransament": _bransament, "tablou": _tablou, "pt": _pt, "cef": _cef, "prosumator": _prosumator, "ge_ats": _ge, "locuinta": _locuinta}


# ------------------------------------------------------------------------------------------------ texte din parametri
def _regen(a):
    par = a.get("param")
    if not par or not par.get("sablon"):
        return
    p = {k: v for k, v in par.items() if k != "sablon"}
    try:
        den, car = text_lista(par["sablon"], p)
        a["lista"] = [den, car] if car and car != "—" else [den]
        a["spec"] = text_desen(par["sablon"], p)
        if par["sablon"] == "contor":           # caseta are deja „kWh · kVArh”; dedesubt: tensiune și curent
            a["spec"] = [car.split(", telecitire")[0]]
        elif par["sablon"] == "dpst":
            a["spec"] = [f"U> 50{NB}Hz {PUNCT} t 0,13…0,2{NB}s"]
    except Exception as e:      # parametri incompleți → textul indică problema, validatorul blochează
        a["lista"] = [f"[parametri incompleți: {e}]"]
        a["spec"] = ["?"]


def regenereaza_texte(model):
    """SPEC §E.1: spec / lista se regenerează din `param` pentru fiecare aparat și auxiliar generat"""
    def br(b):
        for a in b.get("aparate") or []:
            _regen(a)
            for l in a.get("laterale") or []:
                _regen(l)
        for c in b.get("copii") or []:
            br(c)
    for b in (model.get("intrari") or []) + (model.get("plecari") or []):
        br(b)
    for l in (model.get("bara") or {}).get("laterale") or []:
        _regen(l)
    return model


def materiale_cabluri(model):
    """cablurile cu parametri → rânduri în lista de echipamente (U.M. m, +5 % rezervă), agregate pe tip de cablu (SPEC §E.1 pct. 5)"""
    grup = {}
    def adauga(den, car, ref, metri):
        g = grup.setdefault(den, {"refs": [], "m": 0, "car": car})
        g["refs"].append(ref); g["m"] += metri
    def br(b, ref_implicit):
        for key in ("cablu", "cablu_ca"):
            cab = b.get(key) or {}
            par = cab.get("param")
            if not (par and par.get("S_faza_mm2") and par.get("L_m")):
                continue
            n = int(par.get("n_paralel") or 1) * int(par.get("buc_circuite") or 1)
            metri = math.ceil(par["L_m"] * n * 1.05)
            # doar cablul de fază (conductorul PE separat e rând propriu); același text ca pe planșă, fără „n × (…)”
            txt = text_cablu(par.get("material"), par.get("izolatie"), par.get("metoda"), 1, par.get("S_faza_mm2"),
                             par.get("S_N_mm2"), par.get("S_PE_mm2"), par.get("PE") or "cablu", par.get("retea", "tri"))
            txt = txt.split(" + FY")[0]
            ref = cab.get("ref") or ref_implicit
            npar = int(par.get("n_paralel") or 1)
            mono_r = par.get("retea") == "mono"
            if par.get("monopolar") or str(par.get("metoda") or "").startswith("F"):
                # cabluri MONOPOLARE (treflă pe pat de cabluri): lungimea se socotește pe conductor
                izo = txt.split()[0]
                S, SN = par.get("S_faza_mm2"), par.get("S_N_mm2") or par.get("S_faza_mm2")
                nf = 1 if mono_r else 3
                if SN == S:
                    adauga(f"Cablu monopolar {izo} 1×{fmt_ro(S)} mm² {par.get('material')}", "0,6/1 kV, faze + N, în treflă; nr. de sisteme în paralel conform planșei",
                           ref, math.ceil(par["L_m"] * npar * (nf + 1) * 1.05))
                else:
                    adauga(f"Cablu monopolar {izo} 1×{fmt_ro(S)} mm² {par.get('material')}", "0,6/1 kV, faze, în treflă; nr. de sisteme în paralel conform planșei",
                           ref, math.ceil(par["L_m"] * npar * nf * 1.05))
                    adauga(f"Cablu monopolar {izo} 1×{fmt_ro(SN)} mm² {par.get('material')}", "0,6/1 kV, neutru; nr. de sisteme în paralel conform planșei",
                           ref, math.ceil(par["L_m"] * npar * 1.05))
            else:
                adauga(f"Cablu {txt} {par.get('material')}" + (f" — {npar} cabluri în paralel pe circuit" if npar > 1 else ""),
                       "0,6/1 kV, conform secțiunilor de pe planșă", ref, metri)
            if par.get("PE") == "separat" and par.get("S_PE_mm2"):
                adauga(f"Conductor de protecție FY 1×{fmt_ro(par['S_PE_mm2'])} mm² Cu, galben-verde", "pozat lângă cablul de fază", ref, metri)
        for i, c in enumerate(b.get("copii") or []):
            br(c, ((c.get("sarcina") or {}).get("titlu") if b.get("grup") else None) or f"{ref_implicit}.{i + 1}")
    for i, b in enumerate(model.get("intrari") or []):
        br(b, f"C{i + 1}" if len(model.get("intrari") or []) > 1 else "C1")
    for i, b in enumerate(model.get("plecari") or []):
        br(b, (b.get("sarcina") or {}).get("titlu") or f"P{i + 1}")
    out = []
    for den, g in grup.items():
        refs = g["refs"]
        ref = refs[0] if len(refs) == 1 else (f"{len(refs)} circ." if len(refs) > 3 else ", ".join(refs))
        out.append({"ref": ref, "lista": [den, g["car"] + (f" — {', '.join(refs)}" if len(refs) > 1 else "")], "cantitate": g["m"], "um": "m"})
    return out


# ------------------------------------------------------------------------------------------------ aparataj auxiliar
_GABARIT_NH = [(160, "00"), (250, "1"), (400, "2"), (630, "3"), (1250, "4a")]


def _gabarit(In):
    for lim, g in _GABARIT_NH:
        if In <= lim:
            return g
    return "4a"


def materiale_aparataj(model, inp, rz):
    """articolele care nu apar ca simbol pe planșă, dar se cumpără (SPEC §E.1 pct. 5, completare v1.3):
    patroanele fuzibile ale separatoarelor, sistemul de bare, carcasa tabloului, accesoriile de cablu și
    materialele prizei de pământ calculate. Rândurile au U.M. „buc” / „set” / „m”."""
    out = []
    pat = {}
    def br(b):
        for a in b.get("aparate") or []:
            par = a.get("param") or {}
            if par.get("sablon") in ("sep_sig", "sf") and par.get("In_A"):
                In = int(par["In_A"])
                try:
                    den_sep = text_lista(par["sablon"], {k: v for k, v in par.items() if k != "sablon"})[0]
                except Exception:
                    den_sep = ""
                mg = re.search(r"NH\s*([0-9a]+)", den_sep)
                g = mg.group(1) if mg else str(par.get("gabarit") or _gabarit(In)).upper().replace("NH", "").strip()
                nr = int(par.get("poli") or 3) if par.get("sablon") == "sep_sig" else 3
                k = (g, In)
                e = pat.setdefault(k, {"refs": [], "n": 0})
                e["refs"].append(a.get("ref") or ""); e["n"] += nr * int(a.get("buc") or 1)
        for c in b.get("copii") or []:
            br(c)
    for b in (model.get("intrari") or []) + (model.get("plecari") or []):
        br(b)
    for (g, In), e in sorted(pat.items(), key=lambda t: t[0][1]):
        refs = e["refs"]
        out.append({"ref": refs[0] if len(refs) == 1 else (f"{len(refs)} sep." if len(refs) > 3 else ", ".join(refs)),
                    "lista": [f"Patron fuzibil NH {g}, {In}{NB}A gG", "400/500 V c.a., SR EN 60269-2 — rezervă: 1 set / calibru recomandat"],
                    "cantitate": e["n"], "um": "buc", "tip": "aux"})
    tip = inp.get("tip_schema")
    car = model.get("carcasa") or {}
    In_b, ik = None, None
    if tip == "tablou":
        In_b = ((rz.get("Q1_C1") or {}).get("protectie") or {}).get("In_A"); ik = (rz.get("bara_TG") or {}).get("Ik3max_kA")
    elif tip == "pt":
        In_b = (rz.get("Q_JT") or {}).get("In_A"); ik = (rz.get("trafo") or {}).get("Ik3max_bara_kA")
    elif tip == "cef":
        qg = rz.get("QG") or {}
        In_b = (qg.get("protectie") or qg).get("In_A")
    elif tip == "ge_ats":
        In_b = (rz.get("ATS") or {}).get("In_A")
    if tip == "locuinta" and car:
        mono = "tri" not in str(rz.get("retea") or inp.get("retea") or "").lower()
        mod = 0
        def nm(a):
            par = a.get("param") or {}
            p = str(par.get("poli") or "")
            return 4 if p.startswith(("4", "3")) else 2 if p.startswith(("2", "1P+N")) else 2
        def wm(b):
            nonlocal mod
            for a in b.get("aparate") or []:
                if a.get("in_carcasa") is False or a.get("tip") == "nod":     # branșamentul (BMPM/BMPT) și nodul barei PE nu ocupă module în TE
                    continue
                mod += nm(a) if a.get("param") else (2 if mono else 4)
            for c in b.get("copii") or []:
                wm(c)
        for b in (model.get("intrari") or []) + (model.get("plecari") or []):
            wm(b)
        mod += len((model.get("bara") or {}).get("laterale") or []) * (2 if mono else 4)
        if (rz.get("SPD") or {}).get("protectie_rezerva"):
            mod += 2 if mono else 4            # F2 — protecția de rezervă a SPD, pe șină
        nec = math.ceil(mod * 1.2)
        std = next((x for x in (12, 18, 24, 36, 48, 54, 72, 96) if x >= nec), nec)
        out.append({"ref": car.get("titlu", "TE"), "lista": [f"Tablou modular TE {std} module DIN ({math.ceil(std / 12)} {'rând' if std <= 12 else 'rânduri'}), cu ușă, IP40 (IP65 la exterior)",
                    f"ocupat {mod} module + rezervă ≥ 20 %; borne N și PE, etichete circuite; SR EN 61439-3"], "cantitate": 1, "um": "buc", "tip": "aux"})
        out.append({"ref": car.get("titlu", "TE"), "lista": [f"Pieptene de conexiuni Cu {'1P+N' if mono else '3P+N'}, {max(63, (rz.get('Q_general') or {}).get('In_A') or 0)} A, cu capace de capăt",
                    "alimentarea DDR-urilor și a circuitelor din aceeași grupă"], "cantitate": 1, "um": "set", "tip": "aux"})
    elif In_b and car:
        mono = rz.get("retea") == "mono" or inp.get("retea") == "mono"
        out.append({"ref": car.get("titlu", ""), "lista": [f"Sistem de bare Cu {'L + N + PE' if mono else '3P + N + PE'}, In ≥ {In_b}{NB}A",
                    (f"Icw ≥ {fmt_ro(ik, 1)} kA / 1 s, " if ik else "") + "suporți izolatori, SR EN 61439-1/-2"], "cantitate": 1, "um": "set", "tip": "aux"})
    if car and tip in ("tablou", "cef", "ge_ats"):
        out.append({"ref": car.get("titlu", ""), "lista": [f"Carcasă tablou {car.get('titlu', '')}, metalică, IP54, IK08, uși cu cheie",
                    "plăci de montaj, șine DIN, borne, etichete, schemă în buzunar; SR EN 61439-2"], "cantitate": 1, "um": "buc", "tip": "aux"})
    elif car and tip == "pt":
        out.append({"ref": car.get("titlu", ""), "lista": ["Anvelopă post de transformare (beton sau metalică), cu fundație, ventilație și iluminat",
                    "dimensionată pentru celule MT + trafo + TGJT, conform proiect de specialitate"], "cantitate": 1, "um": "buc", "tip": "aux"})
    def sec(b):        # tablouri secundare (plecări cu circuite în cascadă): carcasă + bare proprii
        if b.get("copii") and b.get("grup"):      # grupă DDR în același tablou: fără carcasă proprie
            for c in b["copii"]:
                sec(c)
        elif b.get("copii"):
            t = (b.get("sarcina") or {}).get("titlu") or "TD"
            In = next(((a.get("param") or {}).get("In_A") for a in b.get("aparate") or [] if (a.get("param") or {}).get("In_A")), None)
            out.append({"ref": t, "lista": [f"Carcasă tablou {t}, metalică, IP54, IK08, uși cu cheie",
                        "plăci de montaj, șine DIN, borne, etichete; SR EN 61439-3"], "cantitate": 1, "um": "buc", "tip": "aux"})
            if In:
                out.append({"ref": t, "lista": [f"Sistem de bare / repartitor Cu 3P + N + PE, In ≥ {In}{NB}A", "SR EN 61439"],
                            "cantitate": 1, "um": "set", "tip": "aux"})
            for c in b["copii"]:
                sec(c)
    for b in model.get("plecari") or []:
        sec(b)
    ncab = sum(1 for x in model.get("materiale") or [] if (x.get("lista") or [""])[0].startswith("Cablu"))
    if ncab:
        capete = 0
        def nc(b):
            nonlocal capete
            for key in ("cablu", "cablu_ca"):
                par = (b.get(key) or {}).get("param") or {}
                if par.get("S_faza_mm2"):
                    capete += 2 * int(par.get("n_paralel") or 1) * int(par.get("buc_circuite") or 1)
            for c in b.get("copii") or []:
                nc(c)
        for b in (model.get("intrari") or []) + ([] if tip == "locuinta" else (model.get("plecari") or [])):     # casă: doar coloana are papuci
            nc(b)
        if capete:
            out.append({"ref": "cabluri", "lista": ["Set accesorii capăt de cablu: papuci de cablu, presetupă, tub termocontractabil, etichetă",
                        "dimensionat după secțiunea fiecărui cablu"], "cantitate": capete, "um": "set", "tip": "aux"})
    pr = rz.get("priza") or {}
    for mt in pr.get("materiale") or []:
        if "piesă de separație" in (mt.get("denumire") or "").lower():
            continue          # piesa de separație e deja poziția BN · PS · PPL de pe planșă
        out.append({"ref": "PP", "lista": [mt.get("denumire", ""), f"priză de pământ calculată, Rp = {fmt_ro(pr.get('Rp_ohm'), 2)} Ω"],
                    "cantitate": mt.get("cantitate"), "um": mt.get("um", "buc"), "tip": "aux"})
    return out


# ------------------------------------------------------------------------------------------------ note
NOTE_FIXE = [
    "Schemă electrică monofilară de principiu, fază {faza}. Dimensionare conform I7-2011, SR HD 60364-4-41, -4-43, -5-52 (2011), -5-54, "
    "SR EN 60909-0; branșament conform ST 4-JT / ST 3-JT (DEER).",
    "Nu fac obiectul prezentei planșe: {exclus}{pp}analiza de risc la trăsnet.",
    "{spl}",
    "Secțiunile cablurilor sunt dimensionate la Iz' = Iz·kθ·kgrup·ksol (SR HD 60364-5-52 tab. B.52.x), la ΔU (I7-2011) și la stabilitatea "
    "termică; reglajele protecțiilor sunt cele înscrise pe planșă.",
]


def cheie_confirmare(v):
    return f"{v.get('cod')}|{v.get('obiect')}"


def _note(inp, r, cartus, confirmari=()):
    spl = inp.get("schema_pamant") or "TN-C-S"
    if inp.get("tip_schema") == "bransament":
        spl_t = f"{spl} cu separarea PEN pe BN în bloc. Rp ≤ 4 Ω" if spl != "TT" else f"TT, RA = {inp.get('RA_ohm', '—')} Ω"
    elif inp.get("tip_schema") in ("pt",) or (inp.get("tip_schema") == "cef" and inp.get("pt_Sn_kVA")):
        spl_t = "TN-S din PT propriu. Rp ≤ 1 Ω, conform calcul"
    else:
        spl_t = "TN-S în aval de separarea PEN. Rp ≤ 4 Ω"
    atr = f" nr. {cartus.get('atr')}" if cartus.get("atr") else ""
    tip = inp.get("tip_schema")
    if tip == "pt" or (tip == "cef" and inp.get("pt_Sn_kVA")):
        exclus = f"racordul MT al OD conform ATR{atr}; legătura trafo–TGJT (conform furnizorului postului); "
    elif tip == "ge_ats":
        exclus = f"alimentarea existentă din amonte de QR; "
    elif tip == "tablou" and inp.get("origine") == "pt_propriu":
        exclus = "postul de transformare (amonte de C1); "
    elif tip == "prosumator":
        exclus = f"branșamentul existent și contorul OD{atr and ' (ATR' + atr + ')'}; "
    elif tip == "cef":
        exclus = f"instalația din amonte de punctul de racord (rețea OD / tablou existent), conform ATR{atr}; "
    else:
        exclus = f"racordul OD (C1) conform ATR{atr}; "
    nspl = (r.get("rezultat") or {}).get("nota_schema_pamant")
    spl_full = nspl if nspl else f"Schemă de legare la pământ: {spl_t}."
    pr = (r.get("rezultat") or {}).get("priza") or {}
    note = [t.format(faza=cartus.get("faza") or "PT", exclus=exclus, spl=spl_full,
                     pp="" if pr.get("nota") else "priza de pământ (calcul separat); ") for t in NOTE_FIXE]
    if pr.get("nota"):
        note.append(pr["nota"])
    try:
        note += [n.replace("celula trafo intreruptor", "celulă de transformator cu întreruptor în vid și releu 50/51, 50N/51N")
                  .replace("celula trafo sigurante", "celulă de transformator cu separator de sarcină și siguranțe MT")
                 for n in note_generate(r["rezultat"])]
    except Exception:
        pass
    ip = r.get("ipoteze") or []
    if ip:
        note.append("Ipoteze de calcul: " + "; ".join(ip) + ".")
    conf = set(confirmari or ())
    av = [v for v in r.get("verificari") or [] if v.get("nivel") == "AVERTISMENT" and cheie_confirmare(v) not in conf]
    if av:
        coduri = {}
        for v in av:
            coduri.setdefault(v["cod"], []).append(v.get("obiect", ""))
        def _ob(o):
            u = sorted(set(o))
            return ", ".join(u[:4]) + (f" și încă {len(u) - 4}" if len(u) > 4 else "")
        note.append("Atenționări de verificat (detalii în memoriul de calcul): " + "; ".join(f"{c} ({_ob(o)})" for c, o in coduri.items()) + ".")
    return [f"{i + 1}. {n}" for i, n in enumerate(note)]


# ------------------------------------------------------------------------------------------------ API
def rezumat(r):
    return {"blocheaza": r.get("blocheaza_export", False), "verificari": r.get("verificari", []), "info": r.get("info", []),
            "presupus": r.get("presupus", []), "ipoteze": r.get("ipoteze", [])}


def genereaza(intrare, cartus=None, format_="A3", pastreaza=None):
    """intrare fizică → (model grafic, rezultat calcul). `pastreaza` = model vechi din care se păstrează cartușul și setările planșei."""
    r = calculeaza(intrare)
    from .presets import CARTUS_CEP
    m = {"format": format_, "cartus": dict(CARTUS_CEP), "auto_format": True, "lista_auto": True, "legenda": True}
    if pastreaza:
        for k in ("format", "auto_format", "lista_auto", "legenda", "deviz"):
            if k in pastreaza:
                m[k] = copy.deepcopy(pastreaza[k])
        m["cartus"].update({k: v for k, v in (pastreaza.get("cartus") or {}).items() if v not in (None, "")})
    if cartus:
        m["cartus"].update({k: v for k, v in cartus.items() if v not in (None, "")})
    m["calc"] = copy.deepcopy(intrare)
    tip = intrare.get("tip_schema")
    rz = r.get("rezultat") or {}
    if tip in CONSTRUCTORI and rz and not (r.get("blocheaza_export") and not _are_structura(tip, rz)):
        try:
            CONSTRUCTORI[tip](intrare, rz, m)
        except Exception as e:      # nu blocăm aplicația: schema rămâne goală, validatorul raportează
            m.update({"intrari": [], "plecari": [], "bara": {"afisare": False}})
            r.setdefault("verificari", []).append({"cod": "V00", "nivel": "BLOCANT", "obiect": "schema",
                                                    "mesaj": f"schema nu a putut fi desenată din rezultat ({e.__class__.__name__}: {e})",
                                                    "remediere": "verificați datele de intrare"})
            r["blocheaza_export"] = True
    else:
        m.update({"intrari": [], "plecari": [], "bara": {"afisare": False}, "carcasa": None})
    conf = list((pastreaza or {}).get("confirmari") or [])
    if conf:
        m["confirmari"] = conf
        for v in r.get("verificari") or []:          # avertismentele analizate de proiectant: marcate, scoase din nota de pe planșă
            if v.get("nivel") == "AVERTISMENT" and cheie_confirmare(v) in conf:
                v["confirmat"] = True
    m["note"] = _note(intrare, r, m["cartus"], conf)
    pr = rz.get("priza") or {}
    if pr.get("Rp_ohm") is not None:          # textul de sub priza de pământ = valoarea calculată
        m["rp"] = f"Rp = {fmt_ro(pr['Rp_ohm'], 2)} Ω {'≤' if pr.get('ok') else '>'} {fmt_ro(pr.get('R_limita_ohm'), 2)} Ω"
    m["materiale"] = materiale_cabluri(m)
    if m.get("intrari") or m.get("plecari"):
        m["materiale"] += materiale_aparataj(m, intrare, rz)
    regenereaza_texte(m)
    m["calc_rezumat"] = rezumat(r)
    return m, r


def _are_structura(tip, rz):
    """dacă rezultatul blocat conține totuși destule date ca schema să fie desenată (pentru vizualizarea problemei)"""
    if tip == "bransament":
        return bool(rz.get("C2") and rz.get("Q"))
    if tip in ("tablou",):
        return bool(rz.get("plecari") is not None and rz.get("Q1_C1", {}).get("protectie"))
    if tip == "pt":
        return bool(rz.get("trafo"))
    if tip == "cef":
        return bool(rz.get("invertoare"))
    if tip == "prosumator":
        return bool(rz.get("INV"))
    if tip == "ge_ats":
        return bool(rz.get("Q_G"))
    if tip == "locuinta":
        return bool(rz.get("coloana") and rz.get("grupe_DDR") is not None)
    return False

engine/render_dxf.py:
"""Randare Canvas -> DXF R2018 (AutoCAD 2018-2025), simboluri ca blocuri cu atribute.

Numele blocului depinde de geometria efectivă a simbolului: două inserări cu geometrie diferită
(de ex. MCCB cu / fără bobină BD, `cutie` de dimensiuni diferite) nu partajează niciodată un bloc.
Prima variantă păstrează numele de bază (`SYM_MCCB`, `SYM_MCCB_BD` …), următoarele primesc un sufix
scurt derivat din geometrie (`SYM_CUTIE_3F9A1C`)."""
import hashlib
# ezdxf se importă la prima randare DXF (în versiunea web se încarcă doar când e nevoie de export)
ezdxf = units = TA = None
ALIGN = {}


def _ezdxf():
    global ezdxf, units, TA, ALIGN
    if ezdxf is None:
        import ezdxf as _e
        from ezdxf import units as _u
        from ezdxf.enums import TextEntityAlignment as _ta
        ezdxf, units, TA = _e, _u, _ta
        ALIGN.update({"left": TA.LEFT, "middle": TA.CENTER, "right": TA.RIGHT})
from .canvas import *



def _emit(space, items, dx=0.0, dy=0.0, k=1.0, reg=None):
    def P(p): return (p[0] * k + dx, p[1] * k + dy)
    for it in items:
        if isinstance(it, Line):
            space.add_line(P(it.a), P(it.b), dxfattribs={"layer": it.layer})
        elif isinstance(it, Polyline):
            space.add_lwpolyline([P(p) for p in it.pts], close=it.closed, dxfattribs={"layer": it.layer})
        elif isinstance(it, Rect):
            x, y = it.p
            space.add_lwpolyline([P((x, y)), P((x + it.w, y)), P((x + it.w, y + it.h)), P((x, y + it.h))], close=True, dxfattribs={"layer": it.layer})
        elif isinstance(it, Circle):
            if it.layer == "HASURA":
                h = space.add_hatch(color=7, dxfattribs={"layer": "HASURA"})
                h.paths.add_edge_path().add_ellipse(P(it.c), major_axis=(it.r * k, 0), ratio=1)
            else:
                space.add_circle(P(it.c), it.r * k, dxfattribs={"layer": it.layer})
        elif isinstance(it, Ellipse):
            space.add_ellipse(P(it.c), major_axis=(it.rx * k, 0), ratio=it.ry / it.rx, dxfattribs={"layer": it.layer})
        elif isinstance(it, Solid):
            space.add_solid([P(p) for p in it.pts], dxfattribs={"layer": it.layer, "color": LAYERS[it.layer][0]})
        elif isinstance(it, Text):
            st = "ARIAL_B" if it.bold else ("ARIAL_I" if it.italic else "ARIAL")
            t = space.add_text(it.s, dxfattribs={"layer": it.layer, "style": st, "height": it.h * k, "rotation": it.rot or 0.0})
            t.set_placement(P(it.p), align=ALIGN[it.align])
        elif isinstance(it, BlockRef):
            _insert_block(space, it, dx, dy, k, reg if reg is not None else {})


def _semnatura(prims):
    """amprenta geometriei unui simbol (fără texte, care se emit separat)"""
    def r(v): return round(float(v), 3)
    parts = []
    for p in prims:
        if isinstance(p, Text): continue
        if isinstance(p, Line): parts.append(("L", p.layer, r(p.a[0]), r(p.a[1]), r(p.b[0]), r(p.b[1])))
        elif isinstance(p, (Polyline, Solid)): parts.append((type(p).__name__, p.layer, getattr(p, "closed", True), tuple((r(x), r(y)) for x, y in p.pts)))
        elif isinstance(p, Rect): parts.append(("R", p.layer, r(p.p[0]), r(p.p[1]), r(p.w), r(p.h)))
        elif isinstance(p, Circle): parts.append(("C", p.layer, r(p.c[0]), r(p.c[1]), r(p.r)))
        elif isinstance(p, Ellipse): parts.append(("E", p.layer, r(p.c[0]), r(p.c[1]), r(p.rx), r(p.ry)))
    return hashlib.sha1(repr(parts).encode()).hexdigest()[:6].upper()


def _nume_bloc(doc, br, reg):
    sig = _semnatura(br.prims)
    name = br.name
    if reg.get(name, sig) != sig:          # numele de bază e luat de altă geometrie
        name = f"{br.name}_{sig}"
    if name not in reg:
        reg[name] = sig
        blk = doc.blocks.new(name=name)
        _emit(blk, [p for p in br.prims if not isinstance(p, Text)])
        for i, tag in enumerate(br.attribs):
            a = blk.add_attdef(tag, (0, -8 - 3.5 * i), dxfattribs={"height": 2.3, "style": "ARIAL", "layer": "TEXT", "invisible": 1})
            a.dxf.prompt = tag
    return name


def _insert_block(space, br: BlockRef, dx, dy, k, reg):
    doc = space.doc
    name = _nume_bloc(doc, br, reg)
    kk = k * br.scale
    pos = (br.p[0] * k + dx, br.p[1] * k + dy)
    ins = space.add_blockref(name, pos, dxfattribs={"layer": br.layer, "xscale": kk, "yscale": kk})
    # atribute: valorile reale; textele vizibile ale simbolului se emit ca TEXT normal, lângă bloc
    for i, (tag, val) in enumerate(br.attribs.items()):
        ins.add_attrib(tag, str(val), insert=(pos[0], pos[1] - (8 + 3.5 * i) * kk), dxfattribs={"invisible": 1, "height": 2.3 * kk, "layer": "TEXT"})
    _emit(space, [p for p in br.prims if isinstance(p, Text)], pos[0], pos[1], kk)


def render(c: Canvas, path: str, layout_name="A3"):
    _ezdxf()
    doc = ezdxf.new("R2018", setup=True)
    doc.units = units.MM
    doc.header["$INSUNITS"] = 4
    doc.header["$LTSCALE"] = 1.0
    doc.header["$PSLTSCALE"] = 0
    for name, (aci, lw, lt, _) in LAYERS.items():
        l = doc.layers.add(name, color=aci)
        l.dxf.lineweight = lw
        l.dxf.linetype = lt
    doc.styles.add("ARIAL", font="arial.ttf")
    doc.styles.add("ARIAL_B", font="arialbd.ttf")
    doc.styles.add("ARIAL_I", font="ariali.ttf")
    msp = doc.modelspace()
    _emit(msp, c.items, reg={})
    lay = doc.layouts.get("Layout1")
    lay.page_setup(size=(c.w, c.h), margins=(0, 0, 0, 0), units="mm", scale=1)
    lay.add_viewport(center=(c.w/2, c.h/2), size=(c.w, c.h), view_center_point=(c.w/2, c.h/2), view_height=c.h)
    doc.set_modelspace_vport(height=c.h*1.08, center=(c.w/2, c.h/2))
    doc.saveas(path)
    return path

engine/render_svg.py:
"""Randare Canvas -> SVG (mm, A3/A2 landscape)."""
from .canvas import *
import html

LW_SVG = {18: 0.18, 25: 0.25, 35: 0.35, 50: 0.5, 70: 0.7}

def _style(layer):
    aci, lw, lt, col = LAYERS[layer]
    s = f'stroke="{col}" stroke-width="{LW_SVG.get(lw, 0.35)}" fill="none"'
    d = DASH_SVG.get(lt)
    if d: s += f' stroke-dasharray="{d}"'
    return s

def render(c: Canvas, title="Schema") -> str:
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{c.w}mm" height="{c.h}mm" viewBox="0 0 {c.w} {c.h}">',
           f'<title>{html.escape(title)}</title>',
           '<style>text{font-family:Arial,Helvetica,sans-serif}</style>',
           f'<rect x="0" y="0" width="{c.w}" height="{c.h}" fill="#fff"/>']

    def emit(items, dx=0.0, dy=0.0, k=1.0):
        def P(p): return p[0] * k + dx, c.h - (p[1] * k + dy)   # local -> SVG (y în jos)
        for it in items:
            if isinstance(it, Line):
                (x1, y1), (x2, y2) = P(it.a), P(it.b)
                out.append(f'<line x1="{x1:.3f}" y1="{y1:.3f}" x2="{x2:.3f}" y2="{y2:.3f}" {_style(it.layer)} stroke-linecap="round"/>')
            elif isinstance(it, Polyline):
                pts = " ".join("%.3f,%.3f" % P(p) for p in it.pts)
                tag = "polygon" if it.closed else "polyline"
                out.append(f'<{tag} points="{pts}" {_style(it.layer)} stroke-linejoin="round"/>')
            elif isinstance(it, Rect):
                x, y = P((it.p[0], it.p[1] + it.h))
                fill = f'fill="{it.fill}"' if it.fill else 'fill="none"'
                st = _style(it.layer).replace('fill="none"', fill)
                out.append(f'<rect x="{x:.3f}" y="{y:.3f}" width="{it.w*k:.3f}" height="{it.h*k:.3f}" {st}/>')
            elif isinstance(it, Circle):
                x, y = P(it.c)
                if it.layer == "HASURA":
                    out.append(f'<circle cx="{x:.3f}" cy="{y:.3f}" r="{it.r*k:.3f}" fill="#000"/>')
                else:
                    out.append(f'<circle cx="{x:.3f}" cy="{y:.3f}" r="{it.r*k:.3f}" {_style(it.layer)}/>')
            elif isinstance(it, Ellipse):
                x, y = P(it.c)
                out.append(f'<ellipse cx="{x:.3f}" cy="{y:.3f}" rx="{it.rx*k:.3f}" ry="{it.ry*k:.3f}" {_style(it.layer)}/>')
            elif isinstance(it, Solid):
                col = LAYERS[it.layer][3]
                pts = " ".join("%.3f,%.3f" % P(p) for p in it.pts)
                out.append(f'<polygon points="{pts}" fill="{col}" stroke="none"/>')
            elif isinstance(it, Text):
                x, y = P(it.p)
                col = LAYERS[it.layer][3]
                anchor = {"left": "start", "middle": "middle", "right": "end"}[it.align]
                fs = it.h * k / 0.72   # înălțimea AutoCAD = înălțimea majusculei ≈ 0,72 em
                st = f'font-size="{fs:.2f}" fill="{col}" text-anchor="{anchor}"'
                if it.bold: st += ' font-weight="bold"'
                if it.italic: st += ' font-style="italic"'
                if it.rot: st += f' transform="rotate({-it.rot:g} {x:.3f} {y:.3f})"'
                out.append(f'<text x="{x:.3f}" y="{y:.3f}" {st}>{html.escape(str(it.s or ""))}</text>')
            elif isinstance(it, BlockRef):
                kk = k * it.scale; ox, oy = it.p[0] * k + dx, it.p[1] * k + dy
                if it.uid:
                    out.append(f'<g class="sym" data-uid="{html.escape(it.uid)}">')
                    emit(it.prims, ox, oy, kk); out.append('</g>')
                else:
                    emit(it.prims, ox, oy, kk)
    emit(c.items)
    out.append('</svg>')
    return "\n".join(out)

engine/topologie.py:
"""Verificări de topologie ale DESENULUI (SPEC D: V57, V82, V83).

`verifica_topologie(model, canvas)` lucrează pe ce s-a desenat efectiv: casetele carcaselor, ale surselor și ale
tablourilor secundare, legăturile de măsură / tensiune / comandă și vârfurile săgeților, pe care motorul de layout
le pune în `canvas.meta`. Fiecare rezultat are forma `{cod, nivel, obiect, mesaj, remediere}` (SPEC D).
"""
from .canvas import Solid, bbox_overlap


def _r(cod, nivel, obiect, mesaj, remediere=""):
    return {"cod": cod, "nivel": nivel, "obiect": obiect, "mesaj": mesaj, "remediere": remediere}


def _aparate(model):
    def walk(bs):
        for b in bs or []:
            for a in b.get("aparate", []) or []: yield a
            yield from walk(b.get("copii"))
    yield from walk(model.get("intrari"))
    yield from walk(model.get("plecari"))


def _v57(model, meta):
    out = []
    # în model: siguranța circuitului de tensiune forțată în lanțul de curent al unui TC
    for a in _aparate(model):
        if a.get("tip") != "tc": continue
        for l in a.get("laterale", []) or []:
            if l.get("tip") == "fuzibil" and l.get("intrare_contor") == "curent":
                out.append(_r("V57", "BLOCANT", a.get("ref") or "TC",
                              f"{l.get('ref') or 'F'} (tensiune contor) legat în circuitul secundar al {a.get('ref') or 'TC'}",
                              "derivație din bare, în amonte de TC: \"intrare_contor\": \"tensiune\""))
    # pe desen: o siguranță pe un traseu de măsură care pleacă din secundarul unui TC
    for l in meta.get("legaturi", []):
        if l.get("tip") == "masura" and l.get("aparat_tip") == "tc" and l.get("lateral") == "fuzibil":
            msg = f"{l.get('spre') or 'F'} (tensiune contor) legat în circuitul secundar al {l.get('de') or 'TC'}"
            if not any(r["mesaj"] == msg for r in out):
                out.append(_r("V57", "BLOCANT", l.get("de") or "TC", msg, "derivație din bare, în amonte de TC"))
    return out


def _v82(meta):
    out = []
    for o in meta.get("obiecte", []):
        if o.get("tip") not in ("sursa", "tablou"): continue
        for car in meta.get("carcase", []):
            if car.get("nume") == o.get("nume"): continue
            if o["bbox"] and bbox_overlap(o["bbox"], car["bbox"], 0.0):
                cine = "sursa" if o["tip"] == "sursa" else "tabloul"
                out.append(_r("V82", "BLOCANT", o.get("nume") or o["tip"],
                              f"{cine} {o.get('nume')} desenat(ă) în interiorul {car.get('nume')}",
                              "sursele și tablourile secundare se desenează în afara carcasei tabloului părinte"))
    return out


def _sageata_spre(c, tip_pt):
    """direcția (dx, dy) a săgeții care are vârful în `tip_pt`, sau None"""
    for it in c.items:
        if isinstance(it, Solid) and it.layer == "COMANDA" and len(it.pts) == 3:
            (tx, ty) = it.pts[0]
            if abs(tx - tip_pt[0]) < 0.05 and abs(ty - tip_pt[1]) < 0.05:
                bx = (it.pts[1][0] + it.pts[2][0]) / 2; by = (it.pts[1][1] + it.pts[2][1]) / 2
                return (tx - bx, ty - by)
    return None


def _v83(c, meta):
    out = []
    for l in meta.get("legaturi", []):
        if l.get("tip") != "comanda": continue
        de, spre = l.get("de_xy"), l.get("spre_xy")
        d = _sageata_spre(c, l.get("sageata") or spre)
        ok = False
        if d and de and spre:
            # săgeata trebuie să aibă vârful la aparatul comandat și să fie orientată de la protecție spre aparat
            v = (spre[0] - de[0], spre[1] - de[1])
            at_tgt = abs(l["sageata"][0] - spre[0]) < 0.05 and abs(l["sageata"][1] - spre[1]) < 0.05
            ok = at_tgt and (d[0] * v[0] + d[1] * v[1]) > 0
        if not ok:
            out.append(_r("V83", "BLOCANT", f"{l.get('de')}→{l.get('spre')}",
                          f"săgeata {l.get('de')}→{l.get('spre')} inversată (sau lipsă)",
                          "săgeata pleacă de la protecție (DPST / PI / releu) și intră în bobina BD a aparatului comandat"))
    return out


def verifica_topologie(model: dict, canvas) -> list:
    """V57 (circuit de tensiune în serie cu TC), V82 (sursă / tablou desenat în carcasa altui tablou),
    V83 (legătură de comandă inversată). Întoarce lista de rezultate {cod, nivel, obiect, mesaj, remediere}."""
    meta = getattr(canvas, "meta", None) or {}
    return _v57(model, meta) + _v82(meta) + _v83(canvas, meta)


# ---------------------------------------------------------------- coliziuni de text (P2-1)
from .canvas import (Text, BlockRef, Line, Circle, iter_texts, item_segments, seg_hits_box, block_bbox, prim_bbox)

LINII_TEXT = ("CARTUS", "TABEL", "CARCASA", "CHENAR")                       # liniile pe care un text nu are voie să le taie
LINII_POZ = ("FORTA", "MASURA", "COMANDA", "MECANIC", "PE", "CARCASA")


def coliziuni(c, tol=0.25):
    """suprapunerile de pe planșă (casete estimate din lungime × înălțime × rotație):
    text–text, text peste liniile cartușului / tabelului / carcaselor, cerc de poziție peste simboluri, săgeți,
    linii de legătură sau alte texte, conductor PE prin caseta unui consumator. Întoarce o listă de șiruri."""
    meta = getattr(c, "meta", None) or {}
    out = []
    texts = [(t, b) for t, b in iter_texts(c.items) if t.s.strip()]
    for i in range(len(texts)):
        ti, bi = texts[i]
        for j in range(i + 1, len(texts)):
            tj, bj = texts[j]
            if bbox_overlap(bi, bj, tol):
                out.append(f"text „{ti.s}” peste „{tj.s}”")
    segs = [(a, b, it.layer) for it in c.items if getattr(it, "layer", "") in LINII_TEXT for a, b in item_segments(it)]
    for t, bb in texts:
        for a, b, lay in segs:
            if seg_hits_box(a, b, bb, tol):
                out.append(f"text „{t.s}” taie o linie {lay}"); break
    # cercuri de poziție
    sym = [block_bbox(it) for it in c.items if isinstance(it, BlockRef)]
    sol = [prim_bbox(it) for it in c.items if isinstance(it, Solid)]
    lin = [(a, b) for it in c.items if getattr(it, "layer", "") in LINII_POZ and not isinstance(it, Circle) for a, b in item_segments(it)]
    pozs = meta.get("poz", [])
    for k, ((x, y), r) in enumerate(pozs):
        bb = (x - r, y - r, x + r, y + r)
        if any(s and bbox_overlap(bb, s, tol) for s in sym): out.append(f"poziția de la ({x:.0f}, {y:.0f}) peste un simbol")
        if any(s and bbox_overlap(bb, s, tol) for s in sol): out.append(f"poziția de la ({x:.0f}, {y:.0f}) peste o săgeată")
        if any(seg_hits_box(a, b, bb, tol) for a, b in lin): out.append(f"poziția de la ({x:.0f}, {y:.0f}) peste o linie")
        for t, tb in texts:
            if bb[0] <= t.p[0] <= bb[2] and bb[1] <= t.p[1] <= bb[3]: continue      # numărul propriu
            if bbox_overlap(bb, tb, tol): out.append(f"poziția de la ({x:.0f}, {y:.0f}) peste textul „{t.s}”")
        for (x2, y2), r2 in pozs[k + 1:]:
            if (x - x2) ** 2 + (y - y2) ** 2 < (r + r2 - tol) ** 2: out.append(f"pozițiile de la ({x:.0f}, {y:.0f}) și ({x2:.0f}, {y2:.0f}) se suprapun")
    # PE prin caseta unui consumator / tablou
    pe = [(a, b) for it in c.items if getattr(it, "layer", "") == "PE" for a, b in item_segments(it)]
    for o in meta.get("obiecte", []):
        if o.get("tip") == "tablou" and any(seg_hits_box(a, b, o["bbox"], tol) for a, b in pe):
            out.append(f"conductorul PE trece prin caseta {o.get('nume')}")
    return out

engine/validare.py:
"""Validarea modelului înainte de previzualizare / export (SPEC §D: BLOCANT = exportul este refuzat).

Două moduri:
* model CALCULAT (`model["calc"]` = intrarea fizică): desenul, textele, lista de echipamente și notele generate se reconstruiesc
  ÎNTOTDEAUNA din calcul (`pregateste`), deci nu pot contrazice dimensionarea. Se păstrează doar cartușul, formatul planșei
  și notele suplimentare scrise de utilizator (`note_manuale`).
* model MANUAL (fără `calc`): se desenează așa cum e, dar dimensionarea nu e verificată → AVERTISMENT V00 și o notă pe
  planșă („schemă nevalidată”). Topologia (V57/V82/V83) se verifică în ambele moduri.
"""
import copy, re

from . import constructor, layout, topologie
from .calc import calculeaza

NOTA_MANUAL = ("ATENȚIE: schemă desenată manual — dimensionarea cablurilor, reglajele protecțiilor, scurtcircuitul și "
               "selectivitatea NU au fost verificate de aplicație.")
CHEI_PLANSA = ("format", "auto_format", "lista_auto", "legenda", "titlu_lista", "abrevieri", "note_manuale", "deviz", "confirmari", "_doc")


def _fara_interne(o):
    if isinstance(o, dict):
        return {k: _fara_interne(v) for k, v in o.items() if not k.startswith("_")}
    if isinstance(o, list):
        return [_fara_interne(v) for v in o]
    return o


def _copiaza_uid(src, dst):
    """modelul regenerat din calcul are aceeași structură ca cel din interfață → se preiau cheile _uid/_k pe poziție
    (legătura planșă ↔ formular din interfață)"""
    if isinstance(src, dict) and isinstance(dst, dict):
        for k in ("_uid", "_k"):
            if k in src and k not in dst:
                dst[k] = src[k]
        for k, v in dst.items():
            if k in src and not k.startswith("_"):
                _copiaza_uid(src[k], v)
    elif isinstance(src, list) and isinstance(dst, list):
        for a, b in zip(src, dst):
            _copiaza_uid(a, b)


def pregateste(model, pentru_export=False):
    """modelul gata de desenat + rezultatul calculului (sau None pentru modelele manuale)"""
    if model.get("calc"):
        m, r = constructor.genereaza(model["calc"], pastreaza=model)
        for k in CHEI_PLANSA:
            if k in model:
                m[k] = copy.deepcopy(model[k])
        if not pentru_export:
            _copiaza_uid(model, m)
        if model.get("note_manuale"):
            n0 = len(m.get("note") or [])
            m["note"] = (m.get("note") or []) + [f"{n0 + i + 1}. {t}" for i, t in enumerate(model["note_manuale"])]
        return (_fara_interne(m) if pentru_export else m), r
    m = copy.deepcopy(model)
    if pentru_export:
        m = _fara_interne(m)
        note = list(m.get("note") or [])
        if NOTA_MANUAL not in note:
            m["note"] = [NOTA_MANUAL] + note
    return m, None


_NR_A = re.compile(r"(\d+(?:[.,]\d+)?)\s*(?:\u00a0)?A\b")


def _numere_A(texte):
    return {float(x.replace(",", ".")) for t in texte for x in _NR_A.findall(t or "")}


_PROT_SABLON = {"mcb": "MCB", "mccb": "MCCB", "acb": "ACB", "sep_sig": "gG", "sf": "gG", "rcbo": "MCB"}


_TIP_PROT = {"mcb": "mcb", "mccb": "mccb", "acb": "acb", "sep_fuzibil": "sep_sig", "fuzibil": "sep_sig", "rcbo": "rcbo", "mccb_dif": "mccb"}


def _n(t):
    return " ".join(str(t or "").replace("\u00a0", " ").replace("\u202f", " ").split())


def _cablu_din_text(t):
    """„ACYABY 4×16 mm²”, „2 × (CYABY 5×95 mm² …)”, „4 x 16 mmp Al”, „N2XY 4×1×16” → parametri pentru verifica_cablu
    (None dacă secțiunea nu se poate citi). Izolația și pozarea se deduc din denumire: 2X / XLPE → XLPE, altfel PVC;
    cablu armat (…ABY / …A2Y) → îngropat (D1), altfel pe perete (C). Aluminiu: denumirea începe cu A sau textul spune „Al”."""
    t = _n(t).replace("mmp", "mm²").replace(" x ", "×").replace("x", "×")
    n = 1
    mp = re.match(r"^\s*(\d+)\s*×\s*\(", t)
    if mp:
        n = int(mp.group(1))
    tip = (re.search(r"\b([A-Z][A-Z0-9-]{2,})\b", t) or [None, ""])[1] if re.search(r"\b([A-Z][A-Z0-9-]{2,})\b", t) else ""
    ms = re.search(r"(\d)\s*×\s*(?:1\s*×\s*)?(\d+(?:[.,]\d+)?)", t) or re.search(r"(\d+(?:[.,]\d+)?)\s*mm²", t)
    if not ms:
        return None
    S = float((ms.group(2) if ms.lastindex == 2 else ms.group(1)).replace(",", "."))
    al = (tip.startswith("A") and not tip.startswith("AF")) or bool(re.search(r"\bAl\b", t))
    xlpe = "2X" in tip or "XLPE" in t.upper()
    armat = tip.endswith("ABY") or tip.endswith("A2Y") or "ABY" in tip
    nc = int(ms.group(1)) if ms.lastindex == 2 else 4
    return {"material": "Al" if al else "Cu", "izolatie": "XLPE" if xlpe else "PVC", "metoda": "D1" if armat else "C",
            "S_faza_mm2": S, "n_paralel": n, "retea": "mono" if nc in (2, 3) and S < 16 else "tri"}


def _consistenta_manual(m):
    """model desenat manual: ce scrie pe desen trebuie să coincidă cu lista de echipamente (V80) și, unde există
    parametri fizici, cu textele generate din ei; protecția nu poate depăși Iz' al cablului cu parametri (V02)"""
    from .calc import text_lista, text_desen
    from .calc import verifica_cablu
    out = []
    prot_curenta = [None]
    def r_(cod, ob, mesaj, rem):
        out.append({"cod": cod, "nivel": "BLOCANT", "obiect": ob, "mesaj": mesaj, "remediere": rem})
    def br(b, cale):
        cab = (b.get("cablu") or {}).get("param") or {}
        for key in ("cablu", "cablu_ca"):
            cb = b.get(key) or {}
            cp = cb.get("param") or {}
            if cp.get("S_faza_mm2"):
                from .calc.texte import text_cablu
                t = text_cablu(cp.get("material"), cp.get("izolatie"), cp.get("metoda"), cp.get("n_paralel") or 1, cp.get("S_faza_mm2"),
                               cp.get("S_N_mm2"), cp.get("S_PE_mm2"), cp.get("PE") or "cablu", cp.get("retea", "tri"))
                if _n(t) not in _n(cb.get("text") or ""):
                    r_("V80", cb.get("ref") or cale, f"{cb.get('ref') or 'cablu'}: textul de pe desen „{cb.get('text')}” ≠ cablul dimensionat „{t}”",
                       "corectați cablul din tab-ul Calcul")
        for a in b.get("aparate") or []:
            ref = a.get("ref") or a.get("tip", "")
            par = a.get("param") or {}
            if par.get("sablon"):
                p = {k: v for k, v in par.items() if k != "sablon"}
                try:
                    den, _ = text_lista(par["sablon"], p)
                    if _n((a.get("lista") or [""])[0]) != _n(den):
                        r_("V80", ref, f"{ref}: lista „{(a.get('lista') or [''])[0]}” ≠ parametri „{den}”", "regenerați lista din parametri")
                    if par["sablon"] not in ("contor", "dpst") and [_n(x) for x in a.get("spec") or []] != [_n(x) for x in text_desen(par["sablon"], p)]:
                        r_("V80", ref, f"{ref}: desenul „{' · '.join(a.get('spec') or [])}” ≠ parametri „{' · '.join(text_desen(par['sablon'], p))}”",
                           "corectați aparatul din tab-ul Calcul")
                except Exception as e:
                    r_("V80", ref, f"{ref}: parametri incompleți ({e})", "completați parametrii")
                if par["sablon"] in _PROT_SABLON:
                    prot_curenta[0] = (ref, par)
            else:
                tp = _TIP_PROT.get(a.get("tip"))
                if tp:      # protecție scrisă de mână: calibrul = primul curent de pe desen
                    nums = [float(x.replace(",", ".")) for x in _NR_A.findall(" ".join(a.get("spec") or []))]
                    if nums:
                        cb = re.search(r"\b([BCD])\s?(\d+)", " ".join(a.get("spec") or []))
                        prot_curenta[0] = (ref, {"sablon": tp, "In_A": nums[0], "curba": cb.group(1) if cb else "C"})
                ns, nl = _numere_A(a.get("spec") or []), _numere_A(a.get("lista") or [])
                if ns and nl and not (ns & nl):
                    r_("V80", ref, f"{ref}: valorile de pe desen ({', '.join(a.get('spec') or [])}) nu apar în lista de echipamente",
                       "aduceți desenul și lista la aceleași valori")
        # cablul ramurii e protejat de ultima protecție dinaintea lui (din ramură sau din amonte)
        for key in ("cablu_ca", "cablu"):
            cp = (b.get(key) or {}).get("param") or {}
            if cp.get("S_faza_mm2") and prot_curenta[0]:
                pref, pp = prot_curenta[0]
                prot = {"tip": _PROT_SABLON[pp["sablon"]], "In_A": pp.get("In_A"), "Ir_A": pp.get("Ir_A"), "curba": pp.get("curba")}
                for v in verifica_cablu(cp, prot, f"{(b.get(key) or {}).get('ref') or 'cablu'} ({pref})"):
                    if v.get("nivel") == "BLOCANT":
                        out.append(v)
            cb = b.get(key) or {}
            if not cp.get("S_faza_mm2") and cb.get("text") and prot_curenta[0]:
                # cablu scris de mână (fără parametri): se citește secțiunea din text și se verifică în ipoteza cea mai
                # probabilă din denumirea cablului (material, izolație, armare → pozare); se blochează dacă nu rezistă
                cp2 = _cablu_din_text(cb["text"])
                if cp2:
                    pref, pp = prot_curenta[0]
                    prot = {"tip": _PROT_SABLON[pp["sablon"]], "In_A": pp.get("In_A"), "Ir_A": pp.get("Ir_A"), "curba": pp.get("curba")}
                    for v in verifica_cablu(cp2, prot, f"{cb.get('ref') or 'cablu'} ({pref}, citit din text)"):
                        if v.get("nivel") == "BLOCANT" and v.get("cod") in ("V02", "V03"):
                            out.append(v)
        amonte = prot_curenta[0]
        for i, c in enumerate(b.get("copii") or []):
            prot_curenta[0] = amonte
            br(c, f"{cale}.{i + 1}")
        prot_curenta[0] = amonte
    intrari = m.get("intrari") or []
    for i, b in enumerate(intrari):
        prot_curenta[0] = None
        br(b, f"i{i}")
    prot_in = prot_curenta[0] if len(intrari) == 1 else None    # protecția de intrare protejează plecările fără protecție proprie
    for i, b in enumerate(m.get("plecari") or []):
        prot_curenta[0] = prot_in
        br(b, f"p{i}")
    return out


def valideaza(model):
    """{blocheaza, verificari, info, presupus, ipoteze, calculat} — verificările BLOCANT + AVERTISMENT ale calculului
    și ale topologiei desenului"""
    m, r = pregateste(model)
    ver, info, presupus, ipoteze = [], [], [], []
    if r is not None:
        ver += r.get("verificari") or []
        info += r.get("info") or []
        presupus = r.get("presupus") or []
        ipoteze = r.get("ipoteze") or []
    else:
        ver.append({"cod": "V00", "nivel": "AVERTISMENT", "obiect": "schema",
                    "mesaj": "Schemă desenată manual: dimensionarea nu este verificată de aplicație.",
                    "remediere": "Generează schema din tab-ul Calcul (sau din „Schemă nouă”) ca să fie dimensionată și verificată."})
        ver += _consistenta_manual(m)
    try:
        cv = layout.build(m)
        ver += topologie.verifica_topologie(m, cv)
        sc = (cv.meta or {}).get("scara") or 1
        if sc < 0.6 and (m.get("plecari") or []):
            # textul de bază (2,1–2,8 mm) ajunge sub ~1,3 mm la mărimea reală a formatului
            fmt_ = "A1" if cv.w > 800 else "A2" if cv.w > 500 else "A3"
            ver.append({"cod": "V95", "nivel": "AVERTISMENT", "obiect": "planșa",
                        "mesaj": f"planșa e greu lizibilă: schema e redusă la {round(sc * 100)} % pe {fmt_} (text ≈ {sc * 2.1:.1f} mm)",
                        "remediere": "împarte tabloul (ex. un tablou secundar pe etaj, pe planșă separată) sau grupează circuitele"})
    except Exception as e:
        ver.append({"cod": "V00", "nivel": "BLOCANT", "obiect": "schema", "mesaj": f"desenul nu poate fi generat: {e}",
                    "remediere": "corectați datele"})
    blocheaza = any(v.get("nivel") == "BLOCANT" for v in ver)
    return {"blocheaza": blocheaza, "verificari": ver, "info": info, "presupus": presupus, "ipoteze": ipoteze,
            "calculat": r is not None, "rezultat": (r or {}).get("rezultat")}
